static int cuda_ensure_graph_nodes(BnCudaCtx *ctx, int need) {
    if (!ctx || need <= ctx->exec_nodes_cap) return ctx ? 0 : -1;
    int cap = ctx->exec_nodes_cap ? ctx->exec_nodes_cap * 2 : 256;
    while (cap < need) cap *= 2;
    cudaGraphNode_t *nodes = (cudaGraphNode_t *)realloc(
        ctx->exec_nodes, (size_t)cap * sizeof(cudaGraphNode_t));
    if (!nodes) return -1;
    ctx->exec_nodes = nodes;
    BnCudaGraphArgs *args = (BnCudaGraphArgs *)realloc(
        ctx->exec_node_args, (size_t)cap * sizeof(BnCudaGraphArgs));
    if (!args) return -1;
    memset(args + ctx->exec_nodes_cap, 0,
           (size_t)(cap - ctx->exec_nodes_cap) * sizeof(BnCudaGraphArgs));
    ctx->exec_node_args = args;
    ctx->exec_nodes_cap = cap;
    return 0;
}

/* Decode replays the same graph with a few moving KV offsets and lengths.
 * Compare the full launch contract before paying for a CUDA node update. */
static int cuda_graph_args_match(const BnCudaGraphArgs *saved,
                                 const cudaKernelNodeParams *params,
                                 void *const *values, const size_t *sizes,
                                 size_t count) {
    size_t offset = 0;
    if (!saved || !saved->data) return 0;
    if (saved->func != params->func ||
        saved->grid[0] != params->gridDim.x ||
        saved->grid[1] != params->gridDim.y ||
        saved->grid[2] != params->gridDim.z ||
        saved->block[0] != params->blockDim.x ||
        saved->block[1] != params->blockDim.y ||
        saved->block[2] != params->blockDim.z ||
        saved->shared != params->sharedMemBytes)
        return 0;
    for (size_t i = 0; i < count; i++) {
        if (offset > saved->size || sizes[i] > saved->size - offset ||
            memcmp(saved->data + offset, values[i], sizes[i]) != 0)
            return 0;
        offset += sizes[i];
    }
    return offset == saved->size;
}

static int cuda_graph_args_save(BnCudaGraphArgs *saved,
                                const cudaKernelNodeParams *params,
                                void *const *values, const size_t *sizes,
                                size_t count) {
    size_t total = 0;
    for (size_t i = 0; i < count; i++) total += sizes[i];
    if (saved->size != total || !saved->data) {
        unsigned char *data = (unsigned char *)realloc(saved->data, total);
        if (!data) return -1;
        saved->data = data;
        saved->size = total;
    }
    size_t offset = 0;
    for (size_t i = 0; i < count; i++) {
        memcpy(saved->data + offset, values[i], sizes[i]);
        offset += sizes[i];
    }
    saved->func = params->func;
    saved->grid[0] = params->gridDim.x;
    saved->grid[1] = params->gridDim.y;
    saved->grid[2] = params->gridDim.z;
    saved->block[0] = params->blockDim.x;
    saved->block[1] = params->blockDim.y;
    saved->block[2] = params->blockDim.z;
    saved->shared = params->sharedMemBytes;
    return 0;
}

template <typename Kernel, typename... Args>
static int cuda_dispatch_kernel(BnCudaCtx *ctx, int graph_exec,
                                int graph_building, int graph_update_node,
                                Kernel kernel,
                                dim3 grid, dim3 block, size_t shared,
                                Args... args) {
    if (!graph_exec) {
        kernel<<<grid, block, shared, ctx->exec_stream>>>(args...);
        return 0;
    }

    if (!graph_building && !graph_update_node) {
        if (ctx->exec_node_cursor >= ctx->exec_node_count) {
            fprintf(stderr,
                    "[bn:gpu:cuda] graph replay node count mismatch\n");
            return -1;
        }
        ctx->exec_node_cursor++;
        return 0;
    }

    void *arg_ptrs[] = { (void *)&args... };
    const size_t arg_sizes[] = { sizeof(Args)... };
    const size_t arg_count = sizeof...(Args);
    cudaKernelNodeParams params;
    memset(&params, 0, sizeof(params));
    params.func = (void *)kernel;
    params.gridDim = grid;
    params.blockDim = block;
    params.sharedMemBytes = shared;
    params.kernelParams = arg_ptrs;

    cudaError_t err;
    if (graph_building) {
        if (cuda_ensure_graph_nodes(ctx, ctx->exec_node_count + 1) != 0)
            return -1;
        cudaGraphNode_t dep = NULL;
        const cudaGraphNode_t *deps = NULL;
        size_t n_deps = 0;
        if (ctx->exec_node_count > 0) {
            dep = ctx->exec_nodes[ctx->exec_node_count - 1];
            deps = &dep;
            n_deps = 1;
        }
        err = cudaGraphAddKernelNode(
            &ctx->exec_nodes[ctx->exec_node_count], ctx->exec_graph_def,
            deps, n_deps, &params);
        if (err != cudaSuccess) {
            fprintf(stderr, "[bn:gpu:cuda] graph add kernel failed: %s\n",
                    cudaGetErrorString(err));
            return -1;
        }
        if (graph_update_node &&
            cuda_graph_args_save(&ctx->exec_node_args[ctx->exec_node_count],
                                 &params, arg_ptrs, arg_sizes,
                                 arg_count) != 0)
            return -1;
        ctx->exec_node_count++;
    } else {
        if (ctx->exec_node_cursor >= ctx->exec_node_count) {
            fprintf(stderr,
                    "[bn:gpu:cuda] graph update node count mismatch\n");
            return -1;
        }
        if (graph_update_node) {
            BnCudaGraphArgs *saved =
                &ctx->exec_node_args[ctx->exec_node_cursor];
            if (!cuda_graph_args_match(saved, &params, arg_ptrs, arg_sizes,
                                       arg_count)) {
                err = cudaGraphExecKernelNodeSetParams(
                    ctx->exec_graph, ctx->exec_nodes[ctx->exec_node_cursor],
                    &params);
                if (err != cudaSuccess) {
                    fprintf(stderr,
                            "[bn:gpu:cuda] graph set kernel failed: %s\n",
                            cudaGetErrorString(err));
                    return -1;
                }
                if (cuda_graph_args_save(saved, &params, arg_ptrs, arg_sizes,
                                         arg_count) != 0)
                    return -1;
            }
        }
        ctx->exec_node_cursor++;
    }
    return 0;
}

#define BN_CUDA_LAUNCH_EX(ctx, dynamic, kernel, grid, block, shared, ...) do { \
    if (cuda_dispatch_kernel((ctx), graph_exec, graph_building, (dynamic), \
                             (kernel), dim3(grid), dim3(block), (shared), \
                             __VA_ARGS__) != 0) return -1; \
} while (0)

#define BN_CUDA_LAUNCH(ctx, kernel, grid, block, shared, ...) \
    BN_CUDA_LAUNCH_EX(ctx, 1, kernel, grid, block, shared, __VA_ARGS__)

#define BN_CUDA_LAUNCH_STATIC(ctx, kernel, grid, block, shared, ...) \
    BN_CUDA_LAUNCH_EX(ctx, graph_static_params ? 0 : 1, kernel, grid, block, shared, __VA_ARGS__)

#define BN_CUDA_LAUNCH_STABLE(ctx, stable, kernel, grid, block, shared, ...) do { \
    if ((stable) && graph_static_params) { \
        BN_CUDA_LAUNCH_STATIC(ctx, kernel, grid, block, shared, __VA_ARGS__); \
    } else { \
        BN_CUDA_LAUNCH(ctx, kernel, grid, block, shared, __VA_ARGS__); \
    } \
} while (0)

static int cuda_ctx_set_device(BnCudaCtx *ctx) {
    if (!ctx) return -1;
    cudaError_t err = cudaSetDevice(ctx->device);
    if (err != cudaSuccess) {
        fprintf(stderr, "[bn:gpu:cuda] failed to select device %d: %s\n",
                ctx->device, cudaGetErrorString(err));
        return -1;
    }
    return 0;
}

static double cuda_wall_ms(void) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (double)ts.tv_sec * 1000.0 + (double)ts.tv_nsec / 1000000.0;
}

