    if (warp != 0) return;

    int selected[BN_MAX_MOE_K];
    float selected_logits[BN_MAX_MOE_K];
    for (int i = 0; i < k; i++) {
        int local_best = -1;
        float local_best_val = -INFINITY;
        for (int e = lane; e < n_experts; e += 32) {
            int used = 0;
            for (int j = 0; j < i; j++) {
                if (selected[j] == e) {
                    used = 1;
                    break;
                }
            }
            if (used) continue;
            float v = logits[e];
            if (v > local_best_val) {
                local_best_val = v;
                local_best = e;
            }
        }
        for (int offset = 16; offset > 0; offset >>= 1) {
            float other_val =
                __shfl_down_sync(0xffffffffu, local_best_val, offset);
            int other = __shfl_down_sync(0xffffffffu, local_best, offset);
            if (other_val > local_best_val ||
                (other_val == local_best_val &&
                 other >= 0 && (local_best < 0 || other < local_best))) {
                local_best_val = other_val;
                local_best = other;
            }
        }
        int best = __shfl_sync(0xffffffffu, local_best, 0);
        float best_val = __shfl_sync(0xffffffffu, local_best_val, 0);
        selected[i] = best < 0 ? 0 : best;
        selected_logits[i] = best_val;
    }

    if (lane != 0) return;
    float max_selected = selected_logits[0];
    for (int i = 1; i < k; i++)
        if (selected_logits[i] > max_selected)
            max_selected = selected_logits[i];
    float max_all = max_selected;
    if (!norm_topk) {
        max_all = logits[0];
        for (int e = 1; e < n_experts; e++)
            if (logits[e] > max_all)
                max_all = logits[e];
    }
    float sum = 0.0f;
    if (norm_topk) {
        for (int i = 0; i < k; i++) {
            float w = expf(selected_logits[i] - max_selected);
            weights[(size_t)token * (size_t)k + (size_t)i] = w;
            sum += w;
        }
    } else {
        for (int e = 0; e < n_experts; e++)
            sum += expf(logits[e] - max_all);
        for (int i = 0; i < k; i++)
            weights[(size_t)token * (size_t)k + (size_t)i] =
                expf(selected_logits[i] - max_all);
    }
    if (sum > 0.0f) {
        for (int i = 0; i < k; i++)
            weights[(size_t)token * (size_t)k + (size_t)i] /= sum;
    }
    if (expert_weights_scale != 0.0f && expert_weights_scale != 1.0f) {
        for (int i = 0; i < k; i++)
            weights[(size_t)token * (size_t)k + (size_t)i] *=
                expert_weights_scale;
    }
    for (int i = 0; i < k; i++)
        indices[(size_t)token * (size_t)k + (size_t)i] = selected[i];
}

static __global__ void moe_route_count_experts_kernel(
    int *counts, const int *indices, int route_items, int n_experts) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= route_items) return;
    int e = indices[idx];
    if (e >= 0 && e < n_experts)
        atomicAdd(counts + e, 1);
}

static __global__ void moe_route_offsets_kernel(
    int *offsets, int *fill, const int *counts, int n_experts) {
    if (blockIdx.x != 0 || threadIdx.x != 0) return;
    int sum = 0;
    for (int e = 0; e < n_experts; e++) {
        offsets[e] = sum;
        fill[e] = sum;
        sum += counts[e];
    }
}

static __global__ void moe_route_fill_slots_kernel(
    int *slot_order, int *fill, const int *indices, int route_items,
    int n_experts) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= route_items) return;
    int e = indices[idx];
    if (e < 0 || e >= n_experts) return;
    int pos = atomicAdd(fill + e, 1);
    slot_order[pos] = idx;
}

/* A fixed upper-bound launch skips unpopulated route tiles on device. */
static __global__ void moe_route_compact_schedule_kernel(
        int *schedule, const int *counts, int n_experts) {
    if (blockIdx.x || threadIdx.x) return;
    int used = 0;
    for (int expert = 0; expert < n_experts; expert++)
        for (int tile = 0; tile * 64 < counts[expert]; tile++)
            schedule[1 + used++] = expert | (tile << 16);
    schedule[0] = used;
}

static __global__ void moe_route_topk_warp_kernel(float *route,
                                                  const float *logits,
                                                  int n_experts,
                                                  int k,
                                                  int norm_topk,
                                                  float expert_weights_scale,
                                                  int separate_routing) {
    int lane = threadIdx.x & 31;
    if (blockIdx.x != 0 || threadIdx.x >= 32) return;
    if (n_experts <= 0 || k <= 0) return;
    if (k > BN_MAX_MOE_K) k = BN_MAX_MOE_K;

    if (n_experts >= 32 && n_experts <= 512 && (n_experts & (n_experts-1)) == 0) {
        cuda_route_softmax_topk_warp(route, NULL, route + k, logits,
            n_experts, k, norm_topk, expert_weights_scale,
            separate_routing);
        return;
    }
    int selected[BN_MAX_MOE_K];
    float selected_logits[BN_MAX_MOE_K];
    for (int i = 0; i < k; i++) {
        int local_best = -1;
        float local_best_val = -INFINITY;
        for (int e = lane; e < n_experts; e += 32) {
            int used = 0;
            for (int j = 0; j < i; j++) {
                if (selected[j] == e) {
                    used = 1;
                    break;
                }
            }
            if (used) continue;
            float v = logits[e];
            if (v > local_best_val) {
                local_best_val = v;
                local_best = e;
            }
        }
        for (int offset = 16; offset > 0; offset >>= 1) {
            float other_val =
                __shfl_down_sync(0xffffffffu, local_best_val, offset);
            int other =
                __shfl_down_sync(0xffffffffu, local_best, offset);
            if (other_val > local_best_val ||
                (other_val == local_best_val &&
                 other >= 0 && (local_best < 0 || other < local_best))) {
                local_best_val = other_val;
                local_best = other;
            }
        }
        int best = __shfl_sync(0xffffffffu, local_best, 0);
        float best_val = __shfl_sync(0xffffffffu, local_best_val, 0);
        selected[i] = best < 0 ? 0 : best;
        selected_logits[i] = best_val;
    }

    float max_selected = selected_logits[0];
    for (int i = 1; i < k; i++)
        if (selected_logits[i] > max_selected)
            max_selected = selected_logits[i];
    float max_all = max_selected;
    if (!norm_topk) {
        float local_max = -INFINITY;
        for (int e = lane; e < n_experts; e += 32)
            if (logits[e] > local_max)
                local_max = logits[e];
        for (int offset = 16; offset > 0; offset >>= 1) {
            float other = __shfl_down_sync(0xffffffffu, local_max, offset);
            if (other > local_max)
                local_max = other;
        }
        max_all = __shfl_sync(0xffffffffu, local_max, 0);
    }
    float sum = 0.0f;
    if (norm_topk) {
        if (lane != 0) return;
        for (int i = 0; i < k; i++) {
            float w = expf(selected_logits[i] - max_selected);
            route[i] = w;
            sum += w;
        }
    } else {
        float local_sum = 0.0f;
        for (int e = lane; e < n_experts; e += 32)
            local_sum += expf(logits[e] - max_all);
        for (int offset = 16; offset > 0; offset >>= 1)
            local_sum += __shfl_down_sync(0xffffffffu, local_sum, offset);
        sum = __shfl_sync(0xffffffffu, local_sum, 0);
        if (lane != 0) return;
        for (int i = 0; i < k; i++)
            route[i] = expf(selected_logits[i] - max_all);
    }
    if (sum > 0.0f) {
        for (int i = 0; i < k; i++)
            route[i] /= sum;
    }
    if (expert_weights_scale != 0.0f && expert_weights_scale != 1.0f) {
        for (int i = 0; i < k; i++)
            route[i] *= expert_weights_scale;
    }
    for (int i = 0; i < k; i++)
        route[k + i] = (float)selected[i];
}

/* Spread the independent exponentials over four warps, then retain the
 * reference warp's accumulation and selection order for exact routing. */
static __global__ void moe_route_topk_128_kernel(
    float *route, const float *logits, int k, int norm_topk,
    float expert_weights_scale) {
    __shared__ float probabilities_shared[128];
    __shared__ float maximum_shared;
    int tid = threadIdx.x;
    int lane = tid & 31;
    int warp = tid >> 5;
    if (blockIdx.x != 0 || tid >= 128 || k <= 0) return;
    if (k > BN_MAX_MOE_K) k = BN_MAX_MOE_K;

    if (warp == 0) {
        float maximum = -INFINITY;
#pragma unroll
        for (int i = 0; i < 4; i++)
            maximum = fmaxf(maximum, logits[lane + i * 32]);
        for (int offset = 16; offset; offset >>= 1)
            maximum = fmaxf(maximum,
                __shfl_xor_sync(0xffffffffu, maximum, offset));
        if (lane == 0) maximum_shared = maximum;
    }
    __syncthreads();
    probabilities_shared[tid] = __expf(logits[tid] - maximum_shared);
    __syncthreads();
    if (warp != 0) return;

    float probabilities[4];
    float sum = 0.0f;
#pragma unroll
    for (int i = 0; i < 4; i++) {
        probabilities[i] = probabilities_shared[lane + i * 32];
        sum += probabilities[i];
    }
    for (int offset = 16; offset; offset >>= 1)
        sum += __shfl_xor_sync(0xffffffffu, sum, offset);
    float inverse = __fdividef(1.0f, sum);
#pragma unroll
    for (int i = 0; i < 4; i++) {
        probabilities[i] *= inverse;
        if (isnan(probabilities[i])) probabilities[i] = -FLT_MAX;
    }

    float selected_sum = 0.0f;
    float output_weight = 0.0f;
    int output_id = 0;
    for (int selected = 0; selected < k; selected++) {
        float best_value = probabilities[0];
        int best_id = lane;
#pragma unroll
        for (int i = 1; i < 4; i++) {
            if (probabilities[i] > best_value) {
                best_value = probabilities[i];
                best_id = lane + i * 32;
            }
        }
        for (int offset = 16; offset; offset >>= 1) {
            float other_value =
                __shfl_xor_sync(0xffffffffu, best_value, offset);
            int other_id = __shfl_xor_sync(0xffffffffu, best_id, offset);
            if (other_value > best_value ||
                (other_value == best_value && other_id < best_id)) {
                best_value = other_value;
                best_id = other_id;
            }
        }
        if ((best_id & 31) == lane) {
            probabilities[best_id / 32] = -INFINITY;
            selected_sum += best_value;
        }
        if (lane == selected) {
            output_weight = best_value;
            output_id = best_id;
        }
    }
    if (norm_topk) {
        for (int offset = 16; offset; offset >>= 1)
            selected_sum +=
                __shfl_xor_sync(0xffffffffu, selected_sum, offset);
        output_weight *= __fdividef(
            1.0f, fmaxf(selected_sum, 6.103515625e-5f));
    }
    if (lane < k) {
        if (expert_weights_scale != 0.0f &&
            expert_weights_scale != 1.0f)
            output_weight *= expert_weights_scale;
        route[lane] = output_weight;
        route[k + lane] = (float)output_id;
    }
}

