static __global__ void moe_route_diff2_warp_kernel(float *route,
                                                   const float *router_diff,
                                                   const float *x,
                                                   int dim,
                                                   float expert_weights_scale) {
    int lane = threadIdx.x & 31;
    float sum = 0.0f;
    for (int d = lane; d < dim; d += 32)
        sum += router_diff[d] * x[d];
    for (int offset = 16; offset > 0; offset >>= 1)
        sum += __shfl_down_sync(0xffffffffu, sum, offset);
    if (lane == 0) {
        float w0 = 1.0f / (1.0f + expf(-sum));
        float w1 = 1.0f - w0;
        if (expert_weights_scale != 0.0f && expert_weights_scale != 1.0f) {
            w0 *= expert_weights_scale;
            w1 *= expert_weights_scale;
        }
        if (w1 > w0) {
            route[0] = w1;
            route[1] = w0;
            route[2] = 1.0f;
            route[3] = 0.0f;
        } else {
            route[0] = w0;
            route[1] = w1;
            route[2] = 0.0f;
            route[3] = 1.0f;
        }
    }
}

static __device__ __forceinline__ float cuda_router_dot_avx2_lane(
    const float *row, const float *x, int dim, int lane16) {
    int lane8 = lane16 & 7;
    int base = (lane16 >> 3) * 8 + lane8;
    float sum = 0.0f;
    for (int d = base; d < dim; d += 16)
        sum = __fmaf_rn(row[d], x[d], sum);
    return sum;
}

static __device__ __forceinline__ float cuda_router_avx2_hsum16(
    const float *partials) {
    float v0 = partials[0] + partials[8];
    float v1 = partials[1] + partials[9];
    float v2 = partials[2] + partials[10];
    float v3 = partials[3] + partials[11];
    float v4 = partials[4] + partials[12];
    float v5 = partials[5] + partials[13];
    float v6 = partials[6] + partials[14];
    float v7 = partials[7] + partials[15];
    float h0 = v0 + v4;
    float h1 = v1 + v5;
    float h2 = v2 + v6;
    float h3 = v3 + v7;
    return (h0 + h1) + (h2 + h3);
}

static __global__ void moe_route_all_active_two_avx2_quantize_q8k_kernel(
    float *route,
    BnBlockQ8K *xq,
    const float *router,
    const float *x,
    int dim,
    float expert_weights_scale,
    int norm_topk_prob) {
    int tid = threadIdx.x;
    if (blockIdx.x == 0) {
        __shared__ float partial[2][16];
        if (tid < 16) {
            partial[0][tid] =
                cuda_router_dot_avx2_lane(router, x, dim, tid);
            partial[1][tid] =
                cuda_router_dot_avx2_lane(router + (size_t)dim, x, dim, tid);
        }
        __syncthreads();
        if (tid == 0) {
            float l0 = cuda_router_avx2_hsum16(partial[0]);
            float l1 = cuda_router_avx2_hsum16(partial[1]);
            float max_val = l0 > l1 ? l0 : l1;
            float w0 = expf(l0 - max_val);
            float w1 = expf(l1 - max_val);
            float denom = w0 + w1;
            if (denom > 0.0f) {
                w0 /= denom;
                w1 /= denom;
            }
            if (norm_topk_prob) {
                float wsum = w0 + w1;
                if (wsum > 0.0f) {
                    w0 /= wsum;
                    w1 /= wsum;
                }
            }
            if (expert_weights_scale != 0.0f &&
                expert_weights_scale != 1.0f) {
                w0 *= expert_weights_scale;
                w1 *= expert_weights_scale;
            }
            if (w1 > w0) {
                route[0] = w1;
                route[1] = w0;
                route[2] = 1.0f;
                route[3] = 0.0f;
            } else {
                route[0] = w0;
                route[1] = w1;
                route[2] = 0.0f;
                route[3] = 1.0f;
            }
        }
        return;
    }

    int block = blockIdx.x - 1;
    if (tid >= BN_QK_K) return;
    int n_blocks = (dim + BN_QK_K - 1) / BN_QK_K;
    if (block >= n_blocks) return;
    int c = block * BN_QK_K + tid;
    float v = c < dim ? x[c] : 0.0f;

    __shared__ float amax_s[BN_QK_K];
    __shared__ int q_s[BN_QK_K];
    amax_s[tid] = fabsf(v);
    __syncthreads();
    for (int stride = BN_QK_K / 2; stride > 0; stride >>= 1) {
        if (tid < stride)
            amax_s[tid] = fmaxf(amax_s[tid], amax_s[tid + stride]);
        __syncthreads();
    }

    float d = amax_s[0] / 127.0f;
    int q = d == 0.0f ? 0 : (int)roundf(v / d);
    q = q < -128 ? -128 : (q > 127 ? 127 : q);
    q_s[tid] = q;
    BnBlockQ8K *dst = xq + block;
    dst->qs[tid] = (int8_t)q;
    __syncthreads();
    if (tid < BN_QK_K / 16) {
        int sum = 0;
#pragma unroll
        for (int i = 0; i < 16; i++)
            sum += q_s[tid * 16 + i];
        dst->bsums[tid] = (int16_t)sum;
    }
    if (tid == 0)
        dst->d = d;
}

static __global__ void moe_route_diff2_quantize_q8k_kernel(
    float *route,
    BnBlockQ8K *xq,
    const float *router_diff,
    const float *x,
    int dim,
    float expert_weights_scale) {
    int tid = threadIdx.x;
    if (blockIdx.x == 0) {
        if (tid >= 32) return;
        float sum = 0.0f;
        for (int d = tid; d < dim; d += 32)
            sum += router_diff[d] * x[d];
        for (int offset = 16; offset > 0; offset >>= 1)
            sum += __shfl_down_sync(0xffffffffu, sum, offset);
        if (tid == 0) {
            float w0 = 1.0f / (1.0f + expf(-sum));
            float w1 = 1.0f - w0;
            if (expert_weights_scale != 0.0f &&
                expert_weights_scale != 1.0f) {
                w0 *= expert_weights_scale;
                w1 *= expert_weights_scale;
            }
            if (w1 > w0) {
                route[0] = w1;
                route[1] = w0;
                route[2] = 1.0f;
                route[3] = 0.0f;
            } else {
                route[0] = w0;
                route[1] = w1;
                route[2] = 0.0f;
                route[3] = 1.0f;
            }
        }
        return;
    }

    int block = blockIdx.x - 1;
    if (tid >= BN_QK_K) return;
    int n_blocks = (dim + BN_QK_K - 1) / BN_QK_K;
    if (block >= n_blocks) return;
    int c = block * BN_QK_K + tid;
    float v = c < dim ? x[c] : 0.0f;

    __shared__ float amax_s[BN_QK_K];
    __shared__ int q_s[BN_QK_K];
    amax_s[tid] = fabsf(v);
    __syncthreads();
    for (int stride = BN_QK_K / 2; stride > 0; stride >>= 1) {
        if (tid < stride)
            amax_s[tid] = fmaxf(amax_s[tid], amax_s[tid + stride]);
        __syncthreads();
    }

    float d = amax_s[0] / 127.0f;
    int q = d == 0.0f ? 0 : (int)roundf(v / d);
    q = q < -128 ? -128 : (q > 127 ? 127 : q);
    q_s[tid] = q;
    BnBlockQ8K *dst = xq + block;
    dst->qs[tid] = (int8_t)q;
    __syncthreads();
    if (tid < BN_QK_K / 16) {
        int sum = 0;
#pragma unroll
        for (int i = 0; i < 16; i++)
            sum += q_s[tid * 16 + i];
        dst->bsums[tid] = (int16_t)sum;
    }
    if (tid == 0)
        dst->d = d;
}

static __global__ void moe_route_diff2_quantize_q8_1_kernel(
    float *route,
    BnCudaBlockQ8_1 *xq,
    const float *router_diff,
    const float *x,
    int dim,
    float expert_weights_scale) {
    int tid = threadIdx.x;
    if (blockIdx.x == 0) {
        if (tid >= 32) return;
        float sum = 0.0f;
        for (int d = tid; d < dim; d += 32)
            sum += router_diff[d] * x[d];
        for (int offset = 16; offset > 0; offset >>= 1)
            sum += __shfl_down_sync(0xffffffffu, sum, offset);
        if (tid == 0) {
            float w0 = 1.0f / (1.0f + expf(-sum));
            float w1 = 1.0f - w0;
            if (expert_weights_scale != 0.0f &&
                expert_weights_scale != 1.0f) {
                w0 *= expert_weights_scale;
                w1 *= expert_weights_scale;
            }
            if (w1 > w0) {
                route[0] = w1;
                route[1] = w0;
                route[2] = 1.0f;
                route[3] = 0.0f;
            } else {
                route[0] = w0;
                route[1] = w1;
                route[2] = 0.0f;
                route[3] = 1.0f;
            }
        }
        return;
    }

    int block = blockIdx.x - 1;
    int c = block * 32 + tid;
    float v = c < dim ? x[c] : 0.0f;
    float amax = fabsf(v);
    for (int offset = 16; offset > 0; offset >>= 1) {
        amax = fmaxf(amax, __shfl_down_sync(0xffffffffu, amax, offset));
    }
    amax = __shfl_sync(0xffffffffu, amax, 0);
    float d = amax / 127.0f;
    int q = d == 0.0f ? 0 : (int)roundf(v / d);
    q = q < -128 ? -128 : (q > 127 ? 127 : q);
    int qsum = q;
    for (int offset = 16; offset > 0; offset >>= 1)
        qsum += __shfl_down_sync(0xffffffffu, qsum, offset);

    BnCudaBlockQ8_1 *dst = xq + block;
    dst->qs[tid] = (int8_t)q;
    if (tid == 0) {
        dst->d = cuda_fp32_to_fp16_bits(d);
        dst->qsum = (int16_t)qsum;
    }
}

static __global__ void moe_q4k_gateup_routed_mid_kernel(
    float *mid,
    const BnBlockQ4K *gate,
    const BnBlockQ4K *up,
    const BnCudaBlockQ8_1 *xq,
    const float *route,
    int hidden,
    int cols,
    int n_experts,
    int k) {
    int lane = threadIdx.x & 31;
    int warp = threadIdx.x >> 5;
    int warps_per_block = blockDim.x >> 5;
    int task = blockIdx.x * warps_per_block + warp;
    if (task >= hidden * k) return;

    int slot = task / hidden;
    int row = task - slot * hidden;
    int expert = (int)(route[k + slot] + 0.5f);
    if (expert < 0) expert = 0;
    if (expert >= n_experts) expert = n_experts - 1;

    int n_bpr = cols / BN_QK_K;
    int kbx = lane / 16;
    int iqs = 2 * (lane & 15);
    size_t expert_row = ((size_t)expert * (size_t)hidden + (size_t)row);
    const BnBlockQ4K *gate_blocks = gate + expert_row * (size_t)n_bpr;
    const BnBlockQ4K *up_blocks = up + expert_row * (size_t)n_bpr;
    float gate_sum = 0.0f;
    float up_sum = 0.0f;
    for (int b = kbx; b < n_bpr; b += 2) {
        const BnCudaBlockQ8_1 *xqb = xq + (size_t)b * 8;
        gate_sum += cuda_vec_dot_q4k_q8_1(&gate_blocks[b], xqb, iqs);
        up_sum += cuda_vec_dot_q4k_q8_1(&up_blocks[b], xqb, iqs);
    }
    for (int offset = 16; offset > 0; offset >>= 1) {
        gate_sum += __shfl_down_sync(0xffffffffu, gate_sum, offset);
        up_sum += __shfl_down_sync(0xffffffffu, up_sum, offset);
    }
    if (lane == 0) {
        float silu = gate_sum / (1.0f + __expf(-gate_sum));
        mid[(size_t)slot * (size_t)hidden + (size_t)row] =
            silu * up_sum;
    }
}

/* Match llama.cpp's single-token MUL_MAT_ID schedule: four warps split the
 * Q4_K blocks for one expert row, then warp zero folds the other partials
 * lane-wise before the final XOR reduction. */
static __global__ void moe_q4k_gateup_routed_mid_4warp_kernel(
    float *mid, const BnBlockQ4K *gate, const BnBlockQ4K *up,
    const BnCudaBlockQ8_1 *xq, const float *route, int hidden, int cols,
    int n_experts, int k) {
    int lane = threadIdx.x & 31;
    int warp = threadIdx.x >> 5;
    int task = blockIdx.x;
    if (task >= hidden * k) return;

    int slot = task / hidden;
    int row = task - slot * hidden;
    int expert = (int)(route[k + slot] + 0.5f);
    expert = expert < 0 ? 0 : (expert >= n_experts ? n_experts - 1 : expert);
    int n_bpr = cols / BN_QK_K;
    size_t expert_row = (size_t)expert * (size_t)hidden + (size_t)row;
    const BnBlockQ4K *gate_blocks = gate + expert_row * (size_t)n_bpr;
    const BnBlockQ4K *up_blocks = up + expert_row * (size_t)n_bpr;
    float gate_sum = 0.0f;
    float up_sum = 0.0f;
    int iqs = 2 * (lane & 15);
    for (int b = threadIdx.x / 16; b < n_bpr; b += 8) {
        const BnCudaBlockQ8_1 *xqb = xq + (size_t)b * 8u;
        up_sum += cuda_vec_dot_q4k_q8_1(&up_blocks[b], xqb, iqs);
        gate_sum += cuda_vec_dot_q4k_q8_1(&gate_blocks[b], xqb, iqs);
    }

    __shared__ float up_partial[3][32];
    __shared__ float gate_partial[3][32];
    if (warp > 0) {
        up_partial[warp - 1][lane] = up_sum;
        gate_partial[warp - 1][lane] = gate_sum;
    }
    __syncthreads();
    if (warp > 0) return;
#pragma unroll
    for (int w = 0; w < 3; w++) {
        up_sum += up_partial[w][lane];
        gate_sum += gate_partial[w][lane];
    }
#pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
        up_sum += __shfl_xor_sync(0xffffffffu, up_sum, offset);
        gate_sum += __shfl_xor_sync(0xffffffffu, gate_sum, offset);
    }
    if (lane == 0)
        mid[(size_t)slot * (size_t)hidden + (size_t)row] =
            cuda_silu_select(gate_sum, 1) * up_sum;
}

static __global__ void moe_q5k_gateup_routed_mid_kernel(
    float *mid, const BnBlockQ5K *gate, const BnBlockQ5K *up,
    const BnCudaBlockQ8_1 *xq, const float *route, int hidden, int cols,
    int n_experts, int k) {
    int lane = threadIdx.x & 31;
    int warp = threadIdx.x >> 5;
    int task = blockIdx.x * (blockDim.x >> 5) + warp;
    if (task >= hidden * k) return;

    int slot = task / hidden;
    int row = task - slot * hidden;
    int expert = (int)(route[k + slot] + 0.5f);
    expert = expert < 0 ? 0 : (expert >= n_experts ? n_experts - 1 : expert);
    int n_bpr = cols / BN_QK_K;
    size_t expert_row = (size_t)expert * (size_t)hidden + (size_t)row;
    const BnBlockQ5K *gate_blocks = gate + expert_row * (size_t)n_bpr;
    const BnBlockQ5K *up_blocks = up + expert_row * (size_t)n_bpr;
    float gate_sum = 0.0f;
    float up_sum = 0.0f;
    int kbx = lane / 16;
    int iqs = 2 * (lane & 15);
    for (int b = kbx; b < n_bpr; b += 2) {
        const BnCudaBlockQ8_1 *xqb = xq + (size_t)b * 8u;
        gate_sum += cuda_vec_dot_q5k_q8_1(&gate_blocks[b], xqb, iqs);
        up_sum += cuda_vec_dot_q5k_q8_1(&up_blocks[b], xqb, iqs);
    }
    for (int offset = 16; offset > 0; offset >>= 1) {
        gate_sum += __shfl_down_sync(0xffffffffu, gate_sum, offset);
        up_sum += __shfl_down_sync(0xffffffffu, up_sum, offset);
    }
    if (lane == 0)
        mid[(size_t)slot * (size_t)hidden + (size_t)row] =
            cuda_silu_relaxed_division(gate_sum) * up_sum;
}

/* Match llama.cpp's single-token MUL_MAT_ID schedule: four warps split the
