    float *mid, const BnBlockQ4K *gate, const BnBlockQ4K *up,
    const BnBlockQ8K *xq, const float *route, int hidden, int cols,
    int n_experts, int k, int uses_reference_silu) {
    int lane = threadIdx.x & 31;
    int warp = threadIdx.x >> 5;
