    up_sum += __shfl_down_sync(mask, up_sum, 2);
    up_sum += __shfl_down_sync(mask, up_sum, 1);
    if (sublane == 0) {
        float silu = cuda_silu_select(gate_sum, uses_reference_silu);
        mid[(size_t)slot * (size_t)hidden + (size_t)row] = silu * up_sum;
