    gate_sum += __shfl_down_sync(mask, gate_sum, 1);
    up_sum += __shfl_down_sync(mask, up_sum, 8);
    up_sum += __shfl_down_sync(mask, up_sum, 4);
    up_sum += __shfl_down_sync(mask, up_sum, 2);
    up_sum += __shfl_down_sync(mask, up_sum, 1);
