    ctx->d_q8_k_bytes = 0;
    cudaError_t err = cudaMalloc(&ctx->d_q8_k, bytes);
    if (err != cudaSuccess) {
        fprintf(stderr, "[bn:gpu:cuda] q8_k scratch alloc failed: %s\n",
                cudaGetErrorString(err));
        return -1;
    }
    ctx->d_q8_k_bytes = bytes;
    return 0;
}

/* Q8 MMQ schedules belong to the backend and are reused across layers.
 * Each tile lists K intervals in reference fixup order (last interval first).
 * Empty experts still participate in the global partition. */
static int cuda_prepare_q8_mmq_plan(BnCudaCtx *ctx, BnCudaQ8MmqPlan *plan,
                                        int rows, int cols, int tokens, int experts) {
    if (plan->data && plan->rows == rows && plan->cols == cols &&
        plan->tokens == tokens && plan->experts == experts) return 0;
    const int widths[] = {8,16,24,32,40,48,64,80,96,112,128};
    int jbest = 8, ntx = INT_MAX;
    for (size_t i = 0; i < sizeof(widths)/sizeof(widths[0]); i++) {
        int count = 1 + (tokens - 1) / widths[i];
        if (count < ntx) { ntx = count; jbest = widths[i]; }
    }
    int nb = cols / 32, nsm = 0;
    int64_t tiles64 = (int64_t)(1 + (rows - 1)/128) * experts;
    if (tiles64 <= 0 || tiles64 > ((INT64_C(1) << 30) - 1)/nb/ntx)
        return -1;
    tiles64 *= ntx;
    if (cudaDeviceGetAttribute(&nsm, cudaDevAttrMultiProcessorCount,
                               ctx->device) != cudaSuccess || nsm <= 0) return -1;
    int tiles = (int)tiles64;
    int waves = 1 + (tiles - 1)/nsm;
    int grid = (int64_t)100 * tiles / ((int64_t)nsm * waves) >= 90 ? tiles : nsm;
    size_t capacity = (size_t)tiles + 1 + 2*((size_t)tiles + grid);
    if (capacity > INT_MAX || capacity > SIZE_MAX / sizeof(int)) return -1;
    int *host = (int *)malloc(capacity * sizeof(int));
    if (!host) return -1;
    size_t cursor = (size_t)tiles + 1;
    int64_t total = tiles64 * nb;
    for (int tile = 0; tile < tiles; tile++) {
        host[tile] = (int)cursor;
        /* Host planning runs only when the shape changes, never per row. */
        for (int block = grid - 1; block >= 0; block--) {
            int start = (int)((int64_t)block * total / grid);
            int end = (int)((int64_t)(block + 1) * total / grid);
            start -= (start % nb) % 8; end -= (end % nb) % 8;
            int begin = start > tile*nb ? start - tile*nb : 0;
            int stop = end < (tile+1)*nb ? end - tile*nb : nb;
            if (begin >= stop) continue;
            if (cursor + 2 > capacity) { free(host); return -1; }
            host[cursor++] = begin; host[cursor++] = stop;
        }
    }
    host[tiles] = (int)cursor;
    int *device = NULL;
    cudaError_t err = cudaMalloc(&device, cursor * sizeof(int));
    if (err == cudaSuccess)
        err = cudaMemcpy(device, host, cursor * sizeof(int), cudaMemcpyHostToDevice);
    free(host);
    if (err != cudaSuccess) { cudaFree(device); return -1; }
    cudaFree(plan->data);
    plan->data = device; plan->rows = rows; plan->cols = cols;
    plan->tokens = tokens; plan->experts = experts; plan->j = jbest; plan->ntx = ntx;
    return 0;
}

static __global__ void quantize_q8_mmq_kernel(BnCudaBlockQ8_0F32 *out,
                                                   const float *x, int cols) {
    int lane = threadIdx.x, block = blockIdx.x, token = blockIdx.y;
    float v = x[(size_t)token*cols + block*32 + lane], amax = fabsf(v);
    for (int offset = 16; offset; offset >>= 1)
        amax = fmaxf(amax, __shfl_xor_sync(0xffffffffu, amax, offset));
    float inverse = amax == 0.0f ? 0.0f : __fdividef(127.0f, amax);
    BnCudaBlockQ8_0F32 *dst = out + (size_t)token*(cols/32) + block;
    dst->qs[lane] = (int8_t)roundf(v * inverse);
    if (lane == 0) dst->d = amax == 0.0f ? 0.0f : __fdividef(1.0f, inverse);
}

static __device__ float q8_mmq_row(const BnBlockQ8_0 *w,
                                        const BnCudaBlockQ8_0F32 *x,
                                        const int *schedule, int tile) {
    float last = 0.0f, fixup = 0.0f;
    int first = schedule[tile], end = schedule[tile + 1];
    for (int p = first; p < end; p += 2) {
        float partial = 0.0f;
        for (int b = schedule[p]; b < schedule[p + 1]; b++) {
            int dot = cuda_dot_i8x32_dp4a(w[b].qs, x[b].qs);
            partial = fmaf(__fmul_rn((float)dot, cuda_fp16_to_fp32(w[b].d)),
                           x[b].d, partial);
        }
        if (p == first) last = partial; else fixup += partial;
    }
    return end - first > 2 ? last + fixup : last;
}

/* A lane owns one complete schedule interval.  Lane zero combines those
 * interval sums in the same last/fixup order as q8_mmq_row. */
static __global__ void q8_mmq_dense_subwarp_kernel(
    float *out, const BnBlockQ8_0 *weight,
    const BnCudaBlockQ8_0F32 *input, const int *schedule,
    int rows, int cols, int j, int ntx, size_t out_offset) {
    int row = blockIdx.x * (blockDim.x / 8) + threadIdx.x / 8;
    int lane = threadIdx.x & 7;
    int token = blockIdx.y;
    if (row >= rows) return;
    int nb = cols / 32;
    int tile = (row / 128) * ntx + token / j;
    int first = schedule[tile], end = schedule[tile + 1];
    const BnBlockQ8_0 *w = weight + (size_t)row * nb;
    const BnCudaBlockQ8_0F32 *x = input + (size_t)token * nb;
    unsigned mask = 0xffu << (threadIdx.x & ~7);
    float last = 0.0f, fixup = 0.0f;
    for (int base = first; base < end; base += 16) {
        int p = base + lane * 2;
        float partial = 0.0f;
        if (p < end) {
            for (int b = schedule[p]; b < schedule[p + 1]; b++) {
                int dot = cuda_dot_i8x32_dp4a(w[b].qs, x[b].qs);
                partial = fmaf(
                    __fmul_rn((float)dot, cuda_fp16_to_fp32(w[b].d)),
                    x[b].d, partial);
            }
        }
#pragma unroll
        for (int source = 0; source < 8; source++) {
            float part = __shfl_sync(mask, partial, source, 8);
            int part_index = base + source * 2;
            if (lane == 0 && part_index < end) {
                if (part_index == first) last = part;
                else fixup += part;
            }
        }
    }
    if (lane == 0)
        out[out_offset + (size_t)token * rows + row] =
            end - first > 2 ? last + fixup : last;
}

/* The reference schedule has a multiple-of-eight token width. Adjacent
 * tokens therefore traverse identical K intervals, so load each four-byte
 * weight group once while preserving each token's sum order. */
template <int TokensPerTile>
static __global__ void q8_mmq_dense_subwarp_tiled_kernel(
    float *out, const BnBlockQ8_0 *weight,
    const BnCudaBlockQ8_0F32 *input, const int *schedule,
    int rows, int cols, int n_tokens, int j, int ntx, size_t out_offset) {
    int row = blockIdx.x * (blockDim.x / 8) + threadIdx.x / 8;
    int lane = threadIdx.x & 7;
    int token0 = blockIdx.y * TokensPerTile;
    if (row >= rows || token0 >= n_tokens) return;
    int nb = cols / 32;
    int tile = (row / 128) * ntx + token0 / j;
    int first = schedule[tile], end = schedule[tile + 1];
    const BnBlockQ8_0 *w = weight + (size_t)row * nb;
    const BnCudaBlockQ8_0F32 *x[TokensPerTile];
#pragma unroll
    for (int t = 0; t < TokensPerTile; t++) {
        int token = token0 + t < n_tokens ? token0 + t : token0;
        x[t] = input + (size_t)token * nb;
    }
    unsigned mask = 0xffu << (threadIdx.x & ~7);
    float last[TokensPerTile] = {0.0f};
    float fixup[TokensPerTile] = {0.0f};
    for (int base = first; base < end; base += 16) {
        int p = base + lane * 2;
        float partial[TokensPerTile] = {0.0f};
        if (p < end) {
            for (int b = schedule[p]; b < schedule[p + 1]; b++) {
                int dot[TokensPerTile] = {0};
#pragma unroll
                for (int i = 0; i < 32; i += 4) {
                    int av, bv;
                    memcpy(&av, w[b].qs + i, sizeof(av));
#pragma unroll
                    for (int t = 0; t < TokensPerTile; t++) {
                        memcpy(&bv, x[t][b].qs + i, sizeof(bv));
                        dot[t] = cuda_dp4a_i32(av, bv, dot[t]);
                    }
                }
                float wd = cuda_fp16_to_fp32(w[b].d);
#pragma unroll
                for (int t = 0; t < TokensPerTile; t++)
                    partial[t] = fmaf(
                        __fmul_rn((float)dot[t], wd), x[t][b].d, partial[t]);
            }
        }
#pragma unroll
        for (int source = 0; source < 8; source++) {
            int part_index = base + source * 2;
#pragma unroll
            for (int t = 0; t < TokensPerTile; t++) {
                float part = __shfl_sync(mask, partial[t], source, 8);
                if (lane == 0 && part_index < end) {
                    if (part_index == first) last[t] = part;
                    else fixup[t] += part;
                }
            }
        }
    }
    if (lane == 0) {
#pragma unroll
        for (int t = 0; t < TokensPerTile; t++) {
            if (token0 + t < n_tokens)
                out[out_offset + (size_t)(token0 + t) * rows + row] =
                    end - first > 2 ? last[t] + fixup[t] : last[t];
        }
    }
}

/* Small dense batches use the MMVQ activation format and reduction table. */
static __global__ void q8_0_matmul_prepared_input_kernel(
        float *out, const BnBlockQ8_0 *weights, const BnCudaBlockQ8_1 *input,
        int rows, int cols, int n_tokens, size_t out_offset) {
    int lane = threadIdx.x & 31;
    int row = blockIdx.x * (blockDim.x / 32) + threadIdx.x / 32;
    int token = blockIdx.y;
    if (row >= rows || token >= n_tokens) return;
    int n_blocks = cols / 32;
    float sum = q8_0_prepared_row_sum(
        weights + (size_t)row * n_blocks,
        input + (size_t)token * n_blocks, n_blocks, lane,
        n_tokens <= 4 ? 4 : 2);
    if (lane == 0) out[out_offset + (size_t)token * rows + row] = sum;
}

static int cuda_launch_q8_0_matmul(BnCudaCtx *ctx, float *d_dst,
                                   const BnBlockQ8_0 *blocks,
                                   const float *d_x, int rows, int cols,
                                   int n_tokens, size_t out_offset) {
    if (!ctx || !d_dst || !blocks || !d_x || rows <= 0 || cols <= 0 ||
        n_tokens <= 0 || (cols & 31) != 0)
        return -1;
    int threads = 256;
    int warps = threads / 32;
    if (n_tokens <= 8) {
        if (cols > INT_MAX / n_tokens ||
            cuda_ensure_q8_1(ctx, cols * n_tokens) != 0) return -1;
        BnCudaBlockQ8_1 *input = (BnCudaBlockQ8_1 *)ctx->d_q8_1;
        quantize_q8_1_batch_kernel<<<dim3(cols / 32, n_tokens), 32>>>(
            input, d_x, cols, n_tokens);
        if (cudaGetLastError() != cudaSuccess) return -1;
        dim3 grid(rows / warps + (rows % warps != 0), n_tokens);
        q8_0_matmul_prepared_input_kernel<<<grid, threads>>>(
            d_dst, blocks, input, rows, cols, n_tokens, out_offset);
        return cudaGetLastError() == cudaSuccess ? 0 : -1;
    }
    if (ctx->compute_capability == 1200 && n_tokens <= 65535) {
        BnCudaQ8MmqPlan *plan = &ctx->dense_mmq_plan;
        if (cuda_prepare_q8_mmq_plan(ctx, plan, rows, cols, n_tokens, 1) != 0 ||
            cuda_ensure_q8_0_f32(ctx, cols, n_tokens) != 0) return -1;
        BnCudaBlockQ8_0F32 *input = (BnCudaBlockQ8_0F32 *)ctx->d_q8_0_f32;
        quantize_q8_mmq_kernel<<<dim3(cols/32, n_tokens),32>>>(input, d_x, cols);
        if (cudaGetLastError() != cudaSuccess) return -1;
        if (n_tokens >= 32 && plan->j % 8 == 0)
            q8_mmq_dense_subwarp_tiled_kernel<8><<<
                dim3((rows + 31) / 32, (n_tokens + 7) / 8), 256>>>(
                d_dst, blocks, input, plan->data, rows, cols, n_tokens,
                plan->j, plan->ntx, out_offset);
        else if (n_tokens >= 16 && plan->j % 4 == 0)
            q8_mmq_dense_subwarp_tiled_kernel<4><<<
                dim3((rows + 31) / 32, (n_tokens + 3) / 4), 256>>>(
                d_dst, blocks, input, plan->data, rows, cols, n_tokens,
                plan->j, plan->ntx, out_offset);
        else
            q8_mmq_dense_subwarp_kernel<<<
                dim3((rows + 31) / 32, n_tokens), 256>>>(
                d_dst, blocks, input, plan->data, rows, cols, plan->j,
                plan->ntx, out_offset);
        return cudaGetLastError() == cudaSuccess ? 0 : -1;
    }
    if (cuda_use_native_quant_matmul(ctx)) {
        int x_blocks = cols / 32;
        if (cuda_ensure_q8_0_f32(ctx, cols, n_tokens) != 0)
            return -1;
        BnCudaBlockQ8_0F32 *xq = (BnCudaBlockQ8_0F32 *)ctx->d_q8_0_f32;
        quantize_q8_0_f32_batch_kernel<<<dim3(x_blocks, n_tokens, 1), 32, 0>>>(
            xq, d_x, cols, n_tokens);
        dim3 grid(((rows + 1) / 2 + warps - 1) / warps, n_tokens, 1);
        q8_0_q8f32_matmul4_warp_kernel<<<grid, threads, 0>>>(
            d_dst, blocks, xq, rows, cols, n_tokens, out_offset);
        return 0;
    }

    if (n_tokens >= 16) {
        dim3 grid((rows + warps - 1) / warps, (n_tokens + 15) / 16, 1);
        q8_0_matmul_token16_warp_kernel<<<grid, threads, 0>>>(
            d_dst, blocks, d_x, rows, cols, n_tokens, out_offset);
    } else if (n_tokens >= 8) {
        dim3 grid((rows + warps - 1) / warps, (n_tokens + 7) / 8, 1);
        q8_0_matmul_token8_warp_kernel<<<grid, threads, 0>>>(
            d_dst, blocks, d_x, rows, cols, n_tokens, out_offset);
    } else if (n_tokens >= 4) {
        dim3 grid((rows + warps - 1) / warps, (n_tokens + 3) / 4, 1);
        q8_0_matmul_token4_warp_kernel<<<grid, threads, 0>>>(
            d_dst, blocks, d_x, rows, cols, n_tokens, out_offset);
    } else {
        dim3 grid(((rows + 3) / 4 + warps - 1) / warps, n_tokens, 1);
        q8_0_matmul4_warp_kernel<<<grid, threads, 0>>>(
            d_dst, blocks, d_x, rows, cols, n_tokens, out_offset);
    }
    return 0;
}

static int cuda_ensure_x_f16(BnCudaCtx *ctx, size_t values) {
    if (!ctx || values == 0) return -1;
    size_t bytes = values * sizeof(__half);
    if (bytes <= ctx->d_x_f16_bytes) return 0;
    if (ctx->d_x_f16) cudaFree(ctx->d_x_f16);
    ctx->d_x_f16 = NULL;
    ctx->d_x_f16_bytes = 0;
    cudaError_t err = cudaMalloc(&ctx->d_x_f16, bytes);
    if (err != cudaSuccess) {
        fprintf(stderr, "[bn:gpu:cuda] f16 input scratch alloc failed: %s\n",
                cudaGetErrorString(err));
        return -1;
    }
    ctx->d_x_f16_bytes = bytes;
    return 0;
}

static int cuda_ensure_prefill(BnCudaCtx *ctx, size_t values) {
    if (!ctx || values == 0) return -1;
    size_t bytes = values * sizeof(float);
    if (bytes <= ctx->d_prefill_bytes) return 0;
    if (ctx->d_prefill) cudaFree(ctx->d_prefill);
    ctx->d_prefill = NULL;
    ctx->d_prefill_bytes = 0;
    cudaError_t err = cudaMalloc(&ctx->d_prefill, bytes);
    if (err != cudaSuccess) {
        fprintf(stderr, "[bn:gpu:cuda] prefill scratch alloc failed: %s\n",
                cudaGetErrorString(err));
        return -1;
    }
    ctx->d_prefill_bytes = bytes;
    return 0;
}

static int cuda_ensure_mmq_fixup(BnCudaCtx *ctx, size_t values) {
    if (!ctx || values == 0 || values > SIZE_MAX / sizeof(float)) return -1;
    size_t bytes = values * sizeof(float);
    if (bytes <= ctx->d_mmq_fixup_bytes) return 0;
    if (ctx->d_mmq_fixup) cudaFree(ctx->d_mmq_fixup);
    ctx->d_mmq_fixup = NULL;
    ctx->d_mmq_fixup_bytes = 0;
    cudaError_t err = cudaMalloc(&ctx->d_mmq_fixup, bytes);
    if (err != cudaSuccess) return -1;
    ctx->d_mmq_fixup_bytes = bytes;
    return 0;
}

static int cuda_ensure_gemm_ptrs(BnCudaCtx *ctx, int n_ptrs) {
    if (!ctx || n_ptrs <= 0) return -1;
    size_t bytes = (size_t)n_ptrs * sizeof(void *);
    if (bytes > ctx->h_gemm_ptrs_bytes) {
        void **p = (void **)realloc(ctx->h_gemm_ptrs, bytes);
        if (!p) {
            fprintf(stderr, "[bn:gpu:cuda] host gemm ptr alloc failed\n");
            return -1;
        }
        ctx->h_gemm_ptrs = p;
        ctx->h_gemm_ptrs_bytes = bytes;
    }
    if (bytes > ctx->d_gemm_ptrs_bytes) {
        if (ctx->d_gemm_ptrs) cudaFree(ctx->d_gemm_ptrs);
        ctx->d_gemm_ptrs = NULL;
        ctx->d_gemm_ptrs_bytes = 0;
        cudaError_t err = cudaMalloc(&ctx->d_gemm_ptrs, bytes);
        if (err != cudaSuccess) {
            fprintf(stderr, "[bn:gpu:cuda] device gemm ptr alloc failed: %s\n",
                    cudaGetErrorString(err));
            return -1;
        }
        ctx->d_gemm_ptrs_bytes = bytes;
    }
    return 0;
}

static int cuda_ensure_argmax(BnCudaCtx *ctx, int n, int n_penalty_tokens) {
    if (!ctx || n <= 0) return -1;
    if (cuda_ctx_set_device(ctx) != 0) return -1;
    if (!ctx->h_argmax) {
        cudaError_t host_err =
            cudaMallocHost((void **)&ctx->h_argmax, sizeof(int));
        if (host_err != cudaSuccess) {
            fprintf(stderr,
                    "[bn:gpu:cuda] pinned argmax host alloc failed: %s\n",
                    cudaGetErrorString(host_err));
            return -1;
        }
    }
    int threads = 256;
    int blocks = (n + threads - 1) / threads;
    size_t bytes = (size_t)blocks * sizeof(BnCudaArgmaxPair) + sizeof(int);
    if (bytes > ctx->d_argmax_bytes) {
        if (ctx->d_argmax) cudaFree(ctx->d_argmax);
        ctx->d_argmax = NULL;
        ctx->d_argmax_bytes = 0;
        cudaError_t err = cudaMalloc(&ctx->d_argmax, bytes);
        if (err != cudaSuccess) {
            fprintf(stderr, "[bn:gpu:cuda] argmax scratch alloc failed: %s\n",
                    cudaGetErrorString(err));
            return -1;
        }
        ctx->d_argmax_bytes = bytes;
    }
    if (n_penalty_tokens > 0) {
        size_t penalty_bytes = (size_t)n_penalty_tokens * sizeof(int);
        if (penalty_bytes > ctx->d_penalty_tokens_bytes) {
            if (ctx->d_penalty_tokens) cudaFree(ctx->d_penalty_tokens);
            ctx->d_penalty_tokens = NULL;
            ctx->d_penalty_tokens_bytes = 0;
            cudaError_t err = cudaMalloc(&ctx->d_penalty_tokens,
                                         penalty_bytes);
            if (err != cudaSuccess) {
                fprintf(stderr,
                        "[bn:gpu:cuda] penalty token scratch alloc failed: %s\n",
                        cudaGetErrorString(err));
                return -1;
            }
            ctx->d_penalty_tokens_bytes = penalty_bytes;
        }
    }
    return 0;
}

static int cuda_ensure_argmax_partials(BnCudaCtx *ctx, int n_partials,
                                        int n_penalty_tokens) {
    if (!ctx || n_partials <= 0) return -1;
    if (cuda_ctx_set_device(ctx) != 0) return -1;
    if (!ctx->h_argmax) {
        cudaError_t host_err =
            cudaMallocHost((void **)&ctx->h_argmax, sizeof(int));
        if (host_err != cudaSuccess) {
            fprintf(stderr,
                    "[bn:gpu:cuda] pinned argmax host alloc failed: %s\n",
                    cudaGetErrorString(host_err));
            return -1;
        }
    }
    size_t bytes = (size_t)n_partials * sizeof(BnCudaArgmaxPair) +
                   sizeof(int);
    if (bytes > ctx->d_argmax_bytes) {
        if (ctx->d_argmax) cudaFree(ctx->d_argmax);
        ctx->d_argmax = NULL;
        ctx->d_argmax_bytes = 0;
        cudaError_t err = cudaMalloc(&ctx->d_argmax, bytes);
        if (err != cudaSuccess) {
            fprintf(stderr, "[bn:gpu:cuda] argmax scratch alloc failed: %s\n",
                    cudaGetErrorString(err));
            return -1;
        }
        ctx->d_argmax_bytes = bytes;
    }
    if (n_penalty_tokens > 0) {
        size_t penalty_bytes = (size_t)n_penalty_tokens * sizeof(int);
        if (penalty_bytes > ctx->d_penalty_tokens_bytes) {
            if (ctx->d_penalty_tokens) cudaFree(ctx->d_penalty_tokens);
            ctx->d_penalty_tokens = NULL;
            ctx->d_penalty_tokens_bytes = 0;
            cudaError_t err = cudaMalloc(&ctx->d_penalty_tokens,
                                         penalty_bytes);
            if (err != cudaSuccess) {
                fprintf(stderr,
                        "[bn:gpu:cuda] penalty token scratch alloc failed: %s\n",
                        cudaGetErrorString(err));
                return -1;
            }
            ctx->d_penalty_tokens_bytes = penalty_bytes;
        }
    }
    return 0;
}

static int cuda_ensure_host_out(BnCudaCtx *ctx, size_t bytes) {
    if (!ctx) return -1;
    if (bytes <= ctx->h_out_bytes) return 0;
    float *next = NULL;
    cudaError_t err = cudaMallocHost((void **)&next, bytes);
    if (err != cudaSuccess) {
        fprintf(stderr, "[bn:gpu:cuda] pinned host output alloc failed: %s\n",
                cudaGetErrorString(err));
        return -1;
    }
    if (ctx->h_out) cudaFreeHost(ctx->h_out);
    ctx->h_out = next;
    ctx->h_out_bytes = bytes;
    return 0;
}

/* Captured arguments may point into activation storage. Invalidate the
 * graph before releasing that storage or changing its capture contract. */
static void cuda_invalidate_exec_graph(BnCudaCtx *ctx) {
    if (ctx->exec_graph) cudaGraphExecDestroy(ctx->exec_graph);
    if (ctx->exec_graph_def) cudaGraphDestroy(ctx->exec_graph_def);
    for (int i = 0; i < ctx->exec_node_count; i++) {
        free(ctx->exec_node_args[i].data);
        ctx->exec_node_args[i].data = NULL;
        ctx->exec_node_args[i].size = 0;
    }
    ctx->exec_graph = NULL;
    ctx->exec_graph_def = NULL;
    ctx->exec_node_count = 0;
    ctx->exec_node_cursor = 0;
    ctx->exec_graph_ops = 0;
    ctx->exec_graph_static_params = 0;
    ctx->exec_graph_attention_key = 0;
}

static void cuda_free_activations(void *vctx) {
    BnCudaCtx *ctx = (BnCudaCtx *)vctx;
    if (!ctx) return;
    if (cuda_ctx_set_device(ctx) != 0) return;
    cuda_invalidate_exec_graph(ctx);
    for (int i = 0; i < BN_GPU_VALUE_COUNT; i++) {
        if (ctx->act_bufs[i]) {
            cudaFree(ctx->act_bufs[i]);
            ctx->act_bufs[i] = NULL;
        }
        ctx->act_sizes[i] = 0;
    }
}

static int cuda_alloc_activation(BnCudaCtx *ctx, int idx, size_t bytes) {
    if (!ctx || idx < 0 || idx >= BN_GPU_VALUE_COUNT) return -1;
    if (bytes == 0) return 0;
    if (cuda_ctx_set_device(ctx) != 0) return -1;
    size_t aligned = (bytes + 255u) & ~(size_t)255u;
    cudaError_t err = cudaMalloc(&ctx->act_bufs[idx], aligned);
    if (err != cudaSuccess) {
        fprintf(stderr, "[bn:gpu:cuda] activation alloc failed idx=%d bytes=%zu: %s\n",
                idx, aligned, cudaGetErrorString(err));
        return -1;
    }
    err = cudaMemset(ctx->act_bufs[idx], 0, aligned);
    if (err != cudaSuccess) {
        fprintf(stderr, "[bn:gpu:cuda] activation zero failed idx=%d bytes=%zu: %s\n",
                idx, aligned, cudaGetErrorString(err));
        cudaFree(ctx->act_bufs[idx]);
        ctx->act_bufs[idx] = NULL;
        return -1;
    }
    ctx->act_sizes[idx] = aligned;
    return 0;
}

static __global__ void prepare_rope_frequencies_kernel(
        float *out, int count, float theta_scale,
        const float *factors, int factor_mode) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i >= count) return;
    float value = __powf(theta_scale, (float)i);
    if (factor_mode == BN_GPU_ROPE_FACTOR_MULTIPLY) {
        value *= factors[i];
    } else if (factor_mode == BN_GPU_ROPE_FACTOR_DIVIDE) {
        value = __fdividef(value, factors[i]);
    }
    out[i] = value;
}

static int cuda_init_activations(void *vctx,
                                 const BnGPUActivationPlan *plan) {
    BnCudaCtx *ctx = (BnCudaCtx *)vctx;
    if (!ctx || !plan || (plan->separate_rope_norm != 0 &&
                           plan->separate_rope_norm != 1)) return -1;
    if (cuda_ctx_set_device(ctx) != 0) return -1;

    cuda_free_activations(ctx);
    ctx->kv_f16 = plan->kv_f16;
    ctx->separate_rope_norm = plan->separate_rope_norm;
    ctx->has_moe_model = plan->uses_moe;

    int q_dim = plan->n_heads * plan->head_size;
    int xb_size = q_dim > plan->dim ? q_dim : plan->dim;
    size_t sizes[BN_GPU_VALUE_COUNT] = {0};
    sizes[BN_GPU_VALUE_X] = (size_t)plan->dim * sizeof(float);
    sizes[BN_GPU_VALUE_XB] = (size_t)xb_size * sizeof(float);
    sizes[BN_GPU_VALUE_XB2] = (size_t)plan->xb2_elements * sizeof(float);
    sizes[BN_GPU_VALUE_Q] = (size_t)q_dim * sizeof(float);
    sizes[BN_GPU_VALUE_HB] = (size_t)plan->hb_elements * sizeof(float);
    sizes[BN_GPU_VALUE_HB2] = (size_t)plan->hb_elements * sizeof(float);
    size_t kv_elem_size = plan->kv_f16 ? sizeof(uint16_t) : sizeof(float);
    sizes[BN_GPU_VALUE_KEY_CACHE] = (size_t)plan->attention_layer_count *
        plan->seq_len * plan->kv_dim * kv_elem_size;
    sizes[BN_GPU_VALUE_VALUE_CACHE] = (size_t)plan->attention_layer_count *
        plan->seq_len * plan->kv_dim * kv_elem_size;
    size_t attention_values = (size_t)plan->n_heads * plan->seq_len;
    /* Decode attention may emit 16 partials of 130 floats per head. */
    size_t partition_values = (size_t)plan->n_heads * 16 * 130;
    sizes[BN_GPU_VALUE_ATT] =
        (attention_values > partition_values
            ? attention_values : partition_values) * sizeof(float);
    sizes[BN_GPU_VALUE_LOGITS] = (size_t)plan->vocab_size * sizeof(float);
    sizes[BN_GPU_VALUE_ROPE_FREQ] =
        (size_t)plan->n_layers * (size_t)(plan->head_size / 2) *
        sizeof(float);
    sizes[BN_GPU_VALUE_SCRATCH] = (size_t)xb_size * sizeof(float);
    if (plan->per_layer_input_dim > 0)
        sizes[BN_GPU_VALUE_PER_LAYER_INPUT] =
            (size_t)plan->n_layers * (size_t)plan->per_layer_input_dim *
            sizeof(float);
    if (plan->hyper_connection_count > 1 &&
        plan->hyper_connection_rank > 0) {
        size_t wide = (size_t)plan->hyper_connection_count *
                      (size_t)plan->dim;
        sizes[BN_GPU_VALUE_HC_RESIDUAL] = wide * sizeof(float);
        sizes[BN_GPU_VALUE_HC_NORM] = wide * sizeof(float);
        sizes[BN_GPU_VALUE_HC_GATE] = wide * sizeof(float);
        sizes[BN_GPU_VALUE_HC_LOW_RANK] =
            (size_t)plan->hyper_connection_rank * sizeof(float);
        sizes[BN_GPU_VALUE_HC_INJECT] =
            (size_t)plan->hyper_connection_count * sizeof(float);
    }
    {
        size_t qkv_size =
            (size_t)(q_dim + 2 * plan->kv_dim) * sizeof(float);
        size_t gated_q_size = (size_t)(2 * q_dim) * sizeof(float);
        if (plan->uses_hybrid_moe) {
            size_t hybrid_q_size = (size_t)(4 * q_dim) * sizeof(float);
            if (hybrid_q_size > gated_q_size) gated_q_size = hybrid_q_size;
        }
        sizes[BN_GPU_VALUE_QKV] = qkv_size > gated_q_size
            ? qkv_size : gated_q_size;
    }
    if (plan->moe_expert_hidden_dim > 0) {
        int moe_scratch = plan->moe_expert_hidden_dim;
        if (plan->moe_total_experts > moe_scratch)
            moe_scratch = plan->moe_total_experts;
        if (2 * plan->moe_active_experts > moe_scratch)
            moe_scratch = 2 * plan->moe_active_experts;
        if (plan->moe_active_experts > 0 &&
            plan->moe_expert_hidden_dim <= INT_MAX / plan->moe_active_experts &&
            plan->moe_expert_hidden_dim * plan->moe_active_experts > moe_scratch)
            moe_scratch = plan->moe_expert_hidden_dim * plan->moe_active_experts;
        sizes[BN_GPU_VALUE_MOE_HB] = (size_t)moe_scratch * sizeof(float);
        sizes[BN_GPU_VALUE_MOE_HB2] = (size_t)moe_scratch * sizeof(float);
        sizes[BN_GPU_VALUE_MOE_OUT] = (size_t)plan->dim * sizeof(float);
    }
    if (plan->uses_hybrid_ssm) {
        int num_v_heads = plan->ssm_time_step_rank;
        int head_k_dim = plan->ssm_state_size;
        int head_v_dim = plan->ssm_inner_size /
            (num_v_heads > 0 ? num_v_heads : 1);
        int key_dim = plan->ssm_group_count * head_k_dim;
        int value_dim = plan->ssm_inner_size;
        int qkv_dim = key_dim * 2 + value_dim;
        int kern = plan->ssm_conv_kernel > 0 ? plan->ssm_conv_kernel : 4;
        sizes[BN_GPU_VALUE_SSM_STATE] = (size_t)plan->ssm_layer_count *
            num_v_heads * head_k_dim * head_v_dim * sizeof(float);
        sizes[BN_GPU_VALUE_SSM_CONV_STATE] =
            (size_t)plan->ssm_layer_count * (kern - 1) * qkv_dim * sizeof(float);
        sizes[BN_GPU_VALUE_SSM_QKV] = (size_t)qkv_dim * sizeof(float);
        sizes[BN_GPU_VALUE_SSM_Z] = (size_t)value_dim * sizeof(float);
        sizes[BN_GPU_VALUE_SSM_ALPHA] = (size_t)num_v_heads * sizeof(float);
        sizes[BN_GPU_VALUE_SSM_BETA] = (size_t)num_v_heads * sizeof(float);
        sizes[BN_GPU_VALUE_SSM_V] = (size_t)value_dim * sizeof(float);
        /* SSM comparison snapshots use these shared scratch slots even in
         * dense models, where the MoE allocation above is absent. */
        size_t snapshot_bytes = (size_t)value_dim * sizeof(float);
        if (sizes[BN_GPU_VALUE_MOE_HB] < snapshot_bytes)
            sizes[BN_GPU_VALUE_MOE_HB] = snapshot_bytes;
        if (sizes[BN_GPU_VALUE_MOE_HB2] < snapshot_bytes)
            sizes[BN_GPU_VALUE_MOE_HB2] = snapshot_bytes;
    }

    for (int i = 0; i < BN_GPU_VALUE_COUNT; i++) {
        if (cuda_alloc_activation(ctx, i, sizes[i]) != 0) {
            cuda_free_activations(ctx);
            return -1;
        }
    }
    if (plan->rope_frequency_count > 0 &&
        ctx->act_bufs[BN_GPU_VALUE_ROPE_FREQ]) {
        if (!plan->rope_frequencies || (size_t)plan->rope_frequency_count >
            ctx->act_sizes[BN_GPU_VALUE_ROPE_FREQ] / sizeof(float)) {
            cuda_free_activations(ctx);
            return -1;
        }
        cudaError_t err = cudaMemcpy(ctx->act_bufs[BN_GPU_VALUE_ROPE_FREQ],
                                     plan->rope_frequencies,
                                     (size_t)plan->rope_frequency_count *
                                         sizeof(float),
                                     cudaMemcpyHostToDevice);
        if (err != cudaSuccess) {
            fprintf(stderr, "[bn:gpu:cuda] rope frequency upload failed: %s\n",
                    cudaGetErrorString(err));
            cuda_free_activations(ctx);
            return -1;
        }
    }
    if (plan->rope_frequency_plan_count < 0 ||
        (plan->rope_frequency_plan_count > 0 && !plan->rope_frequency_plans)) {
        cuda_free_activations(ctx);
        return -1;
    }
    for (int r = 0; r < plan->rope_frequency_plan_count; r++) {
        const BnGPURopeFrequencyPlan *rp = &plan->rope_frequency_plans[r];
        size_t capacity = ctx->act_sizes[BN_GPU_VALUE_ROPE_FREQ] / sizeof(float);
        if (rp->offset < 0 || rp->pair_count < 0 ||
            (size_t)rp->offset > capacity ||
            (size_t)rp->pair_count > capacity - (size_t)rp->offset ||
            rp->rotary_dims < 0 || rp->pair_count > rp->rotary_dims / 2 ||
            (rp->pair_count > 0 && (!(rp->theta > 0) || !isfinite(rp->theta))) ||
            rp->factor_mode < BN_GPU_ROPE_FACTOR_NONE ||
            rp->factor_mode > BN_GPU_ROPE_FACTOR_DIVIDE ||
            (rp->factor_mode != BN_GPU_ROPE_FACTOR_NONE && !rp->factors)) {
            cuda_free_activations(ctx);
            return -1;
        }
        if (rp->pair_count == 0) continue;
        float *factors = NULL;
        cudaError_t err = cudaSuccess;
        if (rp->factor_mode != BN_GPU_ROPE_FACTOR_NONE) {
            size_t bytes = (size_t)rp->pair_count * sizeof(float);
            err = cudaMalloc((void **)&factors, bytes);
            if (err == cudaSuccess)
                err = cudaMemcpy(factors, rp->factors, bytes, cudaMemcpyHostToDevice);
        }
        if (err == cudaSuccess) {
            float theta_scale = powf(rp->theta, -2.0f / (float)rp->rotary_dims);
            prepare_rope_frequencies_kernel<<<(rp->pair_count + 127) / 128, 128>>>(
                (float *)ctx->act_bufs[BN_GPU_VALUE_ROPE_FREQ] + rp->offset,
                rp->pair_count, theta_scale, factors, (int)rp->factor_mode);
            err = cudaGetLastError();
            if (err == cudaSuccess) err = cudaDeviceSynchronize();
        }
        if (factors) cudaFree(factors);
        if (err != cudaSuccess) {
            fprintf(stderr, "[bn:gpu:cuda] rope preparation failed: %s\n",
                    cudaGetErrorString(err));
            cuda_free_activations(ctx);
            return -1;
        }
    }
    /* Uploads and zero fills use the default stream; execution/readback use
     * a nonblocking stream. A pageable host upload may return before DMA is
     * complete, including when no RoPE preparation kernel is requested. */
    cudaError_t ready = cudaStreamSynchronize(0);
    if (ready != cudaSuccess) {
        fprintf(stderr, "[bn:gpu:cuda] activation initialization failed: %s\n",
                cudaGetErrorString(ready));
        cuda_free_activations(ctx);
        return -1;
    }
    return 0;
}

static int cuda_write_activation(void *vctx, int buf_idx, const void *data,
                                 size_t size, size_t offset) {
    BnCudaCtx *ctx = (BnCudaCtx *)vctx;
    if (!ctx || !data || buf_idx < 0 || buf_idx >= BN_GPU_VALUE_COUNT)
        return -1;
    if (cuda_ctx_set_device(ctx) != 0) return -1;
    if (!ctx->act_bufs[buf_idx] || offset + size > ctx->act_sizes[buf_idx])
        return -1;
    cudaError_t err = cudaSuccess;
    if (ctx->stream) {
        err = cudaMemcpyAsync((char *)ctx->act_bufs[buf_idx] + offset,
                              data, size, cudaMemcpyHostToDevice,
                              ctx->stream);
    } else {
        err = cudaMemcpy((char *)ctx->act_bufs[buf_idx] + offset,
                         data, size, cudaMemcpyHostToDevice);
    }
    return err == cudaSuccess ? 0 : -1;
}

static int cuda_read_activation(void *vctx, int buf_idx, void *out,
                                size_t size, size_t offset) {
    BnCudaCtx *ctx = (BnCudaCtx *)vctx;
    if (ctx && out && offset == 0 &&
        (buf_idx == BN_GPU_DEBUG_BUF_NATIVE_QUANT_ACT ||
         buf_idx == BN_GPU_DEBUG_BUF_NATIVE_QUANT_SCALE ||
         buf_idx == BN_GPU_DEBUG_BUF_NATIVE_QUANT_BLOCK_SUM)) {
        if (cuda_ctx_set_device(ctx) != 0 || !ctx->d_q8_k)
            return -1;
        size_t n_blocks = buf_idx == BN_GPU_DEBUG_BUF_NATIVE_QUANT_ACT
            ? size / BN_QK_K
            : buf_idx == BN_GPU_DEBUG_BUF_NATIVE_QUANT_SCALE
                ? size / sizeof(float)
                : size / (16 * sizeof(int16_t));
        size_t scratch_bytes = n_blocks * sizeof(BnBlockQ8K);
        if (n_blocks == 0 || scratch_bytes > ctx->d_q8_k_bytes)
            return -1;
        BnBlockQ8K *scratch = (BnBlockQ8K *)malloc(scratch_bytes);
        if (!scratch)
            return -1;
        cudaError_t err = cudaMemcpy(scratch, ctx->d_q8_k, scratch_bytes,
                                     cudaMemcpyDeviceToHost);
        if (err == cudaSuccess) {
            for (size_t b = 0; b < n_blocks; b++) {
                if (buf_idx == BN_GPU_DEBUG_BUF_NATIVE_QUANT_ACT)
                    memcpy((int8_t *)out + b * BN_QK_K, scratch[b].qs,
                           BN_QK_K);
                else if (buf_idx == BN_GPU_DEBUG_BUF_NATIVE_QUANT_SCALE)
                    ((float *)out)[b] = scratch[b].d;
                else
                    memcpy((int16_t *)out + b * 16, scratch[b].bsums,
                           16 * sizeof(int16_t));
            }
        }
        free(scratch);
        return err == cudaSuccess ? 0 : -1;
    }
    if (!ctx || !out || buf_idx < 0 || buf_idx >= BN_GPU_VALUE_COUNT) {
        if (cuda_debug_readback(ctx)) {
            fprintf(stderr,
                    "[bn:gpu:cuda] read_activation invalid args: ctx=%p "
                    "out=%p buf=%d size=%zu offset=%zu\n",
                    (void *)ctx, out, buf_idx, size, offset);
        }
        return -1;
    }
    if (cuda_ctx_set_device(ctx) != 0) return -1;
    if (!ctx->act_bufs[buf_idx] || offset + size > ctx->act_sizes[buf_idx]) {
        if (cuda_debug_readback(ctx)) {
            fprintf(stderr,
                    "[bn:gpu:cuda] read_activation invalid buffer: buf=%d "
                    "ptr=%p size=%zu offset=%zu alloc=%zu\n",
                    buf_idx, ctx->act_bufs[buf_idx], size, offset,
                    ctx->act_sizes[buf_idx]);
        }
        return -1;
    }
    cudaError_t err = cudaSuccess;
    if (ctx->stream) {
        err = cudaMemcpyAsync(out, (char *)ctx->act_bufs[buf_idx] + offset,
                              size, cudaMemcpyDeviceToHost, ctx->stream);
        if (err == cudaSuccess)
            err = cudaStreamSynchronize(ctx->stream);
    } else {
        err = cudaMemcpy(out, (char *)ctx->act_bufs[buf_idx] + offset,
                         size, cudaMemcpyDeviceToHost);
    }
    if (err != cudaSuccess && cuda_debug_readback(ctx)) {
        fprintf(stderr,
                "[bn:gpu:cuda] read_activation failed: buf=%d size=%zu "
                "offset=%zu err=%s\n",
                buf_idx, size, offset, cudaGetErrorString(err));
    }
    return err == cudaSuccess ? 0 : -1;
}

static int cuda_buffer_create_f16_cache(const BnCudaCtx *ctx,
                                        BnCudaBuffer *buf,
                                        int aux_cache_mode) {
    if (!buf || !buf->data || buf->rows <= 0 || buf->cols <= 0 ||
        (buf->cols & 31) != 0)
        return 0;
    if (!bn_gpu_policy_cuda_cublas_aux_cache_supported(
            ctx ? ctx->runtime_policy : NULL, buf->type, buf->cols))
        return 0;

    int force_down_kquant_f32 = aux_cache_mode == 2;
    int force_f16 = aux_cache_mode == 3;
    int force_asymmetric_kquant_f32 =
        bn_backend_quant_aux_cache_force_asymmetric_kquant_f32(
            buf->type, aux_cache_mode == 2);
    int down_kquant_as_f16 = bn_backend_quant_aux_cache_down_kquant_can_use_f16(
                        buf->type, force_f16, force_down_kquant_f32) &&
                    bn_gpu_policy_cuda_down_kquant_cublas_f16_cache_enabled(
                        ctx ? ctx->runtime_policy : NULL);
    int add_down_kquant_f32_cache =
        bn_backend_quant_aux_cache_add_down_kquant_f32(buf->type, force_f16) &&
        bn_gpu_policy_cuda_down_kquant_f16_cache_adds_f32_down_cache(ctx->runtime_policy);
    size_t n = (size_t)buf->rows * (size_t)buf->cols;
    int f32_cache = bn_backend_quant_aux_cache_f32_storage(
        buf->type, force_asymmetric_kquant_f32, down_kquant_as_f16);
    size_t bytes = n * (f32_cache
                        ? sizeof(float)
                        : sizeof(__half));
    int max_mb = bn_gpu_policy_cuda_cublas_aux_cache_max_mb(
        ctx ? ctx->runtime_policy : NULL, buf->type,
        force_down_kquant_f32, force_f16);
    if (max_mb > 0 && bytes > (size_t)max_mb * 1024u * 1024u)
        return 0;
    size_t free_mem = 0;
    size_t total_mem = 0;
    if (cudaMemGetInfo(&free_mem, &total_mem) == cudaSuccess) {
        int reserve_mb =
            bn_gpu_policy_cuda_cublas_cache_reserve_mb_or_default(
                ctx ? ctx->runtime_policy : NULL, 4096);
        size_t reserve = reserve_mb > 0
            ? (size_t)reserve_mb * 1024u * 1024u : 0u;
        if (free_mem <= bytes + reserve)
            return 0;
    }
    void **cache_ptr = f32_cache
        ? &buf->f32_data
        : &buf->f16_data;
    cudaError_t err = cudaMalloc(cache_ptr, bytes);
    if (err != cudaSuccess) {
        if (cuda_debug_cublas_cache(ctx))
            fprintf(stderr,
                    "[bn:gpu:cuda] cublas cache alloc skipped type=%d rows=%d cols=%d bytes=%zu: %s\n",
                    buf->type, buf->rows, buf->cols, bytes,
                    cudaGetErrorString(err));
        *cache_ptr = NULL;
        return 0;
    }
    int threads = 256;
    int blocks = (int)((n + (size_t)threads - 1u) / (size_t)threads);
    BnBackendQuantAuxCacheDequant dequant_route =
        bn_backend_quant_aux_cache_dequant_route(buf->type,
                                                 force_asymmetric_kquant_f32,
                                                 down_kquant_as_f16);
    switch (dequant_route) {
    case BN_BACKEND_QUANT_AUX_CACHE_DEQUANT_DENSE_BFLOAT_TO_F16:
        dequant_bf16_to_f16_kernel<<<blocks, threads>>>(
            (__half *)buf->f16_data, (const uint16_t *)buf->data,
            buf->rows, buf->cols);
        break;
    case BN_BACKEND_QUANT_AUX_CACHE_DEQUANT_NATIVE_QUANT_TO_F16:
        dequant_q8_0_to_f16_kernel<<<blocks, threads>>>(
            (__half *)buf->f16_data, (const BnBlockQ8_0 *)buf->data,
            buf->rows, buf->cols);
        break;
    case BN_BACKEND_QUANT_AUX_CACHE_DEQUANT_LEGACY_BLOCK_TO_F16:
        dequant_q5_0_to_f16_kernel<<<blocks, threads>>>(
            (__half *)buf->f16_data, (const BnBlockQ5_0 *)buf->data,
            buf->rows, buf->cols);
        break;
    case BN_BACKEND_QUANT_AUX_CACHE_DEQUANT_COMPACT_KQUANT_TO_F16:
        dequant_q3k_to_f16_kernel<<<blocks, threads>>>(
            (__half *)buf->f16_data, (const BnBlockQ3K *)buf->data,
            buf->rows, buf->cols);
        break;
    case BN_BACKEND_QUANT_AUX_CACHE_DEQUANT_ASYMMETRIC_KQUANT_TO_F32:
        dequant_q4k_to_f32_kernel<<<blocks, threads>>>(
            (float *)buf->f32_data, (const BnBlockQ4K *)buf->data,
            buf->rows, buf->cols);
        break;
    case BN_BACKEND_QUANT_AUX_CACHE_DEQUANT_ASYMMETRIC_KQUANT_TO_F16:
        dequant_q4k_to_f16_kernel<<<blocks, threads>>>(
            (__half *)buf->f16_data, (const BnBlockQ4K *)buf->data,
            buf->rows, buf->cols);
        break;
    case BN_BACKEND_QUANT_AUX_CACHE_DEQUANT_DEINTERLEAVED_KQUANT_TO_F16:
        dequant_q5k_to_f16_kernel<<<blocks, threads>>>(
            (__half *)buf->f16_data, (const BnBlockQ5K *)buf->data,
            buf->rows, buf->cols);
        break;
    case BN_BACKEND_QUANT_AUX_CACHE_DEQUANT_DOWN_KQUANT_TO_F16:
        dequant_q6k_to_f16_kernel<<<blocks, threads>>>(
            (__half *)buf->f16_data, (const BnBlockQ6K *)buf->data,
            buf->rows, buf->cols);
        break;
    case BN_BACKEND_QUANT_AUX_CACHE_DEQUANT_DOWN_KQUANT_TO_F32:
        dequant_q6k_to_f32_kernel<<<blocks, threads>>>(
            (float *)buf->f32_data, (const BnBlockQ6K *)buf->data,
            buf->rows, buf->cols);
        break;
    case BN_BACKEND_QUANT_AUX_CACHE_DEQUANT_NONE:
        cudaFree(*cache_ptr);
        *cache_ptr = NULL;
        return 0;
    }
    err = cudaGetLastError();
    if (err != cudaSuccess) {
        if (cuda_debug_cublas_cache(ctx))
            fprintf(stderr,
                    "[bn:gpu:cuda] cublas cache dequant skipped type=%d rows=%d cols=%d: %s\n",
                    buf->type, buf->rows, buf->cols,
                    cudaGetErrorString(err));
        cudaFree(*cache_ptr);
        *cache_ptr = NULL;
        return 0;
    }
    if (cuda_debug_cublas_cache(ctx))
        fprintf(stderr,
                "[bn:gpu:cuda] cublas cache ready type=%d rows=%d cols=%d bytes=%zu precision=%s\n",
                buf->type, buf->rows, buf->cols, bytes,
                f32_cache ? "f32" : "f16");
    if (f32_cache)
        buf->f32_size = bytes;
    else
        buf->f16_size = bytes;
    if (add_down_kquant_f32_cache && !buf->f32_data) {
        size_t f32_bytes = n * sizeof(float);
        size_t free_mem2 = 0;
        size_t total_mem2 = 0;
        if (cudaMemGetInfo(&free_mem2, &total_mem2) == cudaSuccess) {
            int reserve_mb =
                bn_gpu_policy_cuda_cublas_cache_reserve_mb_or_default(
                    ctx ? ctx->runtime_policy : NULL, 4096);
            size_t reserve = reserve_mb > 0
                ? (size_t)reserve_mb * 1024u * 1024u : 0u;
            if (free_mem2 <= f32_bytes + reserve)
                return 0;
        }
        cudaError_t f32_err = cudaMalloc(&buf->f32_data, f32_bytes);
        if (f32_err != cudaSuccess) {
            if (cuda_debug_cublas_cache(ctx))
                fprintf(stderr,
                        "[bn:gpu:cuda] q6 f32 companion cache skipped "
                        "rows=%d cols=%d bytes=%zu: %s\n",
                        buf->rows, buf->cols, f32_bytes,
                        cudaGetErrorString(f32_err));
            buf->f32_data = NULL;
            return 0;
        }
        dequant_q6k_to_f32_kernel<<<blocks, threads>>>(
            (float *)buf->f32_data, (const BnBlockQ6K *)buf->data,
            buf->rows, buf->cols);
        f32_err = cudaGetLastError();
        if (f32_err != cudaSuccess) {
            if (cuda_debug_cublas_cache(ctx))
                fprintf(stderr,
                        "[bn:gpu:cuda] q6 f32 companion dequant skipped "
                        "rows=%d cols=%d: %s\n",
                        buf->rows, buf->cols,
                        cudaGetErrorString(f32_err));
            cudaFree(buf->f32_data);
            buf->f32_data = NULL;
            return 0;
        }
        buf->f32_size = f32_bytes;
        if (cuda_debug_cublas_cache(ctx))
            fprintf(stderr,
                    "[bn:gpu:cuda] q6 f32 companion cache ready rows=%d "
                    "cols=%d bytes=%zu\n",
                    buf->rows, buf->cols, f32_bytes);
    }
    return 0;
}

static int cuda_buffer_create_iq_f16_cache(const BnCudaCtx *ctx,
                                           BnCudaBuffer *buf,
                                           const void *host_data) {
    if (!buf || !host_data || !buf->data || buf->rows <= 0 ||
        buf->cols <= 0 || (buf->cols % BN_QK_K) != 0)
        return 0;
    if (!bn_backend_quant_supports_lazy_moe_aux_cache(buf->type))
        return 0;
    if (!bn_gpu_policy_cuda_cublas_matmul_enabled(
            ctx ? ctx->runtime_policy : NULL))
        return 0;

    size_t n = (size_t)buf->rows * (size_t)buf->cols;
    size_t bytes = n * sizeof(uint16_t);
    int max_mb = bn_gpu_policy_cuda_cublas_cache_max_mb(
        ctx ? ctx->runtime_policy : NULL, 128, 0);
    if (max_mb > 0 && bytes > (size_t)max_mb * 1024u * 1024u)
        return 0;
    size_t free_mem = 0;
    size_t total_mem = 0;
    if (cudaMemGetInfo(&free_mem, &total_mem) == cudaSuccess) {
        int reserve_mb =
            bn_gpu_policy_cuda_cublas_cache_reserve_mb_or_default(
                ctx ? ctx->runtime_policy : NULL, 4096);
        size_t reserve = reserve_mb > 0
            ? (size_t)reserve_mb * 1024u * 1024u : 0u;
        if (free_mem <= bytes + reserve)
            return 0;
    }

    uint16_t *h_f16 = (uint16_t *)malloc(bytes);
    if (!h_f16)
        return 0;
    float tmp[BN_QK_K];
    int blocks_per_row = buf->cols / BN_QK_K;
    for (int r = 0; r < buf->rows; r++) {
        for (int b = 0; b < blocks_per_row; b++) {
            size_t block_idx = (size_t)r * (size_t)blocks_per_row + (size_t)b;
            if (bn_backend_quant_lazy_moe_aux_cache_dequant_block(
                    buf->type, host_data, block_idx, tmp) != 0) {
                free(h_f16);
                return 0;
            }
            size_t out = ((size_t)r * (size_t)buf->cols +
                          (size_t)b * BN_QK_K);
            for (int i = 0; i < BN_QK_K; i++)
                h_f16[out + (size_t)i] = bn_fp32_to_fp16(tmp[i]);
        }
    }

    cudaError_t err = cudaMalloc(&buf->f16_data, bytes);
    if (err == cudaSuccess) {
        err = cudaMemcpy(buf->f16_data, h_f16, bytes, cudaMemcpyHostToDevice);
        if (err == cudaSuccess)
            buf->f16_size = bytes;
    }
    free(h_f16);
    if (err != cudaSuccess) {
        if (buf->f16_data)
            cudaFree(buf->f16_data);
        buf->f16_data = NULL;
        buf->f16_size = 0;
        if (cuda_debug_cublas_cache(ctx))
            fprintf(stderr,
                    "[bn:gpu:cuda] iq f16 cache skipped type=%d rows=%d "
                    "cols=%d bytes=%zu: %s\n",
                    buf->type, buf->rows, buf->cols, bytes,
                    cudaGetErrorString(err));
    } else if (cuda_debug_cublas_cache(ctx)) {
        fprintf(stderr,
                "[bn:gpu:cuda] iq f16 cache ready type=%d rows=%d cols=%d "
                "bytes=%zu\n",
                buf->type, buf->rows, buf->cols, bytes);
    }
    return 0;
}


static size_t cuda_buffer_kquant_mmq_bytes(const BnCudaCtx *ctx, int type,
                                           int rows, int cols) {
    int asymmetric = type == BN_GGUF_TENSOR_Q4_K ||
                     type == BN_GGUF_TENSOR_Q5_K;
    int q6 = type == BN_GGUF_TENSOR_Q6_K && ctx &&
             ctx->compute_capability == 1200;
    int iq4xs = bn_backend_quant_supports_packed_codebook_matvec(type) && ctx &&
                bn_gpu_policy_cuda_iq4xs_packed_enabled(ctx->runtime_policy);
    if (!ctx || (!asymmetric && !q6 && !iq4xs) || rows <= 0 || cols <= 0 ||
        (cols % BN_QK_K) != 0 ||
        (asymmetric &&
         !bn_gpu_policy_cuda_asymmetric_kquant_matmul8_enabled(
             ctx->runtime_policy)))
        return 0;
    size_t blocks_per_row = (size_t)cols / BN_QK_K;
    size_t block_bytes = iq4xs ? sizeof(BnCudaIQ4XSPackedBlock) :
                         q6 ? sizeof(BnCudaQ6KMmqBlock) :
                              sizeof(BnCudaKQuantMmqBlock);
    if ((size_t)rows > SIZE_MAX / blocks_per_row / block_bytes)
        return SIZE_MAX;
    return (size_t)rows * blocks_per_row * block_bytes;
}

static size_t cuda_buffer_f16_cache_extra_bytes(void *vctx, int type,
                                                int rows, int cols) {
    BnCudaCtx *ctx = (BnCudaCtx *)vctx;
    if (!ctx || rows <= 0 || cols <= 0) return 0;
    size_t packed = cuda_buffer_kquant_mmq_bytes(ctx, type, rows, cols);
    if (packed == SIZE_MAX) return SIZE_MAX;
    if (!bn_gpu_policy_cuda_cublas_aux_cache_supported(
            ctx->runtime_policy, type, cols))
        return packed;
    int down_f16 = bn_backend_quant_aux_cache_down_kquant_can_use_f16(
                       type, 1, 0) &&
                   bn_gpu_policy_cuda_down_kquant_cublas_f16_cache_enabled(
                       ctx->runtime_policy);
    int f32 = bn_backend_quant_aux_cache_f32_storage(type, 0, down_f16);
    size_t element_bytes = f32 ? sizeof(float) : sizeof(uint16_t);
    if ((size_t)rows > SIZE_MAX / (size_t)cols / element_bytes)
        return SIZE_MAX;
    size_t elements = (size_t)rows * (size_t)cols;
    size_t primary = elements * element_bytes;
    int max_mb = bn_gpu_policy_cuda_cublas_aux_cache_max_mb(
        ctx->runtime_policy, type, 0, 1);
    if (max_mb > 0 && primary > (size_t)max_mb * 1024u * 1024u)
        return packed;
    size_t companion = 0;
    if (!f32 && bn_backend_quant_aux_cache_add_down_kquant_f32(type, 1) &&
        bn_gpu_policy_cuda_down_kquant_f16_cache_adds_f32_down_cache(
            ctx->runtime_policy)) {
        if (elements > SIZE_MAX / sizeof(float)) return SIZE_MAX;
        companion = elements * sizeof(float);
    }
    if (primary > SIZE_MAX - packed ||
        companion > SIZE_MAX - packed - primary)
        return SIZE_MAX;
    return packed + primary + companion;
}

static void cuda_buffer_create_kquant_mmq(BnCudaCtx *ctx, BnCudaBuffer *buf) {
    if (!ctx || !buf || !buf->data || buf->mmq_data) return;
    size_t bytes = cuda_buffer_kquant_mmq_bytes(ctx, buf->type,
                                               buf->rows, buf->cols);
    if (bytes == 0 || bytes == SIZE_MAX) return;
    size_t n_blocks = (size_t)buf->rows * (size_t)buf->cols / BN_QK_K;
    size_t free_mem = 0;
    size_t total_mem = 0;
    if (cudaMemGetInfo(&free_mem, &total_mem) == cudaSuccess &&
        free_mem <= bytes + 4096u * 1024u * 1024u)
        return;
    cudaError_t err = cudaMalloc(&buf->mmq_data, bytes);
    if (err != cudaSuccess) {
        buf->mmq_data = NULL;
        (void)cudaGetLastError();
        return;
    }
    if (buf->type == BN_GGUF_TENSOR_Q4_K)
        pack_q4k_mmq_kernel<<<n_blocks, BN_QK_K>>>(
            (BnCudaKQuantMmqBlock *)buf->mmq_data,
            (const BnBlockQ4K *)buf->data, n_blocks);
    else if (buf->type == BN_GGUF_TENSOR_Q5_K)
        pack_q5k_mmq_kernel<<<n_blocks, BN_QK_K>>>(
            (BnCudaKQuantMmqBlock *)buf->mmq_data,
            (const BnBlockQ5K *)buf->data, n_blocks);
    else if (bn_backend_quant_supports_packed_codebook_matvec(buf->type))
        iq4xs_pack_decode_kernel<<<n_blocks, BN_QK_K>>>(
            (BnCudaIQ4XSPackedBlock *)buf->mmq_data,
            (const BnBlockIQ4XS *)buf->data, n_blocks);
    else
        pack_q6k_mmq_kernel<<<n_blocks, BN_QK_K>>>(
            (BnCudaQ6KMmqBlock *)buf->mmq_data,
            (const BnBlockQ6K *)buf->data, n_blocks);
    err = cudaGetLastError();
    if (err != cudaSuccess) {
        cudaFree(buf->mmq_data);
        buf->mmq_data = NULL;
        (void)cudaGetLastError();
        return;
    }
    buf->mmq_size = bytes;
}

static void cuda_buffer_destroy(void *vctx, void *buffer);

static void *cuda_buffer_create_impl(void *vctx, const void *data, size_t size,
                                     int type, int rows, int cols,
                                     int create_aux_cache) {
    BnCudaCtx *ctx = (BnCudaCtx *)vctx;
    if (cuda_ctx_set_device(ctx) != 0) return NULL;
    if (!data || size == 0) return NULL;

    BnCudaBuffer *buf = (BnCudaBuffer *)calloc(1, sizeof(BnCudaBuffer));
    if (!buf) return NULL;
    buf->size = size;
    buf->type = type;
    buf->rows = rows;
    buf->cols = cols;

    cudaError_t err = cudaMalloc(&buf->data, size);
    if (err != cudaSuccess) {
        fprintf(stderr, "[bn:gpu:cuda] weight alloc failed: %s\n",
                cudaGetErrorString(err));
        (void)cudaGetLastError();
        free(buf);
        return NULL;
    }
    err = cudaMemcpy(buf->data, data, size, cudaMemcpyHostToDevice);
    if (err != cudaSuccess) {
        fprintf(stderr, "[bn:gpu:cuda] weight upload failed: %s\n",
                cudaGetErrorString(err));
        cudaFree(buf->data);
        free(buf);
        return NULL;
    }
    if (create_aux_cache) {
        cuda_buffer_create_kquant_mmq(ctx, buf);
        int lazy_candidate =
            bn_backend_quant_supports_lazy_moe_aux_cache(type);
        if (bn_backend_quant_eager_aux_cache_supported(type) &&
            (!lazy_candidate || create_aux_cache != 1 ||
             bn_gpu_policy_cuda_eager_kquant_aux_cache_enabled(
                 ctx->runtime_policy)))
            cuda_buffer_create_f16_cache(ctx, buf, create_aux_cache);
        else if (lazy_candidate)
            cuda_buffer_create_iq_f16_cache(ctx, buf, data);
    }
    /* Pageable host uploads may return before device transfer completes.
     * Execution uses a nonblocking stream, so default-stream uploads and
     * auxiliary layout kernels must be complete before publishing a handle. */
    err = cudaStreamSynchronize((cudaStream_t)0);
    if (err != cudaSuccess) {
        fprintf(stderr, "[bn:gpu:cuda] weight preparation sync failed: %s\n",
                cudaGetErrorString(err));
        cuda_buffer_destroy(vctx, buf);
        return NULL;
    }
    return buf;
}

static void *cuda_buffer_create(void *vctx, const void *data, size_t size,
                                int type, int rows, int cols) {
    return cuda_buffer_create_impl(vctx, data, size, type, rows, cols, 1);
}

static void *cuda_buffer_create_quant_only(void *vctx, const void *data,
                                           size_t size, int type, int rows,
                                           int cols) {
    return cuda_buffer_create_impl(vctx, data, size, type, rows, cols, 0);
}

static void *cuda_buffer_create_kquant_f32_cache(void *vctx, const void *data,
                                             size_t size, int type, int rows,
                                             int cols) {
    return cuda_buffer_create_impl(vctx, data, size, type, rows, cols, 2);
}

static void *cuda_buffer_create_force_f16_cache(void *vctx, const void *data,
                                                size_t size, int type,
                                                int rows, int cols) {
    return cuda_buffer_create_impl(vctx, data, size, type, rows, cols, 3);
}

static void *cuda_buffer_create_stacked2(void *vctx,
                                         const void *data0, size_t size0,
                                         const void *data1, size_t size1,
                                         int type, int rows, int cols) {
    if (!data0 || !data1 || size0 == 0 || size1 == 0)
        return NULL;
    size_t size = size0 + size1;
    uint8_t *combined = (uint8_t *)malloc(size);
    if (!combined)
        return NULL;
    memcpy(combined, data0, size0);
    memcpy(combined + size0, data1, size1);
    void *buf = cuda_buffer_create_impl(vctx, combined, size, type, rows,
                                        cols, 1);
    free(combined);
    return buf;
}

static void *cuda_buffer_create_stacked3(void *vctx,
                                         const void *data0, size_t size0,
                                         const void *data1, size_t size1,
                                         const void *data2, size_t size2,
                                         int type, int rows, int cols) {
    if (!data0 || !data1 || !data2 || size0 == 0 || size1 == 0 ||
        size2 == 0)
        return NULL;
    size_t size = size0 + size1 + size2;
    uint8_t *combined = (uint8_t *)malloc(size);
    if (!combined)
        return NULL;
    memcpy(combined, data0, size0);
    memcpy(combined + size0, data1, size1);
    memcpy(combined + size0 + size1, data2, size2);
    void *buf = cuda_buffer_create_impl(vctx, combined, size, type, rows,
                                        cols, 1);
    free(combined);
    return buf;
}

static void cuda_buffer_destroy(void *vctx, void *buffer) {
    BnCudaCtx *ctx = (BnCudaCtx *)vctx;
    if (cuda_ctx_set_device(ctx) != 0) return;
    BnCudaBuffer *buf = (BnCudaBuffer *)buffer;
    if (!buf) return;
    if (buf->mmq_data) cudaFree(buf->mmq_data);
    if (buf->f16_data) cudaFree(buf->f16_data);
    if (buf->f32_data) cudaFree(buf->f32_data);
    if (buf->data) cudaFree(buf->data);
    free(buf);
}

static int cuda_cublas_matmul_f16_preconverted(BnCudaCtx *ctx, float *d_out,
                                               const BnCudaBuffer *w,
                                               const void *d_x_f16,
                                               int rows, int cols,
                                               int n_tokens);

/* Sixteen lanes per block preserve the reference input-scale accumulation. */
static __global__ void q3k_dot_matvec_mmvq_kernel(float *out,
        const void *weights, const BnCudaBlockQ8_1 *input,
        int rows, int cols, const float *bias, size_t out_offset) {
    __shared__ float partial[3][32];
    int tid = threadIdx.x, lane = tid & 31, warp = tid / 32;
    int row = blockIdx.x, token = blockIdx.y, nwarps = blockDim.x / 32;
    int blocks = cols / 256, group = tid % 16;
    float sum = 0.0f;
    for (int b = tid / 16; b < blocks; b += blockDim.x / 16) {
        const BnBlockQ3K *w = (const BnBlockQ3K *)weights + (size_t)row * blocks + b;
        int half = group / 8, off = (group % 8) * 4;
        float part = 0.0f;
        for (int i = 0; i < 4; i++) {
            int g = half * 8 + (group % 8) / 4 + 2 * i;
            int scale = ((w->scales[g % 8] >> (4 * (g / 8))) & 15) |
                        (((w->scales[8 + g % 4] >> (2 * (g / 4))) & 3) << 4);
            const BnCudaBlockQ8_1 *x = input + (size_t)token * (cols / 32) + b * 8 + half * 4 + i;
            int dot = 0;
            for (int j = 0; j < 4; j++) {
                int q = ((w->qs[group * 4 + j] >> (2 * i)) & 3) -
                        ((w->hmask[off + j] & (1 << (half * 4 + i))) ? 0 : 4);
                dot += q * (int)x->qs[off + j];
            }
            dot *= scale - 32;
            part = fmaf(cuda_fp16_to_fp32(x->d), (float)dot, part);
        }
        sum = fmaf(cuda_fp16_to_fp32(w->d), part, sum);
    }
    if (warp) partial[warp - 1][lane] = sum;
    __syncthreads();
    if (!warp) {
        for (int i = 0; i < nwarps - 1; i++) sum += partial[i][lane];
        for (int i = 16; i > 0; i /= 2) sum += __shfl_xor_sync(0xffffffffu, sum, i);
        if (!lane) {
            if (bias) sum += bias[row];
            out[out_offset + (size_t)token * rows + row] = sum;
        }
    }
}

/* Two lanes decode each block; preserve the reference MMVQ reduction order. */
static __global__ void iq4nl_dot_matvec_mmvq_kernel(float *out,
        const void *weights, const BnCudaBlockQ8_1 *input,
        int rows, int cols, const float *bias, size_t out_offset) {
    __shared__ float partial[3][32];
    int tid = threadIdx.x, lane = tid & 31, warp = tid / 32;
    int row = blockIdx.x, token = blockIdx.y, nwarps = blockDim.x / 32;
    int blocks = cols / 32, group = tid & 1;
    float sum = 0.0f;
    for (int b = tid / 2; b < blocks; b += blockDim.x / 2) {
        const BnCudaBlockQ8_1 *x = input + (size_t)token * blocks + b;
        const BnBlockIQ4NL *w = (const BnBlockIQ4NL *)weights + (size_t)row * blocks + b;
        int dot = 0;
        for (int j = 0; j < 8; j++) {
            int index = group * 8 + j;
            dot += (int)bn_kvalues_iq4nl[w->qs[index] & 15] * (int)x->qs[index];
            dot += (int)bn_kvalues_iq4nl[w->qs[index] >> 4] * (int)x->qs[index + 16];
        }
        float d = cuda_fp16_to_fp32(w->d) * cuda_fp16_to_fp32(x->d);
        sum = fmaf(d, (float)dot, sum);
    }
    if (warp) partial[warp - 1][lane] = sum;
    __syncthreads();
    if (!warp) {
        for (int i = 0; i < nwarps - 1; i++) sum += partial[i][lane];
        for (int i = 16; i > 0; i /= 2) sum += __shfl_xor_sync(0xffffffffu, sum, i);
        if (!lane) {
            if (bias) sum += bias[row];
            out[out_offset + (size_t)token * rows + row] = sum;
        }
    }
}

/* Eight threads decode each block; lane partials retain MMVQ reduction order. */
static __global__ void scaled_subblock_dot_matvec_mmvq_kernel(float *out,
        const void *weights, const BnCudaBlockQ8_1 *input,
        int rows, int cols, int type, const float *bias, size_t out_offset) {
    __shared__ float partial[3][32];
    int tid = threadIdx.x, lane = tid & 31, warp = tid / 32;
    int row = blockIdx.x, token = blockIdx.y, nwarps = blockDim.x / 32;
    int blocks = cols / 256, group = tid % 8;
    float sum = 0.0f;
    for (int b = tid / 8; b < blocks; b += blockDim.x / 8) {
        const BnCudaBlockQ8_1 *x = input + (size_t)token * (cols / 32) + b * 8 + group;
        int dot = 0;
        float d;
        if (type == BN_GGUF_TENSOR_IQ4_XS) {
            const BnBlockIQ4XS *v = (const BnBlockIQ4XS *)weights + (size_t)row * blocks + b;
            for (int j = 0; j < 32; j++) {
                int q = (v->qs[group * 16 + j % 16] >> (4 * (j / 16))) & 15;
                dot += (int)bn_kvalues_iq4nl[q] * (int)x->qs[j];
            }
            int scale = ((v->scales_l[group / 2] >> (4 * (group & 1))) & 15) |
                        (((v->scales_h >> (2 * group)) & 3) << 4);
            dot *= scale - 32;
            d = cuda_fp16_to_fp32(v->d) * cuda_fp16_to_fp32(x->d);
        } else {
            const BnBlockIQ3S *w = (const BnBlockIQ3S *)weights +
                                   (size_t)row * blocks + b;
            for (int j = 0; j < 32; j++) {
                int l = j / 4, k = j & 3;
                int index = w->qs[group * 8 + l] | (((w->qh[group] >> l) & 1) << 8);
                int q = (bn_iq3s_grid[index] >> (8 * k)) & 255;
                if ((w->signs[group * 4 + l / 2] >> ((l & 1) * 4 + k)) & 1) q = -q;
                dot += q * (int)x->qs[j];
            }
            dot *= 1 + 2 * ((w->scales[group / 2] >> (4 * (group & 1))) & 15);
            d = cuda_fp16_to_fp32(w->d) * cuda_fp16_to_fp32(x->d);
        }
        sum = fmaf(d, (float)dot, sum);
    }
    if (warp) partial[warp - 1][lane] = sum;
    __syncthreads();
    if (!warp) {
        for (int i = 0; i < nwarps - 1; i++) sum += partial[i][lane];
        for (int i = 16; i > 0; i /= 2) sum += __shfl_xor_sync(0xffffffffu, sum, i);
        if (!lane) {
            if (bias) sum += bias[row];
            out[out_offset + (size_t)token * rows + row] = sum;
        }
    }
}

static int cuda_matmul_device_out(BnCudaCtx *ctx, float *d_dst,
                                  const BnCudaBuffer *w, const float *d_x,
                                  int rows, int cols, int n_tokens,
                                  int type);

#include "quant/mxfp4_cuda.cuh"
#include "quant/kquant_routed_cuda.cuh"

/* Gate and up use the same route and quantized input. Keep each projection's
 * exact MMVQ accumulation order while sharing the block and input traversal. */
static __global__ void q4k_routed_gateup_mmvq_kernel(
    float *gate_out, float *up_out, float *mid, const BnBlockQ4K *gate,
    const BnBlockQ4K *up, const BnCudaBlockQ8_1 *x, int rows, int cols,
    const int *ids, int repeat, int act_type) {
    __shared__ float gate_partial[3][32];
    __shared__ float up_partial[3][32];
    int row = blockIdx.x;
    int item = blockIdx.y;
    int tid = threadIdx.x;
    int lane = tid & 31;
    int warp = tid >> 5;
    int nb = cols / BN_QK_K;
    float gate_sum = 0.0f;
    float up_sum = 0.0f;
    for (int b = tid / 16; b < nb; b += blockDim.x / 16) {
        size_t wi = ((size_t)ids[item] * rows + row) * nb + b;
        const BnCudaBlockQ8_1 *xb =
            x + (size_t)(item / repeat) * (cols / 32) + b * 8;
        int iqs = 2 * (tid & 15);
        gate_sum += cuda_vec_dot_q4k_q8_1(gate + wi, xb, iqs);
        up_sum += cuda_vec_dot_q4k_q8_1(up + wi, xb, iqs);
    }
    if (warp) {
        gate_partial[warp - 1][lane] = gate_sum;
        up_partial[warp - 1][lane] = up_sum;
    }
    __syncthreads();
    if (!warp) {
#pragma unroll
        for (int i = 0; i < 3; i++) {
            gate_sum += gate_partial[i][lane];
            up_sum += up_partial[i][lane];
        }
        for (int offset = 16; offset; offset >>= 1) {
            gate_sum += __shfl_xor_sync(0xffffffffu, gate_sum, offset);
            up_sum += __shfl_xor_sync(0xffffffffu, up_sum, offset);
        }
        if (!lane) {
            size_t oi = (size_t)item * rows + row;
            gate_out[oi] = gate_sum;
            up_out[oi] = up_sum;
            mid[oi] = cuda_ffn_activation(gate_sum, act_type) * up_sum;
        }
    }
}
#include "quant/q5_1_cuda.cuh"
#include "quant/q4_cuda.cuh"

static int cuda_q4_batch_matmul(BnCudaCtx *ctx, float *out,
        const BnCudaBuffer *w, const float *input,
        int rows, int cols, int nt, cudaStream_t stream,
        const BnGPUMoEExpertBatchPlan *routed = NULL,
        int geometry_rows = 0, int row_offset = 0) {
    if (!ctx || ctx->compute_capability != 1200 || rows <= 0 ||
        rows > INT_MAX-127 || cols <= 0 || cols%32 || nt <= 0 ||
        nt > INT_MAX/cols || cuda_ensure_q8_1(ctx, cols*nt) != 0) return -1;
    if (!geometry_rows) geometry_rows = rows;
    if (geometry_rows < rows || geometry_rows > INT_MAX-127 || row_offset < 0 ||
        row_offset > geometry_rows - rows) return -1;
    int total_tokens = routed ? routed->total_tokens : nt;
    int experts = routed ? routed->n_experts : 1;
    int expert = routed ? routed->expert_index : 0;
    if (total_tokens < nt || total_tokens > INT_MAX-127 || experts <= 0 ||
        expert < 0 || expert >= experts) return -1;
    /* Backend scratch is re-quantized on each use. Never reuse integer-qsum
     * contents as original-sum contents, despite identical block sizes. */
    BnQ4CudaInput *xq = (BnQ4CudaInput *)ctx->d_q8_1;
    if (total_tokens <= 8) {
        q4_quantize_mmvq<<<dim3(cols/32,nt),32,0,stream>>>(xq,input,cols);
        int nw = routed && total_tokens > 1 ? 1 : (nt <= 4 ? 4 : 2);
        q4_mmvq<<<dim3(rows,nt),nw*32,0,stream>>>(out,
            (const BnBlockQ4_0 *)w->data,xq,rows,cols,nw,NULL,0);
    } else {
        const int widths[] = {8,16,24,32,40,48,64,80,96,112,128};
        int jwidth=8,token_tiles=INT_MAX,nsm=0;
        for(size_t i=0;i<sizeof(widths)/sizeof(widths[0]);i++) {
            int width=widths[i];
            if(geometry_rows%128 && (width&(width-1))) continue;
            int count=(total_tokens-1)/width+1;
            if(count<token_tiles){token_tiles=count;jwidth=width;}
        }
        if(cudaDeviceGetAttribute(&nsm,cudaDevAttrMultiProcessorCount,
                                  ctx->device)!=cudaSuccess || nsm<=0) return -1;
        int64_t limit=((INT64_C(1)<<30)-1)/(cols/32);
        int64_t tiles=(geometry_rows-1)/128+1;
        if (tiles > limit/token_tiles || tiles*token_tiles > limit/experts)
            return -1;
        tiles *= (int64_t)token_tiles*experts;
        int64_t waves=(tiles+nsm-1)/nsm;
        int64_t grid=100*tiles/((int64_t)nsm*waves)>=90?tiles:nsm;
        if(grid>INT_MAX) return -1;
        q4_quantize_mmq<<<dim3(cols/32,nt),32,0,stream>>>(xq,input,cols);
        if (nt >= 128 && jwidth % 64 == 0)
            q4_mmq_mma_tile<false,8,2><<<dim3((rows+31)/32,(nt+63)/64),256,0,stream>>>(
                out,(const BnBlockQ4_0 *)w->data,xq,NULL,rows,cols,nt,
                total_tokens,expert,experts,1,1,jwidth,(int)grid,
                geometry_rows,row_offset);
        else
            q4_mmq<<<dim3((rows+31)/32,(nt+3)/4),128,0,stream>>>(out,
                (const BnBlockQ4_0 *)w->data,xq,rows,cols,nt,jwidth,(int)grid,total_tokens,expert,experts,geometry_rows,row_offset);
    }
    return cudaGetLastError()==cudaSuccess?0:-1;
}


#ifdef BN_CUDA_MXFP4_SM120
static int cuda_mxfp4_batch_matmul(BnCudaCtx *ctx, float *out,
        const BnCudaBuffer *weights, const float *input,
        int rows, int cols, int n_tokens, cudaStream_t stream) {
    if (!ctx || ctx->compute_capability != 1200 || rows <= 0 ||
        rows > INT_MAX - 127 || cols <= 0 || cols % 32 ||
        n_tokens <= 0 || n_tokens > INT_MAX / cols ||
        cuda_ensure_q8_1(ctx, cols * n_tokens) != 0)
        return -1;
    if (n_tokens <= 8) {
        BnCudaBlockQ8_1 *xq = (BnCudaBlockQ8_1 *)ctx->d_q8_1;
        quantize_q8_1_batch_kernel<<<dim3(cols / 32, n_tokens), 32, 0, stream>>>(
            xq, input, cols, n_tokens);
        mxfp4_mmvq_kernel<<<dim3(rows, n_tokens), n_tokens <= 4 ? 128 : 64, 0, stream>>>(
            out, (const BnBlockMXFP4 *)weights->data, xq, rows, cols, NULL, 0);
    } else {
        const int widths[] = {8, 16, 24, 32, 40, 48, 64, 80, 96, 112, 128};
        int jwidth = 8, token_tiles = INT_MAX, nsm = 0;
        for (size_t i = 0; i < sizeof(widths) / sizeof(widths[0]); i++) {
            int width = widths[i];
            if (rows % 128 && (width & (width - 1))) continue;
            int count = (n_tokens - 1) / width + 1;
            if (count < token_tiles) { token_tiles = count; jwidth = width; }
        }
        if (cudaDeviceGetAttribute(&nsm, cudaDevAttrMultiProcessorCount,
                                   ctx->device) != cudaSuccess || nsm <= 0)
            return -1;
        int64_t tiles = (int64_t)((rows - 1) / 128 + 1) * token_tiles;
        int64_t waves = (tiles + nsm - 1) / nsm;
        int64_t grid = 100 * tiles / ((int64_t)nsm * waves) >= 90 ? tiles : nsm;
        if (grid > INT_MAX) return -1;
        /* Existing backend scratch is larger than packed FP4 inputs. No
         * activation storage or prepared layout is attached to weights. */
        BnBlockMXFP4 *xq = (BnBlockMXFP4 *)ctx->d_q8_1;
        mxfp4_quantize_mmq_kernel<<<dim3(cols / 32, n_tokens), 32, 0, stream>>>(
            xq, input, cols);
        mxfp4_mmq_kernel<<<dim3((rows + 15) / 16, (n_tokens + 7) / 8), 32, 0, stream>>>(
            out, (const BnBlockMXFP4 *)weights->data, xq,
            rows, cols, n_tokens, jwidth, (int)grid);
    }
    return cudaGetLastError() == cudaSuccess ? 0 : -1;
}
#endif

static int cuda_kquant_batch_input_enabled(const BnCudaCtx *ctx, int type,
                                          int n_tokens) {
    if (bn_quant_format_has_cap(type, BN_QUANT_CAP_GPU_MMQ_BLOCK32_SIGNED_NIBBLE))
        return ctx && ctx->compute_capability == 1200 && n_tokens > 0;
    if (bn_quant_format_has_cap(type, BN_QUANT_CAP_GPU_MMQ_BLOCK32_FP4)) {
#ifdef BN_CUDA_MXFP4_SM120
        return ctx && ctx->compute_capability == 1200 && n_tokens > 0;
#else
        return 0;
#endif
    }
    if (!ctx || ctx->compute_capability < 750 ||
        !(bn_quant_format_has_cap(type, BN_QUANT_CAP_GPU_MMQ_ORIGINAL_SUM) ||
          bn_quant_format_has_cap(type, BN_QUANT_CAP_GPU_MMQ_F32_SCALE)) ||
        bn_gpu_policy_kquant_dot_enabled(ctx->runtime_policy))
        return 0;
    /* Match the reference MMVQ/MMQ boundary for NVIDIA tensor-core GPUs.
     * The arithmetic contract changes here, not just the launch geometry. */
    if (bn_quant_format_has_cap(type, BN_QUANT_CAP_GPU_MMVQ_SUBBLOCK16_INPUT_SCALE))
        return ctx->compute_capability == 1200 && n_tokens > 0;
    if (bn_quant_format_has_cap(type, BN_QUANT_CAP_GPU_MMVQ_BLOCK32_CODEBOOK_FP16))
        return ctx->compute_capability == 1200 && n_tokens > 0;
    int subblock16 = bn_quant_format_has_cap(type, BN_QUANT_CAP_GPU_MMQ_SUBBLOCK16);
    int subblock32 = bn_quant_format_has_cap(type, BN_QUANT_CAP_GPU_MMQ_SUBBLOCK32);
    if (bn_quant_format_has_cap(type, BN_QUANT_CAP_GPU_MMVQ_SUBBLOCK32_INT_SCALE))
        return ctx->compute_capability == 1200 && n_tokens > 0;
    if (subblock16 || subblock32)
        return ctx->compute_capability == 1200 && n_tokens > (subblock16 ? 5 : 8);
    int f32_scale = bn_quant_format_has_cap(type, BN_QUANT_CAP_GPU_MMQ_F32_SCALE);
    if (f32_scale && bn_gpu_policy_cuda_down_kquant_dot_forced(ctx->runtime_policy))
        return 0;
    int max_mmvq = ctx->compute_capability == 1200 ? (f32_scale ? 7 : 5)
                  : ctx->compute_capability == 890 && !f32_scale ? 7 : 8;
    return n_tokens > 0 && (f32_scale || n_tokens > max_mmvq);
}

/* Quant-only handles stay cache-free. A stream-ordered temporary layout lets
 * prefill reuse the packed tensor-core path without attaching backend state
 * to the immutable weight handle. */
struct BnCudaMmqScratch {
    void *data;
    cudaStream_t stream;
    ~BnCudaMmqScratch() {
        if (data) (void)cudaFreeAsync(data, stream);
    }
};

static int cuda_kquant_batch_matmul(BnCudaCtx *ctx, float *out,
                                  const BnCudaBuffer *w, const float *input,
                                  int rows, int cols, int n_tokens, int type,
                                  cudaStream_t stream,
                                  const BnCudaBlockQ8Mmq *prepared_xq = NULL) {
    if (bn_quant_format_has_cap(type, BN_QUANT_CAP_GPU_MMQ_BLOCK32_SIGNED_NIBBLE))
        return cuda_q4_batch_matmul(ctx,out,w,input,rows,cols,n_tokens,stream);
#ifdef BN_CUDA_MXFP4_SM120
    if (bn_quant_format_has_cap(type, BN_QUANT_CAP_GPU_MMQ_BLOCK32_FP4))
        return cuda_mxfp4_batch_matmul(ctx, out, w, input,
                                       rows, cols, n_tokens, stream);
#endif
    int signed_subblocks =
        bn_quant_format_has_cap(type, BN_QUANT_CAP_GPU_MMQ_SUBBLOCK16) ||
        bn_quant_format_has_cap(type, BN_QUANT_CAP_GPU_MMQ_SUBBLOCK32);
    const BnQuantFormatOps *format = bn_quant_format_ops(type);
    int block_elems = signed_subblocks && format ? format->block_elems : BN_QK_K;
    if (rows <= 0 || cols <= 0 || block_elems <= 0 || cols % block_elems ||
        n_tokens <= 0 || n_tokens > INT_MAX / cols ||
        cuda_ensure_q8_1(ctx, cols * n_tokens) != 0)
        return -1;
    if (bn_quant_format_has_cap(type, BN_QUANT_CAP_GPU_MMVQ_SUBBLOCK16_INPUT_SCALE) && n_tokens <= 5) {
        BnCudaBlockQ8_1 *xq = (BnCudaBlockQ8_1 *)ctx->d_q8_1;
        quantize_q8_1_batch_kernel<<<dim3(cols / 32, n_tokens), 32, 0, stream>>>(xq, input, cols, n_tokens);
        q3k_dot_matvec_mmvq_kernel<<<dim3(rows, n_tokens), n_tokens <= 4 ? 128 : 64, 0, stream>>>(out, w->data, xq, rows, cols, NULL, 0);
        return cudaGetLastError() == cudaSuccess ? 0 : -1;
    }
    if (bn_quant_format_has_cap(type, BN_QUANT_CAP_GPU_MMVQ_BLOCK32_CODEBOOK_FP16) && n_tokens <= 8) {
        BnCudaBlockQ8_1 *xq = (BnCudaBlockQ8_1 *)ctx->d_q8_1;
        quantize_q8_1_batch_kernel<<<dim3(cols / 32, n_tokens), 32, 0, stream>>>(xq, input, cols, n_tokens);
        iq4nl_dot_matvec_mmvq_kernel<<<dim3(rows, n_tokens), n_tokens <= 4 ? 128 : 64, 0, stream>>>(out, w->data, xq, rows, cols, NULL, 0);
        return cudaGetLastError() == cudaSuccess ? 0 : -1;
    }
    if (bn_quant_format_has_cap(type, BN_QUANT_CAP_GPU_MMVQ_SUBBLOCK32_INT_SCALE) && n_tokens <= 8) {
        BnCudaBlockQ8_1 *xq = (BnCudaBlockQ8_1 *)ctx->d_q8_1;
        quantize_q8_1_batch_kernel<<<dim3(cols / 32, n_tokens), 32, 0, stream>>>(xq, input, cols, n_tokens);
        if (bn_backend_quant_supports_packed_codebook_matvec(type) &&
            w->mmq_data)
            iq4xs_dot_matvec_packed_kernel
                <<<dim3(rows, n_tokens), n_tokens <= 4 ? 128 : 64,
                   0, stream>>>(out,
                (const BnCudaIQ4XSPackedBlock *)w->mmq_data,
                xq, rows, cols, NULL, 0);
        else
            scaled_subblock_dot_matvec_mmvq_kernel
                <<<dim3(rows, n_tokens), n_tokens <= 4 ? 128 : 64,
                   0, stream>>>(out, w->data, xq, rows, cols, type, NULL, 0);
        return cudaGetLastError() == cudaSuccess ? 0 : -1;
    }
    /* Small Q6_K batches use the same FP16-scale input and accumulation
     * as decode. Larger batches use the MMQ FP32-scale contract below. */
    int f32_scale = bn_quant_format_has_cap(type, BN_QUANT_CAP_GPU_MMQ_F32_SCALE);
    int max_mmvq = ctx->compute_capability == 1200 ? 7 : 8;
    if (f32_scale && !signed_subblocks && n_tokens <= max_mmvq) {
        BnCudaBlockQ8_1 *xq = (BnCudaBlockQ8_1 *)ctx->d_q8_1;
        quantize_q8_1_batch_kernel<<<dim3(cols / 32, n_tokens), 32,
                                     0, stream>>>(xq, input, cols, n_tokens);
        for (int t = 0; t < n_tokens; t++) {
            if (n_tokens >= 5)
                q6k_dot_matvec_mmvq_2warp_kernel<<<rows, 64, 0, stream>>>(
                    out, (const BnBlockQ6K *)w->data,
                    xq + (size_t)t * (cols / 32), NULL, rows, cols, (size_t)t * rows);
            else
                q6k_dot_matvec_mmvq_kernel<<<rows, 128, 0, stream>>>(
                    out, (const BnBlockQ6K *)w->data,
                    xq + (size_t)t * (cols / 32), NULL, rows, cols, (size_t)t * rows);
        }
        return cudaGetLastError() == cudaSuccess ? 0 : -1;
    }
    BnCudaBlockQ8Mmq *xq = prepared_xq
        ? (BnCudaBlockQ8Mmq *)prepared_xq
        : (BnCudaBlockQ8Mmq *)ctx->d_q8_1;
    if (!prepared_xq)
        quantize_mmq_input_kernel<<<dim3((cols / 32 + 15) / 16,
                                           n_tokens), 512,
                                           0, stream>>>(xq, input, cols,
                bn_quant_format_has_cap(type, BN_QUANT_CAP_GPU_MMQ_F32_SCALE));
    BnCudaMmqScratch scratch = {NULL, stream};
    BnCudaBuffer packed_view;
    if (ctx->compute_capability == 1200 && n_tokens >= 16 &&
        !w->mmq_data &&
        (bn_quant_format_is_q4k(type) || bn_quant_format_is_q5k(type))) {
        size_t bytes = cuda_buffer_kquant_mmq_bytes(ctx, type, rows, cols);
        if (bytes && bytes != SIZE_MAX &&
            cudaMallocAsync(&scratch.data, bytes, stream) == cudaSuccess) {
            size_t blocks = (size_t)rows * (size_t)cols / BN_QK_K;
            if (bn_quant_format_is_q4k(type))
                pack_q4k_mmq_kernel<<<blocks, BN_QK_K, 0, stream>>>(
                    (BnCudaKQuantMmqBlock *)scratch.data,
                    (const BnBlockQ4K *)w->data, blocks);
            else
                pack_q5k_mmq_kernel<<<blocks, BN_QK_K, 0, stream>>>(
                    (BnCudaKQuantMmqBlock *)scratch.data,
                    (const BnBlockQ5K *)w->data, blocks);
            if (cudaGetLastError() != cudaSuccess) return -1;
            packed_view = *w;
            packed_view.mmq_data = scratch.data;
            packed_view.mmq_size = bytes;
            w = &packed_view;
        } else {
            scratch.data = NULL;
            (void)cudaGetLastError();
        }
    }
    if (ctx->compute_capability == 1200) {
        const int widths[] = {8, 16, 24, 32, 40, 48, 64, 80, 96, 112, 128};
        int jwidth = 8, token_tiles = INT_MAX, nsm = 0;
        for (size_t i = 0; i < sizeof(widths) / sizeof(widths[0]); i++) {
            int width = widths[i];
            if (rows % 128 && (width & (width - 1))) continue;
            int count = (n_tokens - 1) / width + 1;
            if (count < token_tiles) { token_tiles = count; jwidth = width; }
        }
        if (cudaDeviceGetAttribute(&nsm, cudaDevAttrMultiProcessorCount,
                                    ctx->device) != cudaSuccess || nsm <= 0)
            return -1;
        int64_t tiles = (int64_t)((rows - 1) / 128 + 1) * token_tiles;
        int64_t waves = (tiles + nsm - 1) / nsm;
        /* A sufficiently full last wave uses independent output tiles.
         * Otherwise the reference distributes K work over one SM wave. */
        int64_t grid = 100 * tiles / ((int64_t)nsm * waves) >= 90 ? tiles : nsm;
        if (grid > INT_MAX) return -1;
        int64_t ref_tiles = (int64_t)((rows + 127) / 128) *
                            ((n_tokens + 127) / 128);
        int ref_split_bound = (int)((grid + ref_tiles - 1) / ref_tiles) +
                              (grid != ref_tiles);
        if (bn_quant_format_is_q6k(type) && n_tokens >= 16 && w->mmq_data) {
            if (n_tokens >= 128 && ref_split_bound > cols / BN_QK_K) {
                dim3 mmq_grid((rows + 63) / 64,
                              (n_tokens + 31) / 32, 1);
                q6k_mmq_packed_kernel<64, 32, 2>
                    <<<mmq_grid, 256, 0, stream>>>(
                        out, (const BnCudaQ6KMmqBlock *)w->mmq_data,
                        (const BnCudaBlockQ8MmqF32 *)xq, rows, cols,
                        n_tokens, jwidth, (int)grid);
            } else if (n_tokens >= 64) {
                int tile_rows = (rows + 127) / 128;
                int tile_tokens = (n_tokens + 63) / 64;
                int split_tiles = tile_rows * ((n_tokens + 127) / 128);
                int split_count = (nsm + split_tiles - 1) / split_tiles;
                if (n_tokens >= 128 && (int64_t)grid != split_tiles)
                    split_count++;
                int n_bpr = cols / BN_QK_K;
                if (split_count > n_bpr) split_count = n_bpr;
                if (split_count < 1) split_count = 1;
                /* The kernel combines reference K partitions in order;
                 * long prefill is faster without partial buffers/fixup. */
                if (n_tokens >= 128) split_count = 1;
                size_t partial_values = (size_t)split_count * rows * n_tokens;
                if (split_count > 1 &&
                    cuda_ensure_mmq_fixup(ctx, partial_values) != 0)
                    return -1;
                dim3 mmq_grid(tile_rows, tile_tokens, split_count);
                q6k_mmq_128x64_kernel<<<mmq_grid, 512, 0, stream>>>(
                    split_count > 1 ? ctx->d_mmq_fixup : out,
                        (const BnCudaQ6KMmqBlock *)w->mmq_data,
                        (const BnCudaBlockQ8MmqF32 *)xq, rows, cols,
                        n_tokens, split_count, NULL, NULL, NULL, NULL,
                        NULL, 0, NULL, 0,
                        n_tokens >= 128 ? jwidth : 0,
                        n_tokens >= 128 ? (int)grid : 0);
                int fixup_threads = 256;
                size_t values = (size_t)rows * n_tokens;
                if (n_tokens >= 128 && split_count > 1)
                    kquant_mmq_reference_fixup_kernel<<<
                        (unsigned)((values + fixup_threads - 1) / fixup_threads),
                        fixup_threads, 0, stream>>>(
                            out, ctx->d_mmq_fixup, rows, cols,
                            n_tokens, jwidth, (int)grid);
                else if (split_count > 1)
                    q4k_mmq_split_fixup_kernel<<<
                        (unsigned)((values + fixup_threads - 1) / fixup_threads),
                        fixup_threads, 0, stream>>>(
                            out, ctx->d_mmq_fixup, rows, n_tokens,
                            split_count, 0);
            } else if (n_tokens >= 32) {
                dim3 mmq_grid((rows + 63) / 64,
                              (n_tokens + 31) / 32, 1);
                q6k_mmq_packed_kernel<64, 32, 2>
                    <<<mmq_grid, 256, 0, stream>>>(
                        out, (const BnCudaQ6KMmqBlock *)w->mmq_data,
                        (const BnCudaBlockQ8MmqF32 *)xq, rows, cols,
                        n_tokens, jwidth, (int)grid);
            } else {
                dim3 mmq_grid((rows + 127) / 128,
                              (n_tokens + 15) / 16, 1);
                q6k_mmq_packed_kernel<128, 16, 1>
                    <<<mmq_grid, 256, 0, stream>>>(
                        out, (const BnCudaQ6KMmqBlock *)w->mmq_data,
                        (const BnCudaBlockQ8MmqF32 *)xq, rows, cols,
                        n_tokens, jwidth, (int)grid);
            }
        } else if (bn_quant_format_has_cap(type,
                       BN_QUANT_CAP_GPU_MMVQ_BLOCK32_CODEBOOK_FP16) &&
                   n_tokens >= 16 && cols % 256 == 0 &&
                   bn_gpu_policy_cuda_iq4nl_t8_enabled(
                       ctx->runtime_policy)) {
            dim3 mmq_grid((rows + 15) / 16, (n_tokens + 31) / 32);
            if (jwidth >= 32 && jwidth % 32 == 0)
                iq4_codebook_mmq_mma_ordered_t8_kernel<false, true, false,
                                                       true><<<mmq_grid, 128,
                                                               0, stream>>>(
                    out, w->data, (const BnCudaBlockQ8MmqF32 *)xq,
                    rows, cols, n_tokens, jwidth, (int)grid);
            else {
                iq4_codebook_mmq_mma_ordered_t8_kernel<false, true, true,
                                                       true><<<mmq_grid, 128,
                                                               0, stream>>>(
                    out, w->data, (const BnCudaBlockQ8MmqF32 *)xq,
                    rows, cols, n_tokens, jwidth, (int)grid);
                iq4_codebook_mmq_mma_ordered_t8_kernel<false, false, true,
                                                       true><<<mmq_grid, 128,
                                                               0, stream>>>(
                    out, w->data, (const BnCudaBlockQ8MmqF32 *)xq,
                    rows, cols, n_tokens, jwidth, (int)grid);
            }
        } else if (bn_quant_format_supports_packed_codebook_matvec(type) &&
                   n_tokens >= 16 &&
                   cols % 256 == 0) {
            if (ctx->compute_capability >= 800) {
                /* A multiple-of-32 width keeps all four token warps in the
                 * same Stream-K partition, so their A tile may be shared. */
                if (w->mmq_data && jwidth >= 32 && jwidth % 32 == 0)
                    iq4_codebook_mmq_mma_ordered_t8_kernel<true, true><<<
                        dim3((rows + 15) / 16, (n_tokens + 31) / 32), 128,
                        0, stream>>>(
                        out, w->mmq_data,
                        (const BnCudaBlockQ8MmqF32 *)xq,
                        rows, cols, n_tokens, jwidth, (int)grid);
                else if (w->mmq_data) {
                    dim3 mmq_grid((rows + 15) / 16,
                                  (n_tokens + 31) / 32);
                    iq4_codebook_mmq_mma_ordered_t8_kernel<true, true, true><<<
                        mmq_grid, 128, 0, stream>>>(
                        out, w->mmq_data,
                        (const BnCudaBlockQ8MmqF32 *)xq,
                        rows, cols, n_tokens, jwidth, (int)grid);
                    iq4_codebook_mmq_mma_ordered_t8_kernel<true, false, true><<<
                        mmq_grid, 128, 0, stream>>>(
                        out, w->mmq_data,
                        (const BnCudaBlockQ8MmqF32 *)xq,
                        rows, cols, n_tokens, jwidth, (int)grid);
                }
                else if (jwidth >= 32 && jwidth % 32 == 0)
                    iq4_codebook_mmq_mma_ordered_t8_kernel<false, true><<<
                        dim3((rows + 15) / 16, (n_tokens + 31) / 32), 128,
                        0, stream>>>(
                        out, w->data,
                        (const BnCudaBlockQ8MmqF32 *)xq,
                        rows, cols, n_tokens, jwidth, (int)grid);
                else
                    iq4_codebook_mmq_mma_ordered_t8_kernel<false, false><<<
                        dim3((rows + 15) / 16, (n_tokens + 31) / 32), 128,
                        0, stream>>>(
                        out, w->data,
                        (const BnCudaBlockQ8MmqF32 *)xq,
                        rows, cols, n_tokens, jwidth, (int)grid);
            }
            else
                iq4xs_mmq_ordered_t8_kernel<<<
                    dim3((rows + 15) / 16, (n_tokens + 7) / 8), 128,
                    0, stream>>>(
                    out, (const BnBlockIQ4XS *)w->data,
                    (const BnCudaBlockQ8MmqF32 *)xq,
                    rows, cols, n_tokens, jwidth, (int)grid);
        } else if (type == BN_GGUF_TENSOR_IQ3_S && n_tokens >= 16 &&
                   cols % 256 == 0) {
            iq3s_mmq_ordered_t8_kernel<<<dim3((rows + 15) / 16,
                                              (n_tokens + 7) / 8), 128,
                                           0, stream>>>(
                out, (const BnBlockIQ3S *)w->data,
                (const BnCudaBlockQ8MmqF32 *)xq,
                rows, cols, n_tokens, jwidth, (int)grid);
        } else if (bn_quant_format_is_q3k(type) && n_tokens >= 16 &&
                   cols % 256 == 0) {
            q3k_mmq_ordered_t8_kernel<<<dim3((rows + 15) / 16,
                                              (n_tokens + 7) / 8), 128,
                                         0, stream>>>(
                out, (const BnBlockQ3K *)w->data,
                (const BnCudaBlockQ8MmqF32 *)xq,
                rows, cols, n_tokens, jwidth, (int)grid);
        } else if (signed_subblocks) {
            signed_mmq_ordered_kernel<<<dim3((rows + 15) / 16, n_tokens), 128,
                                         0, stream>>>(
                out, w->data, (const BnCudaBlockQ8MmqF32 *)xq,
                rows, cols, type, n_tokens, jwidth, (int)grid);
        } else if (((bn_quant_format_is_q4k(type) && n_tokens >= 8) ||
                    (bn_quant_format_is_q5k(type) && n_tokens >= 16)) &&
                   w->mmq_data) {
            if (n_tokens >= 64) {
                if ((bn_quant_format_is_q5k(type) ||
                     bn_quant_format_is_q4k(type)) && n_tokens >= 128) {
                    /* Preserve reference accumulation for interior prompt
                     * rows while reusing weights across token phases. */
                    dim3 mmq_grid((rows + 127) / 128,
                                  (n_tokens + 63) / 64, 1);
                    kquant_mmq_packed_kernel<128, 64, 2, true, false, true,
                                             true>
                        <<<mmq_grid, 512, 0, stream>>>(
                            out, (const BnCudaKQuantMmqBlock *)w->mmq_data,
                            (const BnCudaBlockQ8_1 *)xq, rows, cols,
                            n_tokens, 0, jwidth, (int)grid);
                } else {
                    dim3 mmq_grid((rows + 63) / 64,
                                  (n_tokens + 63) / 64, 1);
                    if (n_tokens >= 128)
                        kquant_mmq_packed_kernel<64, 64, 4, true, true>
                            <<<mmq_grid, 512, 0, stream>>>(
                                out, (const BnCudaKQuantMmqBlock *)w->mmq_data,
                                (const BnCudaBlockQ8_1 *)xq, rows, cols,
                                n_tokens, 0, jwidth, (int)grid);
                    else
                        kquant_mmq_packed_kernel<64, 64, 4, true, false>
                            <<<mmq_grid, 512, 0, stream>>>(
                                out, (const BnCudaKQuantMmqBlock *)w->mmq_data,
                                (const BnCudaBlockQ8_1 *)xq, rows, cols,
                                n_tokens, 0, jwidth, (int)grid);
                }
            } else {
                /* Pad short batches to one 32-token tile: fewer wide FFN
                 * blocks and better occupancy than two 16-token tiles. */
                if (bn_quant_format_is_q4k(type) && n_tokens < 16) {
                    dim3 mmq_grid((rows + 31) / 32, 1, 1);
                    kquant_mmq_packed_kernel<32, 32, 2, true>
                        <<<mmq_grid, 128, 0, stream>>>(
                            out, (const BnCudaKQuantMmqBlock *)w->mmq_data,
                            (const BnCudaBlockQ8_1 *)xq, rows, cols,
                            n_tokens, 0, jwidth, (int)grid);
                } else {
                    dim3 mmq_grid((rows + 127) / 128,
                                  (n_tokens + 31) / 32, 1);
                    kquant_mmq_packed_kernel<128, 32, 2, true>
                        <<<mmq_grid, 512, 0, stream>>>(
                            out, (const BnCudaKQuantMmqBlock *)w->mmq_data,
                            (const BnCudaBlockQ8_1 *)xq, rows, cols,
                            n_tokens, 0, jwidth, (int)grid);
                }
            }
        } else if (bn_quant_format_is_q4k(type) && n_tokens >= 4) {
            q4k_mmq_ordered_t8_kernel<<<dim3((rows + 15) / 16,
                                                  (n_tokens + 7) / 8), 128,
                                           0, stream>>>(
                out, (const BnBlockQ4K *)w->data, xq, rows, cols, n_tokens,
                jwidth, (int)grid);
        } else if (bn_quant_format_is_q5k(type) && n_tokens >= 8) {
            q5k_mmq_ordered_t8_kernel<<<dim3((rows + 15) / 16,
                                              (n_tokens + 7) / 8), 128,
                                         0, stream>>>(
                out, (const BnBlockQ5K *)w->data, xq, rows, cols, n_tokens,
                jwidth, (int)grid);
        } else {
            kquant_mmq_ordered_kernel<<<dim3((rows + 15) / 16, n_tokens), 128,
                                           0, stream>>>(
                out, w->data, xq, rows, cols, type, n_tokens, jwidth,
                (int)grid);
        }
        cudaError_t mmq_err = cudaGetLastError();
        if (mmq_err != cudaSuccess)
            fprintf(stderr, "CUDA MMQ launch type=%d rows=%d cols=%d nt=%d: %s\n",
                    type, rows, cols, n_tokens, cudaGetErrorString(mmq_err));
        return mmq_err == cudaSuccess ? 0 : -1;
    }
    kquant_mmq_kernel<<<dim3((rows + 7) / 8, n_tokens), 256,
                                    0, stream>>>(
        out, w->data, xq, rows, cols, type);
    return cudaGetLastError() == cudaSuccess ? 0 : -1;
}

