        NULL, NULL, NULL, NULL, NULL, X, n_tokens, dim, hidden_dim,
        n_experts, k, gate_type, up_type, down_type, act_type, 0, 0, 0, 0,
        0.0f, 0, norm_topk_prob, expert_weights_scale);
