static const char *cuda_profile_name(int code) {
    if (code == BN_CUDA_PROFILE_QKV_MIXED) return "qkv_mixed";
    if (code == BN_CUDA_PROFILE_READBACK) return "readback";
    if (code == BN_CUDA_PROFILE_LOGITS) return "logits";
    if (code == BN_CUDA_PROFILE_MOE_GATEUP) return "moe_gateup";
    if (code == BN_CUDA_PROFILE_MOE_DOWN) return "moe_down";
    if (code == BN_CUDA_PROFILE_MOE_MID_QUANT) return "moe_mid_quant";
    return cuda_op_name(code);
}

static int cuda_gqa_combine_threads(int n_kv) {
    /* llama.cpp pads non-flash attention to 256 cache positions and picks
     * the first warp multiple that minimizes per-thread value pairs. */
    int padded = ((n_kv + 255) / 256) * 256;
    int best = 32;
    int iterations = (padded + 2 * best - 1) / (2 * best);
    for (int candidate = 64; candidate <= 256; candidate += 32) {
        int next = (padded + 2 * candidate - 1) / (2 * candidate);
        if (next < iterations) {
            best = candidate;
            iterations = next;
        }
    }
    return best;
}

static int cuda_op_mentions_buf(const BnGPUOp *op, int buf) {
    if (!op || buf < 0) return 0;
    if (op->op_code == BN_GPU_CODE_HC_COMBINE &&
        buf == BN_GPU_VALUE_HC_INJECT)
        return 1;
    return op->buf_in == buf || op->buf_out == buf || op->buf_aux == buf;
}

static int cuda_op_writes_buf(const BnGPUOp *op, int buf) {
    if (!op || buf < 0) return 0;
    if (op->buf_out == buf) return 1;
    switch (op->op_code) {
    case BN_GPU_CODE_RESIDUAL_ADD:
    case BN_GPU_CODE_WEIGHTED_ADD:
    case BN_GPU_CODE_WEIGHTED_ADD_SIGMOID:
    case BN_GPU_CODE_HC_COMBINE:
    case BN_GPU_CODE_HC_SCALE_SILU:
        return op->buf_in == buf;
    case BN_GPU_CODE_MATVEC_SPLIT:
    case BN_GPU_CODE_Q4K_MATVEC_SPLIT:
    case BN_GPU_CODE_Q8_MATVEC_SPLIT:
    case BN_GPU_CODE_Q5K_MATVEC_SPLIT:
        return op->buf_aux == buf || (int)op->rows == buf;
    case BN_GPU_CODE_PER_HEAD_RMSNORM:
        return op->buf_in == buf;
    default:
        return 0;
    }
}

static int cuda_op_reads_buf(const BnGPUOp *op, int buf) {
    if (!op || buf < 0) return 0;
    if (op->op_code == BN_GPU_CODE_HC_COMBINE &&
        buf == BN_GPU_VALUE_HC_INJECT)
        return 1;
    switch (op->op_code) {
    case BN_GPU_CODE_MATVEC:
    case BN_GPU_CODE_MATVEC_SPLIT:
    case BN_GPU_CODE_Q4K_MATVEC_SPLIT:
    case BN_GPU_CODE_Q8_MATVEC_SPLIT:
    case BN_GPU_CODE_Q5K_MATVEC_SPLIT:
    case BN_GPU_CODE_FUSED_GATEUP_SILU:
    case BN_GPU_CODE_MOE_ROUTE_TOPK:
    case BN_GPU_CODE_MOE_ROUTED_FFN:
    case BN_GPU_CODE_RMSNORM:
    case BN_GPU_CODE_PER_HEAD_RMSNORM:
    case BN_GPU_CODE_COPY:
    case BN_GPU_CODE_DEINTERLEAVE_Q:
    case BN_GPU_CODE_BIAS_ADD:
    case BN_GPU_CODE_SILU_ACT:
    case BN_GPU_CODE_RELU2_ACT:
    case BN_GPU_CODE_HC_SCALE_SILU:
    case BN_GPU_CODE_ROPE:
    case BN_GPU_CODE_GQA_SCORES:
    case BN_GPU_CODE_FLASH_ATTN:
        return op->buf_in == buf;
    case BN_GPU_CODE_RESIDUAL_RMSNORM:
    case BN_GPU_CODE_RESIDUAL_ADD:
    case BN_GPU_CODE_WEIGHTED_ADD:
    case BN_GPU_CODE_WEIGHTED_ADD_SIGMOID:
    case BN_GPU_CODE_SILU_GATE:
    case BN_GPU_CODE_RELU2_GATE:
    case BN_GPU_CODE_SIGMOID_GATE:
    case BN_GPU_CODE_ROPE_QK:
    case BN_GPU_CODE_HC_GATED_REDUCE:
    case BN_GPU_CODE_HC_COMBINE:
        return op->buf_in == buf || op->buf_aux == buf;
    default:
        return 0;
    }
}

static void cuda_debug_scan_activation(BnCudaCtx *ctx, int buf,
                                       const char *label, int op_index) {
    if (!ctx || buf < 0 || buf >= BN_GPU_VALUE_COUNT || !ctx->act_bufs[buf])
        return;
    size_t n = ctx->act_sizes[buf] / sizeof(float);
    if (n == 0) return;
    if (cudaStreamSynchronize(ctx->exec_stream) != cudaSuccess)
        return;
    float *tmp = (float *)malloc(n * sizeof(float));
    if (!tmp) return;
    cudaError_t err = cudaMemcpy(tmp, ctx->act_bufs[buf], n * sizeof(float),
                                 cudaMemcpyDeviceToHost);
    if (err != cudaSuccess) {
        free(tmp);
        return;
    }
    int bad = 0;
    size_t first_bad = 0;
    float min_v = INFINITY;
    float max_v = -INFINITY;
    for (size_t i = 0; i < n; i++) {
        float v = tmp[i];
        if (!isfinite(v)) {
            if (bad == 0) first_bad = i;
            bad++;
            continue;
        }
        if (v < min_v) min_v = v;
        if (v > max_v) max_v = v;
    }
    if (bad || bn_gpu_policy_cuda_nan_verbose_debug_enabled(
                   ctx->runtime_policy)) {
        fprintf(stderr,
                "[bn:gpu:cuda:nan] op=%d %s buf=%d n=%zu bad=%d first=%zu "
                "min=%.9g max=%.9g first_v=%.9g\n",
                op_index, label ? label : "?", buf, n, bad, first_bad,
                min_v, max_v, bad ? tmp[first_bad] : 0.0f);
    }
    free(tmp);
}

static int cuda_ops_look_like_decode_graph(const BnGPUOp *ops, int n_ops,
                                           int readback_buf,
                                           const float *out_host,
                                           int out_len) {
    if (!ops || n_ops < 32)
        return 0;

    int has_rope = 0;
    int has_attention = 0;
    int has_logits = 0;
    for (int i = 0; i < n_ops; i++) {
        const BnGPUOp *op = &ops[i];
        if (op->op_code == BN_GPU_CODE_ROPE ||
            op->op_code == BN_GPU_CODE_ROPE_QK)
            has_rope = 1;
        if (op->op_code == BN_GPU_CODE_FLASH_ATTN ||
            op->op_code == BN_GPU_CODE_GQA_SCORES ||
            op->op_code == BN_GPU_CODE_GQA_COMBINE)
            has_attention = 1;
        if (op->op_kind == BN_GPU_OP_LOGITS ||
            (op->op_code == BN_GPU_CODE_MATVEC &&
             op->buf_out == BN_GPU_VALUE_LOGITS))
            has_logits = 1;
    }

    int wants_logits_readback =
        readback_buf == BN_GPU_VALUE_LOGITS && out_host && out_len > 0;
    int wants_gpu_resident =
        readback_buf < 0 && !out_host && out_len <= 0;
    return has_rope && has_attention &&
           ((wants_logits_readback && has_logits) || wants_gpu_resident);
}

static int cuda_ops_have_moe(const BnGPUOp *ops, int n_ops) {
    if (!ops) return 0;
    for (int i = 0; i < n_ops; i++) {
        const BnGPUOp *op = &ops[i];
        if (cuda_op_mentions_buf(op, BN_GPU_VALUE_MOE_HB) ||
            cuda_op_mentions_buf(op, BN_GPU_VALUE_MOE_HB2) ||
            cuda_op_mentions_buf(op, BN_GPU_VALUE_MOE_OUT))
            return 1;
    }
    return 0;
}

static int cuda_ops_have_native_quant_moe_routed_ffn(const BnGPUOp *ops, int n_ops) {
    if (!ops) return 0;
    for (int i = 0; i < n_ops; i++) {
        const BnGPUOp *op = &ops[i];
        if (op->op_code == BN_GPU_CODE_MOE_ROUTED_FFN &&
            bn_backend_quant_moe_routed_op_uses_native_quant(op->type))
            return 1;
    }
    return 0;
}

static int cuda_ops_have_moe_all_active_two_kquant_routed_ffn(
    const BnGPUOp *ops, int n_ops) {
    if (!ops) return 0;
    for (int i = 0; i < n_ops; i++) {
        const BnGPUOp *op = &ops[i];
        if (op->op_code == BN_GPU_CODE_MOE_ROUTED_FFN &&
            bn_backend_quant_moe_all_active_two_kquant_routed_op(
                op->type, (int)op->p[1], (int)op->p[2], (int)op->p[3],
                (int)op->p[0], op->cols))
            return 1;
    }
    return 0;
}

static int cuda_ops_have_logits(const BnGPUOp *ops, int n_ops) {
    if (!ops) return 0;
    for (int i = 0; i < n_ops; i++) {
        const BnGPUOp *op = &ops[i];
        if (op->op_kind == BN_GPU_OP_LOGITS ||
            (op->op_code == BN_GPU_CODE_MATVEC &&
             op->buf_out == BN_GPU_VALUE_LOGITS))
            return 1;
    }
    return 0;
}

static int cuda_ops_have_moe_cublas_decode(const BnCudaCtx *ctx,
                                           const BnGPUOp *ops, int n_ops) {
    if (!ops || !bn_gpu_policy_cuda_moe_cublas_decode_enabled(
                    ctx ? ctx->runtime_policy : NULL))
        return 0;
    if (!bn_gpu_policy_all_active_two_kquant_moe_cublas_decode_enabled(
            ctx ? ctx->runtime_policy : NULL))
        return 0;
    for (int i = 0; i < n_ops; i++) {
        const BnGPUOp *op = &ops[i];
        if (op->op_code == BN_GPU_CODE_MOE_ROUTED_FFN &&
            bn_backend_quant_moe_all_active_two_kquant_routed_op(
                op->type, (int)op->p[1], (int)op->p[2], (int)op->p[3],
                (int)op->p[0], op->cols))
            return 1;
    }
    return 0;
}

static int cuda_ops_moe_max_experts(const BnGPUOp *ops, int n_ops) {
    if (!ops) return 0;
    int max_experts = 0;
    for (int i = 0; i < n_ops; i++) {
        const BnGPUOp *op = &ops[i];
        int n_experts = 0;
        if (op->op_code == BN_GPU_CODE_MOE_ROUTE_TOPK)
            n_experts = (int)op->p[0];
        else if (op->op_code == BN_GPU_CODE_MOE_ROUTED_FFN)
            n_experts = (int)op->p[1];
        if (n_experts > max_experts)
            max_experts = n_experts;
    }
    return max_experts;
}

static int cuda_buf_unused_until_write(const BnGPUOp *ops, int n_ops,
                                       int start, int buf) {
    if (!ops || buf < 0) return 0;
    for (int i = start; i < n_ops; i++) {
        if (cuda_op_reads_buf(&ops[i], buf)) return 0;
        if (cuda_op_writes_buf(&ops[i], buf)) return 1;
    }
    return 1;
}

static int cuda_find_fusable_bias(const BnGPUOp *ops, int n_ops, int start,
                                  int buf, int n) {
    if (!ops || buf < 0 || n <= 0) return -1;
    for (int i = start + 1; i < n_ops; i++) {
        const BnGPUOp *op = &ops[i];
        if (op->op_code == BN_GPU_CODE_BIAS_ADD && op->buf_in == buf &&
            (int)op->p[0] == n) {
            BnCudaBuffer *bw = (BnCudaBuffer *)op->W_buf;
            return (bw && bw->data) ? i : -1;
        }
        if (cuda_op_mentions_buf(op, buf))
            return -1;
    }
    return -1;
}

static int cuda_bias_followed_by_copy(const BnGPUOp *ops, int n_ops,
                                      int bias_idx) {
    if (!ops || bias_idx < 0 || bias_idx + 1 >= n_ops) return 0;
    const BnGPUOp *bias = &ops[bias_idx];
    const BnGPUOp *copy = &ops[bias_idx + 1];
    return bias->op_code == BN_GPU_CODE_BIAS_ADD &&
           copy->op_code == BN_GPU_CODE_COPY &&
           copy->buf_in == bias->buf_in &&
           (int)copy->p[0] == 0 &&
           copy->p[2] == bias->p[0];
}

static int cuda_execute(void *vctx, const void *ops_raw, int n_ops,
                        int readback_buf, float *out_host, int out_len) {
    BnCudaCtx *ctx = (BnCudaCtx *)vctx;
    const BnGPUOp *ops = (const BnGPUOp *)ops_raw;
    if (!ctx || !ops || n_ops <= 0) return -1;
    if (cuda_ctx_set_device(ctx) != 0) return -1;
    if (cuda_moe_ordered_quant_graph_reserve(ctx,ops,n_ops) != 0) return -1;
    ctx->exec_stream =
        bn_gpu_policy_cuda_stream_exec_enabled(ctx->runtime_policy)
            ? ctx->stream : (cudaStream_t)0;

    const int profile = bn_gpu_policy_cuda_profile_enabled(
        ctx->runtime_policy);
    const int profile_wall = bn_gpu_policy_cuda_wall_profile_enabled(
        ctx->runtime_policy);
    const int debug_exec_fail = bn_gpu_policy_cuda_exec_fail_debug_enabled(
        ctx->runtime_policy);
    const int debug_sync_each_op =
        bn_gpu_policy_cuda_sync_each_op_debug_enabled(ctx->runtime_policy);
    const int debug_nan = bn_gpu_policy_cuda_nan_debug_enabled(
        ctx->runtime_policy);
    unsigned long long &profile_calls = ctx->diagnostics.execute_profile_calls;
    unsigned long long (&profile_ops)[BN_CUDA_PROFILE_MAX] = ctx->diagnostics.execute_profile_ops;
    double (&profile_ms)[BN_CUDA_PROFILE_MAX] = ctx->diagnostics.execute_profile_ms;

    BnCudaShapeProfile (&shape_profile)[128] = ctx->diagnostics.execute_shape_profile;
    int &shape_profile_count = ctx->diagnostics.execute_shape_profile_count;
    unsigned long long &wall_calls = ctx->diagnostics.execute_wall_calls;
    unsigned long long &wall_ops = ctx->diagnostics.execute_wall_ops;
    unsigned long long &wall_launches = ctx->diagnostics.execute_wall_launches;
    unsigned long long (&wall_launch_by_code)[BN_CUDA_PROFILE_MAX] = ctx->diagnostics.execute_wall_launch_by_code;
    double &wall_ms = ctx->diagnostics.execute_wall_ms;
    double wall_start = profile_wall ? cuda_wall_ms() : 0.0;
    unsigned long long exec_launches = 0;
    unsigned int exec_launch_by_code[BN_CUDA_PROFILE_MAX] = {0};
    cudaEvent_t ev_start = NULL;
    cudaEvent_t ev_stop = NULL;
    if (profile) {
        cudaEventCreate(&ev_start);
        cudaEventCreate(&ev_stop);
    }

    if (bn_gpu_policy_cuda_dump_ops_enabled(ctx->runtime_policy) &&
        n_ops > 0) {
        int &dumped = ctx->diagnostics.execute_dumped;
        if (!dumped || bn_gpu_policy_cuda_dump_ops_every_enabled(
                           ctx->runtime_policy)) {
            int dump_limit =
                bn_gpu_policy_cuda_dump_ops_limit_or_default(
                    ctx->runtime_policy, 256);
            if (dump_limit <= 0 || dump_limit > n_ops) dump_limit = n_ops;
            int limit = n_ops < dump_limit ? n_ops : dump_limit;
            fprintf(stderr, "[bn:gpu:cuda:ops] n_ops=%d showing=%d\n",
                    n_ops, limit);
            for (int i = 0; i < limit; i++) {
                const BnGPUOp *op = &ops[i];
                fprintf(stderr,
                        "  %03d %-18s type=%d in=%d out=%d aux=%d "
                        "rows=%d cols=%d flags=%u p0=%u p1=%u p2=%u p3=%u "
                        "p5=%u p6=%u p7=%u\n",
                        i, cuda_op_name(op->op_code), op->type, op->buf_in,
                        op->buf_out, op->buf_aux, op->rows,
                        op->cols, op->flags, op->p[0], op->p[1], op->p[2], op->p[3],
                        op->p[5], op->p[6], op->p[7]);
            }
            dumped = 1;
        }
    }

    const int threads = 256;
    const int fuse_bias_enabled = ctx->execution_policy.fuse_bias_enabled;
    const int fuse_rope_flash_enabled = ctx->execution_policy.fuse_rope_flash_enabled;
    const int enable_legacy_block_matvec4 = ctx->execution_policy.enable_legacy_block_matvec4;
    const int enable_legacy_block_warp = ctx->execution_policy.enable_legacy_block_warp;
    const int enable_symmetric_kquant_dot = ctx->execution_policy.enable_symmetric_kquant_dot;
    const int enable_deinterleaved_kquant_dot =
        ctx->execution_policy.enable_deinterleaved_kquant_dot;
    const int enable_down_kquant_warp = ctx->execution_policy.enable_down_kquant_warp;
    const int enable_asymmetric_kquant_4warp =
        ctx->execution_policy.enable_asymmetric_kquant_4warp;
    const int disable_native_quant_warp = ctx->execution_policy.disable_native_quant_warp;
    const int disable_qkv_mixed_fuse = ctx->execution_policy.disable_qkv_mixed_fuse;
    const int qkv_fuse_key_cache = ctx->execution_policy.qkv_fuse_key_cache;
    const int enable_qkv_kpair_opt = ctx->execution_policy.enable_qkv_kpair_opt;
    const int disable_legacy_block_gateup_warp =
        ctx->execution_policy.disable_legacy_block_gateup_warp;
    const int disable_native_quant_gateup_warp =
        ctx->execution_policy.disable_native_quant_gateup_warp;
    const int enable_bias_rope_flash_fuse =
        ctx->execution_policy.enable_bias_rope_flash_fuse;
    const int enable_native_quant_prepared_input_all =
        ctx->execution_policy.enable_native_quant_prepared_input_all;
    const int disable_native_quant_prepared_input_logits =
        ctx->execution_policy.disable_native_quant_prepared_input_logits;
    const int enable_graph_exec = ctx->execution_policy.enable_graph_exec;
    int prepared_kquant_input_cache_valid = 0;
    int prepared_kquant_input_cache_buf = -1;
    int prepared_kquant_input_cache_cols = 0;
    int prepared_kquant_input_cache_tokens = 0;
    int prepared_kquant_input_cache_mark_op = -1;
    const int enable_prepared_kquant_input_cache =
        bn_gpu_policy_prepared_kquant_input_cache_enabled(
            ctx->runtime_policy);
#define BN_CUDA_PREPARED_KQUANT_INPUT_CACHE_MARK(buf_, cols_, tokens_) do { \
        prepared_kquant_input_cache_valid = enable_prepared_kquant_input_cache; \
        prepared_kquant_input_cache_buf = (buf_); \
        prepared_kquant_input_cache_cols = (cols_); \
        prepared_kquant_input_cache_tokens = (tokens_); \
        prepared_kquant_input_cache_mark_op = i; \
    } while (0)
#define BN_CUDA_PREPARED_KQUANT_INPUT_CACHE_INVALIDATE() do { \
        prepared_kquant_input_cache_valid = 0; \
        prepared_kquant_input_cache_buf = -1; \
        prepared_kquant_input_cache_cols = 0; \
        prepared_kquant_input_cache_tokens = 0; \
        prepared_kquant_input_cache_mark_op = -1; \
    } while (0)
#define BN_CUDA_PREPARED_KQUANT_INPUT_CACHE_INVALIDATE_BUF(buf_) do { \
        if (prepared_kquant_input_cache_valid && \
            prepared_kquant_input_cache_buf == (buf_)) \
            BN_CUDA_PREPARED_KQUANT_INPUT_CACHE_INVALIDATE(); \
    } while (0)
#define BN_CUDA_PREPARED_KQUANT_INPUT_CACHE_MATCH(buf_, cols_, tokens_) \
    (enable_prepared_kquant_input_cache && prepared_kquant_input_cache_valid && \
     prepared_kquant_input_cache_buf == (buf_) && \
     prepared_kquant_input_cache_cols == (cols_) && \
     prepared_kquant_input_cache_tokens == (tokens_))
    unsigned char skip_ops[8192];
    if (n_ops > (int)sizeof(skip_ops)) {
        fprintf(stderr, "[bn:gpu:cuda] execute graph too large: %d ops\n",
                n_ops);
        if (profile) {
            cudaEventDestroy(ev_start);
            cudaEventDestroy(ev_stop);
        }
        return -1;
    }
    memset(skip_ops, 0, (size_t)n_ops);
    int moe_graph = cuda_ops_have_moe(ops, n_ops);
    int native_quant_moe_graph = cuda_ops_have_native_quant_moe_routed_ffn(ops, n_ops);
    int moe_max_experts = moe_graph
        ? cuda_ops_moe_max_experts(ops, n_ops)
        : 0;
    int default_moe_graph = native_quant_moe_graph ||
        (moe_graph && moe_max_experts > 0 &&
         moe_max_experts <=
             bn_gpu_policy_cuda_moe_graph_max_experts_or_default(
                 ctx->runtime_policy, 128));
    int default_graph_exec =
        bn_gpu_policy_cuda_decode_graph_default_enabled(
            ctx->runtime_policy, moe_graph, default_moe_graph) &&
        cuda_ops_look_like_decode_graph(ops, n_ops, readback_buf,
                                        out_host, out_len);
    int native_quant_prepared_input_logits_default =
        bn_gpu_policy_cuda_native_quant_prepared_input_logits_default_enabled(
            ctx->runtime_policy,
            disable_native_quant_prepared_input_logits);
    int graph_exec = (enable_graph_exec || default_graph_exec) &&
                     n_ops > 10 && !profile;
    int graph_has_gqa = 0;
    int graph_has_gelu_gate = 0;
    for (int gi = 0; gi < n_ops; gi++) {
        graph_has_gqa |= ops[gi].op_code == BN_GPU_CODE_GQA_SCORES;
        graph_has_gelu_gate |= ops[gi].op_code == BN_GPU_CODE_GELU_GATE;
    }
    /* Blackwell runs the GELU/GQA decode graph faster than direct launches;
     * retain the conservative direct path on earlier architectures. */
    if (graph_exec && !enable_graph_exec && graph_has_gqa &&
        graph_has_gelu_gate && ctx->compute_capability < 1200)
        graph_exec = 0;
    int graph_static_params = graph_exec && cuda_ops_have_logits(ops, n_ops);
    if (graph_exec && cuda_ops_have_moe_cublas_decode(ctx, ops, n_ops))
        graph_exec = 0;
    if (graph_exec &&
        bn_gpu_policy_all_active_two_kquant_moe_fast_ffn_enabled(
            ctx->runtime_policy) &&
        bn_gpu_policy_all_active_two_kquant_moe_fast_graph_disabled(
            ctx->runtime_policy) &&
        cuda_ops_have_moe_all_active_two_kquant_routed_ffn(ops, n_ops))
        graph_exec = 0;
    graph_static_params = graph_exec && graph_static_params;
    int graph_building = 0;
    uint64_t attention_key = UINT64_C(14695981039346656037);
    for (int ai = 0; ai < n_ops; ai++) {
        if (ops[ai].op_code == BN_GPU_CODE_FLASH_ATTN ||
            ops[ai].op_code == BN_GPU_CODE_GQA_SCORES) {
            attention_key = (attention_key ^ (uint32_t)ai) * UINT64_C(1099511628211);
            attention_key = (attention_key ^ (uint32_t)ops[ai].attention_window) *
                            UINT64_C(1099511628211);
            /* FP32 128-wide flash switches from one kernel to a
             * partition-and-combine pair above 512 keys. Rebuild the graph
             * when its node layout changes. */
            if (ops[ai].op_code == BN_GPU_CODE_FLASH_ATTN &&
                !ctx->kv_f16 && (int)ops[ai].p[1] == 128)
                attention_key = (attention_key ^
                    (uint32_t)((int)ops[ai].p[2] > 512)) *
                    UINT64_C(1099511628211);
            if (ops[ai].op_code == BN_GPU_CODE_GQA_SCORES)
                attention_key = (attention_key ^
                    (uint32_t)cuda_gqa_combine_threads(
                        (int)ops[ai].p[2])) *
                    UINT64_C(1099511628211);
        }
    }
    int runtime_params_ready = 0;
    cudaGraphExec_t graph_instance = NULL;
    if (graph_exec) {
        int reserve_q8_1_cols = 0;
        int reserve_q8_k_cols = 0;
        int reserve_q8_k_batch = 1;
        for (int ri = 0; ri < n_ops; ri++) {
            const BnGPUOp *rop = &ops[ri];
            if (rop->op_code == BN_GPU_CODE_Q4K_MATVEC_SPLIT ||
                rop->op_code == BN_GPU_CODE_Q5K_MATVEC_SPLIT ||
                rop->op_code == BN_GPU_CODE_Q8_MATVEC_SPLIT) {
                int cols = (int)rop->p[1];
                if (rop->op_code == BN_GPU_CODE_Q4K_MATVEC_SPLIT &&
                    (rop->flags & BN_GPU_OP_FLAG_MATVEC_KQUANT_DOT)) {
                    if (cols > reserve_q8_k_cols) reserve_q8_k_cols = cols;
                } else {
                    if (cols > reserve_q8_1_cols) reserve_q8_1_cols = cols;
                }
            } else if (rop->op_code == BN_GPU_CODE_FUSED_GATEUP_SILU) {
                int cols = (int)rop->p[1];
                if (bn_backend_quant_gpu_graph_gateup_needs_prepared_input_scratch(
                        rop->type)) {
                    if (cols > reserve_q8_1_cols) reserve_q8_1_cols = cols;
                }
            } else if (rop->op_code == BN_GPU_CODE_MATVEC) {
                if (bn_backend_quant_gpu_graph_matvec_down_kquant_needs_dot_scratch(
                        rop->type) &&
                    (rop->cols % BN_QK_K) == 0) {
                    if (rop->cols > reserve_q8_k_cols)
                        reserve_q8_k_cols = rop->cols;
                    if (rop->cols > reserve_q8_1_cols)
                        reserve_q8_1_cols = rop->cols;
                } else if (bn_backend_quant_gpu_graph_matvec_asymmetric_kquant_needs_dot_scratch(
                               rop->type) &&
                           (rop->cols % BN_QK_K) == 0 && enable_symmetric_kquant_dot &&
                           ((rop->flags & BN_GPU_OP_FLAG_MATVEC_KQUANT_DOT) ||
                            bn_gpu_policy_kquant_dot_forced(ctx->runtime_policy)) &&
                           bn_gpu_policy_kquant_dot_enabled(ctx->runtime_policy)) {
                    if (rop->cols > reserve_q8_k_cols)
                        reserve_q8_k_cols = rop->cols;
                } else if (bn_backend_quant_gpu_graph_matvec_needs_prepared_input_scratch(
                               rop->type) &&
                           (rop->cols % BN_QK_K) == 0) {
                    if (rop->cols > reserve_q8_1_cols)
                        reserve_q8_1_cols = rop->cols;
                }
            } else if (rop->op_code == BN_GPU_CODE_MOE_ROUTED_FFN) {
                int hidden = (int)rop->p[0];
                int k = (int)rop->p[2];
                int down_type = (int)rop->p[3];
                if (hidden > 0 && k > 0) {
                    int mid_elems = hidden * k;
                    if (bn_backend_quant_moe_routed_op_uses_native_quant(rop->type)) {
                        int elems = mid_elems > rop->cols ? mid_elems : rop->cols;
                        if (elems > reserve_q8_1_cols)
                            reserve_q8_1_cols = elems;
                    } else if (bn_backend_quant_moe_routed_op_uses_asymmetric_kquant(
                                   rop->type)) {
                        if (rop->cols > reserve_q8_1_cols)
                            reserve_q8_1_cols = rop->cols;
                        if (bn_backend_quant_moe_down_uses_graph_kquant(
                                down_type)) {
                            if (hidden > reserve_q8_k_cols)
                                reserve_q8_k_cols = hidden;
                            if (k > reserve_q8_k_batch)
                                reserve_q8_k_batch = k;
                        }
                    }
                }
            }
        }
        if (reserve_q8_1_cols > 0 &&
            cuda_ensure_q8_1(ctx, reserve_q8_1_cols) != 0)
            return -1;
        if (reserve_q8_k_cols > 0 &&
            cuda_ensure_q8_k(ctx, reserve_q8_k_cols,
                             reserve_q8_k_batch) != 0)
            return -1;
    }
    if (graph_exec) {
        if (ctx->exec_graph && (ctx->exec_graph_ops != n_ops ||
            ctx->exec_graph_static_params != graph_static_params ||
            ctx->exec_graph_attention_key != attention_key)) {
            cuda_invalidate_exec_graph(ctx);
        }
        if (!ctx->exec_graph) {
            cudaError_t graph_err = cudaGraphCreate(&ctx->exec_graph_def, 0);
            if (graph_err != cudaSuccess) {
                fprintf(stderr,
                        "[bn:gpu:cuda] graph create failed: %s\n",
                        cudaGetErrorString(graph_err));
                graph_exec = 0;
            } else {
                graph_building = 1;
                ctx->exec_node_count = 0;
                ctx->exec_node_cursor = 0;
            }
        } else {
            ctx->exec_node_cursor = 0;
        }
        if (ctx->exec_stream == (cudaStream_t)0) {
            fprintf(stderr,
                    "[bn:gpu:cuda] graph execution requires stream mode\n");
            graph_exec = 0;
        }
        if (graph_exec) {
            if (!ctx->d_runtime) {
                cudaError_t alloc_err =
                    cudaMalloc(&ctx->d_runtime,
                               sizeof(BnCudaRuntimeParams));
                if (alloc_err != cudaSuccess) {
                    fprintf(stderr,
                            "[bn:gpu:cuda] runtime params alloc failed: %s\n",
                            cudaGetErrorString(alloc_err));
                    return -1;
                }
            }
            BnCudaRuntimeParams rt;
            memset(&rt, 0, sizeof(rt));
            rt.pos = -1;
            rt.n_kv = -1;
            rt.seq_len = -1;
            for (int ri = 0; ri < n_ops; ri++) {
                if (rt.pos < 0 &&
                    (ops[ri].op_code == BN_GPU_CODE_ROPE ||
                     ops[ri].op_code == BN_GPU_CODE_ROPE_QK)) {
                    rt.pos = (int)ops[ri].p[2];
                }
                if (rt.n_kv < 0 &&
                    (ops[ri].op_code == BN_GPU_CODE_FLASH_ATTN ||
                     ops[ri].op_code == BN_GPU_CODE_GQA_SCORES)) {
                    rt.n_kv = (int)ops[ri].p[2];
                    rt.seq_len = (int)ops[ri].p[5];
                }
                if (rt.pos >= 0 && rt.n_kv >= 0 && rt.seq_len > 0)
                    break;
            }
            if (rt.pos < 0 || rt.n_kv <= 0 || rt.seq_len <= 0) {
                graph_exec = 0;
            } else {
                rt.cache_pos = rt.pos % rt.seq_len;
                cudaError_t copy_err =
                    cudaMemcpyAsync(ctx->d_runtime, &rt, sizeof(rt),
                                    cudaMemcpyHostToDevice,
                                    ctx->exec_stream);
                if (copy_err != cudaSuccess) {
                    fprintf(stderr,
                            "[bn:gpu:cuda] runtime params copy failed: %s\n",
                            cudaGetErrorString(copy_err));
                    return -1;
                }
            }
        }
        runtime_params_ready = graph_exec;
    }
    if (!graph_exec && !profile &&
        bn_gpu_policy_cuda_qk_norm_rope_flash_fuse_enabled(
            ctx->runtime_policy)) {
        int wants_qk_norm_flash_runtime = 0;
        for (int ri = 0; ri + 3 < n_ops; ri++) {
            const BnGPUOp *qnorm = &ops[ri];
            const BnGPUOp *knorm = &ops[ri + 1];
            const BnGPUOp *rope = &ops[ri + 2];
            const BnGPUOp *flash = &ops[ri + 3];
            if (qnorm->op_code == BN_GPU_CODE_PER_HEAD_RMSNORM &&
                qnorm->buf_in == BN_GPU_VALUE_Q &&
                knorm->op_code == BN_GPU_CODE_PER_HEAD_RMSNORM &&
                knorm->buf_in == BN_GPU_VALUE_KEY_CACHE &&
                rope->op_code == BN_GPU_CODE_ROPE_QK &&
                rope->buf_in == BN_GPU_VALUE_Q &&
                rope->buf_aux == BN_GPU_VALUE_KEY_CACHE &&
                flash->op_code == BN_GPU_CODE_FLASH_ATTN &&
                flash->buf_in == BN_GPU_VALUE_Q) {
                wants_qk_norm_flash_runtime = 1;
                break;
            }
        }
        if (wants_qk_norm_flash_runtime) {
            if (!ctx->d_runtime) {
                cudaError_t alloc_err =
                    cudaMalloc(&ctx->d_runtime,
                               sizeof(BnCudaRuntimeParams));
                if (alloc_err != cudaSuccess) {
                    fprintf(stderr,
                            "[bn:gpu:cuda] runtime params alloc failed: %s\n",
                            cudaGetErrorString(alloc_err));
                    return -1;
                }
            }
            BnCudaRuntimeParams rt;
            memset(&rt, 0, sizeof(rt));
            rt.pos = -1;
            rt.n_kv = -1;
            rt.seq_len = -1;
            for (int ri = 0; ri < n_ops; ri++) {
                if (rt.pos < 0 &&
                    (ops[ri].op_code == BN_GPU_CODE_ROPE ||
                     ops[ri].op_code == BN_GPU_CODE_ROPE_QK)) {
                    rt.pos = (int)ops[ri].p[2];
                }
                if (rt.n_kv < 0 &&
                    ops[ri].op_code == BN_GPU_CODE_FLASH_ATTN) {
                    rt.n_kv = (int)ops[ri].p[2];
                    rt.seq_len = (int)ops[ri].p[5];
                }
                if (rt.pos >= 0 && rt.n_kv >= 0 && rt.seq_len > 0)
                    break;
            }
            if (rt.pos >= 0 && rt.n_kv > 0 && rt.seq_len > 0) {
                rt.cache_pos = rt.pos % rt.seq_len;
                cudaError_t copy_err =
                    cudaMemcpyAsync(ctx->d_runtime, &rt, sizeof(rt),
                                    cudaMemcpyHostToDevice,
                                    ctx->exec_stream);
                if (copy_err != cudaSuccess) {
                    fprintf(stderr,
                            "[bn:gpu:cuda] runtime params copy failed: %s\n",
                            cudaGetErrorString(copy_err));
                    return -1;
                }
                runtime_params_ready = 1;
            }
        }
    }
    for (int i = 0; i < n_ops; i++) {
        if (skip_ops[i])
            continue;
        const BnGPUOp *op = &ops[i];
        const BnGPUOp *next = (i + 1 < n_ops) ? &ops[i + 1] : NULL;
#define BN_CUDA_EXEC_FAIL(reason) do { \
            if (debug_exec_fail) { \
                fprintf(stderr, \
                        "[bn:gpu:cuda:exec-fail] op=%d/%d code=%s(%d) " \
                        "reason=%s in=%d out=%d aux=%d rows=%d cols=%d " \
                        "p0=%u p1=%u p2=%u p3=%u p5=%u p6=%u p7=%u\n", \
                        i, n_ops, cuda_op_name(op->op_code), op->op_code, \
                        (reason), op->buf_in, op->buf_out, op->buf_aux, \
                        op->rows, op->cols, op->p[0], op->p[1], op->p[2], \
                        op->p[3], op->p[5], op->p[6], op->p[7]); \
            } \
            return -1; \
        } while (0)
        cudaError_t err = cudaSuccess;
        int is_logits_op = op->op_kind == BN_GPU_OP_LOGITS ||
                           (op->op_code == BN_GPU_CODE_MATVEC &&
                            op->buf_out == BN_GPU_VALUE_LOGITS);
        int profile_code = is_logits_op
            ? BN_CUDA_PROFILE_LOGITS
            : op->op_code;
        if (profile)
        cudaEventRecord(ev_start, ctx->exec_stream);
        switch (op->op_code) {
        case BN_GPU_CODE_MATVEC: {
            BnCudaBuffer *w = (BnCudaBuffer *)op->W_buf;
            float *in = cuda_act(ctx, op->buf_in);
            float *out = cuda_act(ctx, op->buf_out);
            const float *bias = NULL;
            int bias_idx = -1;
            int fused_copy_idx = -1;
            size_t out_offset = (size_t)op->p[5];
            if (!w || !w->data || !in || !out ||
                !cuda_type_supported(ctx, op->type) ||
                op->rows <= 0 || op->cols <= 0) {
                if (debug_exec_fail) {
                    fprintf(stderr,
                            "[bn:gpu:cuda:matvec-invalid] w=%p wdata=%p "
                            "in=%p out=%p type=%d supported=%d\n",
                            (void *)w, w ? w->data : NULL, (void *)in,
                            (void *)out, op->type,
                            cuda_type_supported(ctx, op->type));
                }
                BN_CUDA_EXEC_FAIL("matvec invalid args");
            }
            if (next && i + 2 < n_ops &&
                next->op_code == BN_GPU_CODE_BIAS_ADD &&
                next->buf_in == op->buf_out &&
                (int)next->p[0] == op->rows) {
                const BnGPUOp *copy = &ops[i + 2];
                if (copy->op_code == BN_GPU_CODE_COPY &&
                    copy->buf_in == op->buf_out &&
                    (int)copy->p[0] == (int)op->p[5] &&
                    (int)copy->p[2] == op->rows) {
                    BnCudaBuffer *bw = (BnCudaBuffer *)next->W_buf;
                    float *copy_out = cuda_act(ctx, copy->buf_out);
                    int copy_to_kv_f16 = ctx->kv_f16 &&
                        (copy->buf_out == BN_GPU_VALUE_KEY_CACHE ||
                         copy->buf_out == BN_GPU_VALUE_VALUE_CACHE);
                    if (bw && bw->data && copy_out && !copy_to_kv_f16) {
                        bias = (const float *)bw->data;
                        out = copy_out;
                        out_offset = (size_t)copy->p[1];
                        fused_copy_idx = i + 2;
                    }
                }
            }
            bias_idx = (fused_copy_idx < 0 && fuse_bias_enabled &&
                        bn_backend_quant_matvec_allows_fused_bias(
                            op->type))
                ? cuda_find_fusable_bias(ops, n_ops, i, op->buf_out,
                                          op->rows)
                : -1;
            if (bias_idx >= 0) {
                BnCudaBuffer *bw = (BnCudaBuffer *)ops[bias_idx].W_buf;
                if (bw && bw->data &&
                    !cuda_bias_followed_by_copy(ops, n_ops, bias_idx)) {
                    bias = (const float *)bw->data;
                } else {
                    bias_idx = -1;
                }
            }
            int direct_kv_f16 = ctx->kv_f16 &&
                (op->buf_out == BN_GPU_VALUE_KEY_CACHE ||
                 op->buf_out == BN_GPU_VALUE_VALUE_CACHE) &&
                fused_copy_idx < 0 && bias == NULL && bias_idx < 0;
            void *direct_kv_dst = out;
            size_t direct_kv_offset = out_offset;
            if (direct_kv_f16) {
                float *tmp = cuda_act(ctx, BN_GPU_VALUE_SCRATCH);
                if (!tmp || op->rows > (int)(ctx->act_sizes[BN_GPU_VALUE_SCRATCH] /
                                             sizeof(float)))
                    BN_CUDA_EXEC_FAIL("direct kv f16 scratch unavailable");
                out = tmp;
                out_offset = 0;
            }
            int stable_decode_matvec =
                graph_exec && out_offset == 0 && !direct_kv_f16 &&
                fused_copy_idx < 0;
            int reference_kquant_matvec =
                (op->flags &
                 BN_GPU_OP_FLAG_MATVEC_REFERENCE_KQUANT) != 0;
            int reference_block_accumulation =
                (op->flags &
                 BN_GPU_OP_FLAG_REFERENCE_BLOCK_ACCUMULATION) != 0;
            /* Native MMVQ is faster for the 2048-column Q4_K/Q6_K decode
             * projections while preserving the tested greedy token stream. */
            if (op->cols == 2048 &&
                (bn_quant_format_is_q4k(op->type) ||
                 bn_quant_format_is_q6k(op->type))) {
                reference_kquant_matvec = 0;
                reference_block_accumulation = 0;
            }
            /* The 2048x4096 Q4_K attention output projection retains its
