                } else {
                    int blocks = (n_experts + warps - 1) / warps;
                    BN_CUDA_LAUNCH(ctx, moe_router_logits_warp_kernel, blocks,
                        threads, 0, logits, (const float *)w->data, in,
                        n_experts, dim);
                }
                if (reference_route) {
                    BN_CUDA_LAUNCH_STABLE(ctx, graph_exec,
                        moe_route_topk_avx2_reference_kernel, 1, 1, 0,
                        route, logits, n_experts, k,
                        (op->flags & BN_GPU_OP_FLAG_MOE_ROUTE_NO_NORM) == 0,
                        expert_weights_scale);
                } else if (bn_gpu_policy_cuda_moe_router_warp_topk_enabled(
                        ctx->runtime_policy, n_experts)) {
                    int separate_topk =
                        (op->flags &
                         BN_GPU_OP_FLAG_MOE_ROUTE_SEPARATE_TOPK) != 0;
                    if (n_experts == 128 && !separate_topk) {
                        BN_CUDA_LAUNCH_STABLE(ctx, graph_exec,
                            moe_route_topk_128_kernel, 1, 128, 0, route,
                            logits, k,
                            (op->flags &
                             BN_GPU_OP_FLAG_MOE_ROUTE_NO_NORM) == 0,
                            expert_weights_scale);
                    } else {
                        BN_CUDA_LAUNCH_STABLE(ctx, graph_exec,
                            moe_route_topk_warp_kernel, 1, 32, 0, route,
                            logits, n_experts, k,
                            (op->flags &
                             BN_GPU_OP_FLAG_MOE_ROUTE_NO_NORM) == 0,
                            expert_weights_scale, separate_topk);
                    }
                } else {
                    BN_CUDA_LAUNCH_STABLE(ctx, graph_exec,
                        moe_route_topk_kernel, 1, 1, 0, route, logits,
                        n_experts, k,
                        (op->flags & BN_GPU_OP_FLAG_MOE_ROUTE_NO_NORM) == 0,
                        expert_weights_scale);
                }
            }
            if (expert_down_scale && expert_down_scale->data &&
                expert_down_scale->rows * expert_down_scale->cols >=
                    n_experts) {
                BN_CUDA_LAUNCH_STABLE(ctx, graph_exec,
                    moe_route_apply_expert_down_scale_kernel,
                    (k + 31) / 32, 32, 0, route,
                    (const float *)expert_down_scale->data,
                    n_experts, k,
                    (op->flags &
                     BN_GPU_OP_FLAG_MOE_SEPARATE_OUTPUT_SCALE) != 0);
            }
            break;
        }
        case BN_GPU_CODE_MOE_ROUTED_FFN: {
            BnCudaBuffer *gate = (BnCudaBuffer *)op->W_buf;
            BnCudaBuffer *up = (BnCudaBuffer *)op->W_buf2;
            BnCudaBuffer *down = (BnCudaBuffer *)op->W_buf3;
            float *in = cuda_act(ctx, op->buf_in);
            float *route = cuda_act(ctx, op->buf_aux);
            int mid_buf = (int)op->p[4];
            float *mid = cuda_act(ctx, mid_buf);
            float *out = cuda_act(ctx, op->buf_out);
            int hidden = (int)op->p[0];
            int n_experts = (int)op->p[1];
            int k = (int)op->p[2];
            int down_type = (int)op->p[3];
            int moe_layer = (int)op->p[5];
            int dim = op->cols;
            int separate_output_scale =
                (op->flags &
                 BN_GPU_OP_FLAG_MOE_SEPARATE_OUTPUT_SCALE) != 0;
            if (cuda_moe_ordered_quant_graph_op(ctx,op)) {
                if (cuda_moe_ordered_quant_graph_run(ctx,op,graph_exec,graph_building) != 0)
                    BN_CUDA_EXEC_FAIL("ordered routed quant graph execution failed");
                break;
            }
            int routed_asymmetric_kquant =
                gate && up && down && gate->type == op->type &&
                down->type == down_type &&
                bn_backend_quant_moe_routed_asymmetric_kquant(op->type,
                                                              up->type,
                                                              down_type);
            int routed_native_quant =
                gate && up && down && gate->type == op->type &&
                down->type == down_type &&
                bn_backend_quant_moe_routed_native_quant(op->type, up->type,
                                               down_type);
            int routed_midbit_down =
                gate && up && down && gate->type == op->type &&
                down->type == down_type &&
                bn_backend_quant_moe_routed_kquant_gateup(op->type,
                                                          up->type) &&
                bn_backend_quant_moe_routed_midbit_block32_down(down_type);
            int routed_direct_down =
                gate && up && down && gate->type == op->type &&
                down->type == down_type &&
                bn_backend_quant_moe_routed_kquant_gateup(op->type,
                                                          up->type) &&
                bn_backend_quant_moe_direct_routed_down(down_type);
            int routed_midbit_gateup =
                gate && up && down && gate->type == op->type &&
                down->type == down_type &&
                bn_backend_quant_moe_routed_midbit_kquant_gateup(
                    op->type, up->type) &&
                bn_backend_quant_moe_direct_routed_down(down_type);
            if (!gate || !gate->data || !up || !up->data ||
                !down || !down->data || !in || !route || !mid || !out ||
                (!routed_asymmetric_kquant && !routed_native_quant &&
                 !routed_midbit_down && !routed_direct_down &&
                 !routed_midbit_gateup) ||
                dim <= 0 || hidden <= 0 || n_experts <= 0 || k <= 0 ||
                (dim % 32) != 0 || (hidden % 32) != 0 ||
                gate->rows < hidden * n_experts || gate->cols < dim ||
                up->rows < hidden * n_experts || up->cols < dim ||
                down->rows < dim * n_experts || down->cols < hidden ||
                ctx->act_sizes[op->buf_aux] <
                    (size_t)((separate_output_scale ? 3 : 2) * k) *
                        sizeof(float) ||
                ctx->act_sizes[mid_buf] <
                    (size_t)k * (size_t)hidden * sizeof(float) ||
                ctx->act_sizes[op->buf_out] < (size_t)dim * sizeof(float)) {
                if (debug_exec_fail) {
                    fprintf(stderr,
                            "[bn:gpu:cuda:exec-fail] routed moe detail "
                            "routes=%d/%d/%d/%d/%d gate=%dx%d up=%dx%d "
                            "down=%dx%d route_bytes=%zu mid_bytes=%zu "
                            "out_bytes=%zu\n",
                            routed_asymmetric_kquant, routed_native_quant,
                            routed_midbit_down, routed_direct_down,
                            routed_midbit_gateup,
                            gate ? gate->rows : 0, gate ? gate->cols : 0,
                            up ? up->rows : 0, up ? up->cols : 0,
                            down ? down->rows : 0, down ? down->cols : 0,
                            ctx->act_sizes[op->buf_aux],
                            ctx->act_sizes[mid_buf],
                            ctx->act_sizes[op->buf_out]);
                }
                BN_CUDA_EXEC_FAIL("routed moe invalid args");
            }
            {
                int route_threads = 256;
                int warps = route_threads / 32;
                int gateup_tasks = hidden * k;
                int gateup_blocks = (gateup_tasks + warps - 1) / warps;
                int down_blocks = (dim + warps - 1) / warps;
                if (routed_native_quant) {
                    if (bn_gpu_policy_cuda_moe_block_prepared_decode_enabled(ctx->runtime_policy)) {
                        int q8_scratch_elems =
                            dim > hidden * k ? dim : hidden * k;
                        if (cuda_ensure_q8_1(ctx, q8_scratch_elems) != 0)
                            BN_CUDA_EXEC_FAIL(
                                "routed moe q8_1 scratch alloc failed");
                        BnCudaBlockQ8_1 *xq =
                            (BnCudaBlockQ8_1 *)ctx->d_q8_1;
                        BN_CUDA_LAUNCH_STABLE(ctx, graph_exec, quantize_q8_1_kernel,
                            (dim + 31) / 32, 32, 0, xq, in, dim);
                        BN_CUDA_LAUNCH_STABLE(ctx, graph_exec,
                            moe_q8_0_gateup_routed_mid_q8_1_kernel,
                            gateup_blocks, route_threads, 0,
                            mid, (const BnBlockQ8_0 *)gate->data,
                            (const BnBlockQ8_0 *)up->data, xq, route,
                            hidden, dim, n_experts, k);
                        BnCudaBlockQ8_1 *mid_q =
                            (BnCudaBlockQ8_1 *)ctx->d_q8_1;
                        BN_CUDA_LAUNCH_STABLE(ctx, graph_exec, quantize_q8_1_batch_kernel,
                            dim3(hidden / 32, k, 1), 32, 0, mid_q, mid,
                            hidden, k);
                        BN_CUDA_LAUNCH_STABLE(ctx, graph_exec,
                            moe_q8_0_down_routed_q8_1_accum_kernel,
                            down_blocks, route_threads, 0,
                            out, (const BnBlockQ8_0 *)down->data, mid_q,
                            route, dim, hidden, n_experts, k,
                            (op->flags &
                             BN_GPU_OP_FLAG_MOE_SEPARATE_REDUCTION) != 0,
                            separate_output_scale);
                    } else {
                        BN_CUDA_LAUNCH_STABLE(ctx, graph_exec,
                            moe_q8_0_gateup_routed_mid_kernel, gateup_blocks,
                            route_threads, 0,
                            mid, (const BnBlockQ8_0 *)gate->data,
                            (const BnBlockQ8_0 *)up->data, in, route,
                            hidden, dim, n_experts, k);
                        BN_CUDA_LAUNCH_STABLE(ctx, graph_exec,
                            moe_q8_0_down_routed_accum_kernel, down_blocks,
                            route_threads, 0,
                            out, (const BnBlockQ8_0 *)down->data, mid,
                            route, dim, hidden, n_experts, k,
                            separate_output_scale);
                    }
                } else {
                    /* Q8_1 is faster for small routed inputs; large hidden
                       alone does not amortize Q8_K quantization overhead. */
                    int moe_all_active_two_kquant =
                        bn_backend_quant_moe_all_active_two_kquant_shape(
                            n_experts, k, down_type, hidden, dim);
                    int moe_all_active_two_graph_kquant =
                        bn_backend_quant_moe_all_active_two_graph_kquant_shape(
                            n_experts, k, down_type, hidden, dim);
                    int moe_all_active_two_fast_moe_ffn =
                        bn_gpu_policy_all_active_two_kquant_moe_fast_ffn_enabled(
                            ctx->runtime_policy);
                    int moe_all_active_two_fast_enabled =
                        bn_gpu_policy_cuda_moe_all_active_two_fast_enabled(
                            ctx->runtime_policy,
                            moe_all_active_two_graph_kquant);
                    int uses_reference_silu =
                        (op->flags & BN_GPU_OP_FLAG_REFERENCE_SILU) != 0;
                    int reference_ffn =
                        (op->flags &
                         BN_GPU_OP_FLAG_REFERENCE_BLOCK_ACCUMULATION) != 0;
                    int use_cublas_all_active_two_decode =
                        moe_all_active_two_kquant &&
                        gate->f16_data && up->f16_data && down->f16_data &&
                        bn_gpu_policy_all_active_two_kquant_moe_cublas_decode_enabled(
                            ctx->runtime_policy) &&
                        bn_gpu_policy_cuda_moe_cublas_decode_enabled(
                            ctx->runtime_policy);
                    if (use_cublas_all_active_two_decode) {
                        if (cuda_moe_cublas_all_active_two_decode(
                                ctx, out, gate, up, down, in, route, dim,
                                hidden, uses_reference_silu) == 0) {
                            break;
                        }
                        if (bn_gpu_policy_cuda_moe_cublas_decode_debug_enabled(
                                ctx->runtime_policy)) {
                            fprintf(stderr,
                                    "[bn:gpu:cuda] all-active-two cublas moe decode "
                                    "failed; falling back\n");
                        }
                    }
                    const BnGPUOp *prev = (i > 0) ? &ops[i - 1] : NULL;
                    int moe_all_active_two_route_block_prepared_input_enabled =
                        bn_gpu_policy_cuda_moe_route_block_prepared_input_enabled(
                            ctx->runtime_policy, dim,
                            moe_all_active_two_kquant,
                            uses_reference_silu);
                    int moe_all_active_two_route_dot_prepared_input_default_enabled =
                        bn_gpu_policy_cuda_moe_route_dot_prepared_input_enabled(
                            ctx->runtime_policy, dim,
                            moe_all_active_two_kquant);
                    int moe_all_active_two_x_dot_prepared =
                        moe_all_active_two_kquant &&
                        prev &&
                        prev->op_code == BN_GPU_CODE_MOE_ROUTE_TOPK &&
                        prev->cols == dim &&
                        prev->W_buf &&
                        (((BnCudaBuffer *)prev->W_buf)->rows == 1 ||
                         (((BnCudaBuffer *)prev->W_buf)->rows >= 2 &&
                          (dim % 16) == 0 &&
                          !bn_gpu_policy_all_active_two_kquant_moe_reference_gpu_route_disabled(
                              ctx->runtime_policy))) &&
                        !moe_all_active_two_route_block_prepared_input_enabled &&
                        moe_all_active_two_route_dot_prepared_input_default_enabled;
                    int moe_all_active_two_x_block_prepared =
                        moe_all_active_two_kquant &&
                        prev &&
                        prev->op_code == BN_GPU_CODE_MOE_ROUTE_TOPK &&
                        prev->cols == dim &&
                        prev->W_buf &&
                        ((BnCudaBuffer *)prev->W_buf)->rows == 1 &&
                        moe_all_active_two_route_block_prepared_input_enabled;
                    int use_moe_all_active_two_dot_prepared_default =
                        moe_all_active_two_kquant &&
                        !bn_gpu_policy_all_active_two_kquant_moe_dot_prepared_input_default_disabled(
                            ctx->runtime_policy);
                    int moe_all_active_two_fast_prepared_gateup =
                        moe_all_active_two_graph_kquant &&
                        bn_gpu_policy_all_active_two_kquant_fast_prepared_gateup_enabled(
                            ctx->runtime_policy) &&
                        !bn_gpu_policy_all_active_two_kquant_fast_prepared_gateup_disabled(
                            ctx->runtime_policy);
                    int use_moe_prepared_dot =
                        !routed_midbit_gateup &&
                        bn_gpu_policy_cuda_moe_prepared_dot_enabled(
                            ctx->runtime_policy,
                            use_moe_all_active_two_dot_prepared_default,
                            moe_all_active_two_fast_prepared_gateup,
                            moe_all_active_two_kquant, hidden, dim);
                    int profile_moe_internal =
                        bn_gpu_policy_cuda_moe_internal_profile_enabled(
                            ctx->runtime_policy, profile);
                    cudaEvent_t moe_ev_start = NULL;
                    cudaEvent_t moe_ev_stop = NULL;
                    if (profile_moe_internal) {
                        cudaEventCreate(&moe_ev_start);
                        cudaEventCreate(&moe_ev_stop);
                        cudaEventRecord(moe_ev_start, ctx->exec_stream);
                    }
                    if (reference_ffn &&
                        ((op->type == BN_GGUF_TENSOR_Q4_K &&
                          up->type == BN_GGUF_TENSOR_Q4_K) ||
                         (op->type == BN_GGUF_TENSOR_Q5_K &&
                          up->type == BN_GGUF_TENSOR_Q5_K))) {
                        if (cuda_ensure_q8_k(ctx, dim, 1) != 0)
                            BN_CUDA_EXEC_FAIL(
                                "reference routed moe q8_k scratch alloc failed");
                        BnBlockQ8K *xq = (BnBlockQ8K *)ctx->d_q8_k;
                        BN_CUDA_LAUNCH_STABLE(ctx, graph_exec,
                            quantize_q8k_batch_kernel,
                            dim3(dim / BN_QK_K, 1, 1), BN_QK_K, 0,
                            xq, in, dim, 1);
                        int reference_threads = 256;
                        int reference_blocks =
                            (gateup_tasks + reference_threads - 1) /
                            reference_threads;
                        if (op->type == BN_GGUF_TENSOR_Q4_K) {
                            BN_CUDA_LAUNCH_STABLE(ctx, graph_exec,
                                moe_q4k_gateup_routed_mid_q8k_reference_kernel,
                                reference_blocks, reference_threads, 0,
                                mid, (const BnBlockQ4K *)gate->data,
                                (const BnBlockQ4K *)up->data, xq, route,
                                hidden, dim, n_experts, k,
                                uses_reference_silu);
                        } else {
                            BN_CUDA_LAUNCH_STABLE(ctx, graph_exec,
                                moe_q5k_gateup_routed_mid_q8k_reference_kernel,
                                reference_blocks, reference_threads, 0,
                                mid, (const BnBlockQ5K *)gate->data,
                                (const BnBlockQ5K *)up->data, xq, route,
                                hidden, dim, n_experts, k,
                                uses_reference_silu);
                        }
                    } else if (use_moe_prepared_dot) {
                        if (cuda_ensure_q8_k(ctx, dim, 1) != 0)
                            BN_CUDA_EXEC_FAIL(
                                "routed moe input q8_k scratch alloc failed");
                        BnBlockQ8K *xq = (BnBlockQ8K *)ctx->d_q8_k;
                        if (!moe_all_active_two_x_dot_prepared) {
                            BN_CUDA_LAUNCH_STABLE(ctx, graph_exec, quantize_q8k_batch_kernel,
                                dim3(dim / BN_QK_K, 1, 1), BN_QK_K, 0,
                                xq, in, dim, 1);
                            BN_CUDA_PREPARED_KQUANT_INPUT_CACHE_MARK(
                                op->buf_in, dim, 1);
                        }
                        if (bn_gpu_policy_cuda_moe_all_active_two_fixed_prepared_4row_enabled(
                                ctx->runtime_policy,
                                moe_all_active_two_x_dot_prepared,
                                moe_all_active_two_fast_enabled)) {
                            int gateup4_tasks = (gateup_tasks + 3) / 4;
                            int gateup4_blocks =
                                (gateup4_tasks + warps - 1) / warps;
                            BN_CUDA_LAUNCH_STABLE(ctx, graph_exec,
                                moe_q4k_gateup_all_active_two_mid_q8k_4row_kernel,
                                gateup4_blocks, route_threads, 0,
                                mid, (const BnBlockQ4K *)gate->data,
                                (const BnBlockQ4K *)up->data, xq, route,
                                hidden, dim, uses_reference_silu);
                        } else if (bn_gpu_policy_cuda_moe_gateup_prepared_4row_disabled(
                                       ctx->runtime_policy)) {
                            BN_CUDA_LAUNCH_STABLE(ctx, graph_exec,
                                moe_q4k_gateup_routed_mid_q8k_kernel,
                                gateup_blocks, route_threads, 0,
                                mid, (const BnBlockQ4K *)gate->data,
                                (const BnBlockQ4K *)up->data, xq, route, hidden,
                                dim, n_experts, k, uses_reference_silu);
                        } else {
                            int gateup4_tasks = (gateup_tasks + 3) / 4;
                            int gateup4_blocks =
                                (gateup4_tasks + warps - 1) / warps;
                            BN_CUDA_LAUNCH_STABLE(ctx, graph_exec,
                                moe_q4k_gateup_routed_mid_q8k_4row_kernel,
                                gateup4_blocks, route_threads, 0,
                                mid, (const BnBlockQ4K *)gate->data,
                                (const BnBlockQ4K *)up->data, xq, route, hidden,
                                dim, n_experts, k, uses_reference_silu);
                        }
                    } else {
                        int q8_1_elems = routed_midbit_gateup &&
                                bn_backend_quant_uses_native_quant(down_type) &&
                                hidden * k > dim
                            ? hidden * k : dim;
                        if (cuda_ensure_q8_1(ctx, q8_1_elems) != 0)
                            BN_CUDA_EXEC_FAIL(
                                "routed moe input q8_1 scratch alloc failed");
                        BnCudaBlockQ8_1 *xq =
                            (BnCudaBlockQ8_1 *)ctx->d_q8_1;
                        if (!moe_all_active_two_x_block_prepared) {
                            BN_CUDA_LAUNCH_STABLE(ctx, graph_exec,
                                quantize_q8_1_kernel, (dim + 31) / 32, 32,
                                0, xq, in, dim);
                        }
                        if (bn_gpu_policy_moe_route_all_active_two(n_experts,
                                                                   k) &&
                            moe_all_active_two_fast_enabled) {
                            BN_CUDA_LAUNCH_STABLE(ctx, graph_exec,
                                moe_q4k_gateup_all_active_two_mid_kernel,
                                gateup_blocks, route_threads, 0,
                                mid, (const BnBlockQ4K *)gate->data,
                                (const BnBlockQ4K *)up->data, xq, route,
                                hidden, dim);
                        } else {
                            if (routed_midbit_gateup) {
                                if (bn_backend_quant_uses_native_quant(
                                        down_type) &&
                                    (op->flags &
                                        BN_GPU_OP_FLAG_MOE_Q8_FLOAT_DOWN) == 0) {
                                    BN_CUDA_LAUNCH_STABLE(ctx, graph_exec,
                                        moe_q5k_gateup_routed_mid_4warp_kernel,
                                        hidden * k, 128, 0,
                                        mid, (const BnBlockQ5K *)gate->data,
                                        (const BnBlockQ5K *)up->data, xq,
                                        route, hidden, dim, n_experts, k);
                                } else {
                                    BN_CUDA_LAUNCH_STABLE(ctx, graph_exec,
                                        moe_q5k_gateup_routed_mid_kernel,
                                        gateup_blocks, route_threads, 0,
                                        mid, (const BnBlockQ5K *)gate->data,
                                        (const BnBlockQ5K *)up->data, xq,
                                        route, hidden, dim, n_experts, k);
                                }
                            } else {
                                if (op->flags &
                                    BN_GPU_OP_FLAG_MOE_SEPARATE_REDUCTION) {
                                    BN_CUDA_LAUNCH_STABLE(ctx, graph_exec,
                                        moe_q4k_gateup_routed_mid_4warp_kernel,
                                        hidden * k, 128, 0,
                                        mid, (const BnBlockQ4K *)gate->data,
                                        (const BnBlockQ4K *)up->data, xq,
                                        route, hidden, dim, n_experts, k);
                                } else {
                                    BN_CUDA_LAUNCH_STABLE(ctx, graph_exec,
                                        moe_q4k_gateup_routed_mid_kernel,
                                        gateup_blocks, route_threads, 0,
                                        mid, (const BnBlockQ4K *)gate->data,
                                        (const BnBlockQ4K *)up->data, xq,
                                        route, hidden, dim, n_experts, k);
                                }
                            }
                        }
                    }
                    if (profile_moe_internal) {
                        cudaEventRecord(moe_ev_stop, ctx->exec_stream);
                        cudaEventSynchronize(moe_ev_stop);
                        float ms = 0.0f;
                        cudaEventElapsedTime(&ms, moe_ev_start, moe_ev_stop);
                        profile_ops[BN_CUDA_PROFILE_MOE_GATEUP]++;
                        profile_ms[BN_CUDA_PROFILE_MOE_GATEUP] += (double)ms;
                        cudaEventRecord(moe_ev_start, ctx->exec_stream);
                    }
                    if (routed_midbit_down) {
                        if (reference_ffn) {
                            if (cuda_ensure_q8_1(ctx, hidden * k) != 0)
                                BN_CUDA_EXEC_FAIL(
                                    "reference routed moe q5_1 scratch alloc failed");
                            BnCudaBlockQ8_1 *mid_q =
                                (BnCudaBlockQ8_1 *)ctx->d_q8_1;
                            BN_CUDA_LAUNCH_STABLE(ctx, graph_exec,
                                quantize_q5_1_input_avx2_reference_batch_kernel,
                                dim3(hidden / 32, k, 1), 32, 0,
                                mid_q, mid, hidden, k);
                            BN_CUDA_LAUNCH_STABLE(ctx, graph_exec,
                                moe_q5_1_down_routed_avx2_reference_kernel,
                                (dim + route_threads - 1) / route_threads,
                                route_threads, 0, out,
                                (const BnBlockQ5_1 *)down->data, mid_q,
                                route, dim, hidden, n_experts, k);
                        } else {
                            BN_CUDA_LAUNCH_STABLE(ctx, graph_exec,
                                moe_q5_1_down_routed_accum_kernel,
                                down_blocks, route_threads, 0,
                                out, (const BnBlockQ5_1 *)down->data, mid,
                                route, dim, hidden, n_experts, k);
                        }
                    } else if ((routed_direct_down || routed_midbit_gateup) &&
                               bn_backend_quant_uses_native_quant(
                                   down_type)) {
                        if (op->flags & BN_GPU_OP_FLAG_MOE_Q8_FLOAT_DOWN) {
                            if (reference_ffn) {
                                if (cuda_ensure_q8_1(ctx, hidden * k) != 0)
                                    BN_CUDA_EXEC_FAIL(
                                        "reference routed moe q8_0 scratch alloc failed");
                                BnCudaBlockQ8_1 *mid_q =
                                    (BnCudaBlockQ8_1 *)ctx->d_q8_1;
                                BN_CUDA_LAUNCH_STABLE(ctx, graph_exec,
                                    quantize_q8_0_avx2_reference_batch_kernel,
                                    dim3(hidden / 32, k, 1), 32, 0,
                                    mid_q, mid, hidden, k);
                                BN_CUDA_LAUNCH_STABLE(ctx, graph_exec,
                                    moe_q8_0_down_routed_avx2_reference_kernel,
                                    (dim + route_threads - 1) / route_threads,
                                    route_threads, 0, out,
                                    (const BnBlockQ8_0 *)down->data, mid_q,
                                    route, dim, hidden, n_experts, k);
                            } else {
                                BN_CUDA_LAUNCH_STABLE(ctx, graph_exec,
                                    moe_q8_0_down_routed_reference_kernel,
                                    (dim + route_threads - 1) / route_threads,
                                    route_threads, 0, out,
                                    (const BnBlockQ8_0 *)down->data, mid,
                                    route, dim, hidden, n_experts, k);
                            }
                        } else {
                            BnCudaBlockQ8_1 *mid_q =
                                (BnCudaBlockQ8_1 *)ctx->d_q8_1;
                            BN_CUDA_LAUNCH_STABLE(ctx, graph_exec,
                                quantize_q8_1_batch_kernel,
                                dim3(hidden / 32, k, 1), 32, 0,
                                mid_q, mid, hidden, k);
                            BN_CUDA_LAUNCH_STABLE(ctx, graph_exec,
                                moe_q8_0_down_routed_q8_1_accum_kernel,
                                down_blocks, route_threads, 0,
                                out, (const BnBlockQ8_0 *)down->data, mid_q,
                                route, dim, hidden, n_experts, k,
                                (op->flags &
                                 BN_GPU_OP_FLAG_MOE_SEPARATE_REDUCTION) != 0,
                                separate_output_scale);
                        }
                    } else if (bn_backend_quant_moe_down_uses_down_kquant(
                                   down_type)) {
                        int use_moe_down_float_path = cuda_use_moe_down_float_path(ctx);
                        int moe_all_active_two_pair_down_enabled =
                            bn_gpu_policy_all_active_two_kquant_moe_down_pair_path_enabled(
                                ctx->runtime_policy);
                        int moe_all_active_two_pair_down_f32_layer =
                            moe_all_active_two_kquant &&
                            down->f32_data &&
                            moe_all_active_two_pair_down_enabled &&
                            !bn_gpu_policy_all_active_two_kquant_moe_down_pair_path_f32_layers_disabled(
                                ctx->runtime_policy) &&
                            bn_gpu_policy_all_active_two_kquant_moe_down_pair_path_f32_layer_selected(
                                ctx->runtime_policy, moe_layer);
                        int moe_all_active_two_ordered_quant_down =
                            moe_all_active_two_kquant &&
                            bn_gpu_policy_all_active_two_kquant_moe_down_ordered_quant_path_enabled(
                                ctx->runtime_policy) &&
                            !bn_gpu_policy_all_active_two_kquant_moe_down_ordered_quant_path_disabled(
                                ctx->runtime_policy);
                        int moe_all_active_two_allow_f32_down_default =
                            !moe_all_active_two_fast_moe_ffn ||
                            bn_gpu_policy_all_active_two_kquant_moe_down_f32_cache_default_enabled(
                                ctx->runtime_policy);
                        int moe_all_active_two_f32_down_default =
                            moe_all_active_two_kquant &&
                            down->f32_data &&
                            !moe_all_active_two_ordered_quant_down &&
                            !moe_all_active_two_pair_down_enabled &&
                            moe_all_active_two_allow_f32_down_default &&
                            !bn_gpu_policy_all_active_two_kquant_moe_down_f32_cache_default_disabled(
                                ctx->runtime_policy);
                        int moe_all_active_two_f32_down =
                            (moe_all_active_two_f32_down_default ||
                             moe_all_active_two_pair_down_f32_layer) &&
                            !bn_gpu_policy_all_active_two_kquant_moe_down_f32_all_active_disabled(
                                ctx->runtime_policy);
                        int moe_all_active_two_disable_pair_down =
                            moe_all_active_two_kquant &&
                            moe_all_active_two_fast_moe_ffn &&
                            !moe_all_active_two_pair_down_enabled;
                        int moe_all_active_two_disable_f32_cache =
                            moe_all_active_two_kquant &&
                            moe_all_active_two_fast_moe_ffn &&
                            !bn_gpu_policy_all_active_two_kquant_moe_down_f32_cache_enabled(
                                ctx->runtime_policy);
                        int use_moe_down_pair_path =
                            cuda_use_moe_down_pair_path(ctx,
                                moe_all_active_two_f32_down_default,
                                moe_all_active_two_pair_down_f32_layer,
                                moe_all_active_two_disable_pair_down);
                        int prefer_moe_down_f32_cache =
                            cuda_prefer_moe_down_f32_cache(ctx,
                                down, hidden, moe_all_active_two_kquant,
                                moe_all_active_two_f32_down);
                        int moe_all_active_two_float_4row_down =
                            moe_all_active_two_kquant &&
                            moe_all_active_two_fast_moe_ffn &&
                            !bn_gpu_policy_all_active_two_kquant_moe_down_float_4row_default_disabled(
                                ctx->runtime_policy) &&
                            !bn_gpu_policy_all_active_two_kquant_moe_down_float_4row_disabled(
                                ctx->runtime_policy);
                        int moe_all_active_two_f32_4row_layer_selected =
                            bn_gpu_policy_all_active_two_kquant_moe_down_f32_4row_layer_selected(
                                ctx->runtime_policy, moe_layer);
                        int moe_all_active_two_f32_4row_down =
                            moe_all_active_two_kquant &&
                            moe_all_active_two_fast_moe_ffn &&
                            down->f32_data &&
                            moe_all_active_two_f32_4row_layer_selected &&
                            !bn_gpu_policy_all_active_two_kquant_moe_down_f32_4row_default_disabled(
                                ctx->runtime_policy) &&
                            !bn_gpu_policy_all_active_two_kquant_moe_down_f32_4row_disabled(
                                ctx->runtime_policy);
                        if (moe_all_active_two_f32_4row_down) {
                            int row4_blocks = (dim + 3) / 4;
                            float skip_eps =
                                bn_gpu_policy_all_active_two_kquant_down_skip_eps_or_default(
                                    ctx->runtime_policy, 1.0e-7f);
                            BN_CUDA_LAUNCH_STABLE(ctx, graph_exec,
                                moe_q6k_down_all_active_two_f32_cache_reference_4row_kernel,
                                row4_blocks, dim3(256, 4, 1), 0,
                                out, (const float *)down->f32_data, mid,
                                route, dim, hidden, skip_eps);
                        } else if (prefer_moe_down_f32_cache &&
                            cuda_use_moe_down_f32_pair2(ctx, n_experts, k)) {
                            if (!cuda_use_moe_down_f32_pair2_4row(ctx)) {
                                BN_CUDA_LAUNCH_STABLE(ctx, graph_exec,
                                    moe_q6k_down_all_active_two_f32_cache_pair2_sum_kernel,
                                    (dim + 1) / 2, dim3(32, 4, 1), 0,
                                    out, (const float *)down->f32_data, mid,
                                    route, dim, hidden);
                            } else {
                                BN_CUDA_LAUNCH_STABLE(ctx, graph_exec,
                                    moe_q6k_down_all_active_two_f32_cache_4row_sum_kernel,
                                    (dim + 3) / 4, dim3(32, 8, 1), 0,
                                    out, (const float *)down->f32_data, mid,
                                    route, dim, hidden);
                            }
                        } else if (prefer_moe_down_f32_cache &&
                            bn_gpu_policy_moe_route_all_active_two(n_experts,
                                                                   k) &&
                            moe_all_active_two_fast_enabled) {
                            BN_CUDA_LAUNCH_STABLE(ctx, graph_exec,
                                moe_q6k_down_all_active_two_f32_cache_warp_kernel,
                                down_blocks, route_threads, 0,
                                out, (const float *)down->f32_data, mid,
                                route, dim, hidden);
                        } else if (prefer_moe_down_f32_cache) {
                            BN_CUDA_LAUNCH_STABLE(ctx, graph_exec,
                                moe_q6k_down_routed_f32_cache_warp_kernel,
                                down_blocks, route_threads, 0,
                                out, (const float *)down->f32_data, mid,
                                route, dim, hidden, n_experts, k);
                        } else if (use_moe_down_pair_path) {
                            int use_all_active_two_down_accum =
                                cuda_use_all_active_two_kquant_moe_down_accum(ctx,
                                    moe_all_active_two_kquant);
                            int use_moe_down_pair4_sum =
                                cuda_use_all_active_two_kquant_moe_down_pair4_sum(ctx,
                                    moe_all_active_two_kquant);
                            int use_moe_down_prepared_native_quant_4row_sum =
                                cuda_use_moe_down_prepared_native_quant_4row_sum(ctx,
                                    moe_all_active_two_kquant, k, hidden);
                            int use_moe_down_prepared_native_quant_8row_sum =
                                cuda_use_moe_down_prepared_native_quant_8row_sum(ctx,
                                    use_moe_down_prepared_native_quant_4row_sum, hidden);
                            if (cuda_ensure_q8_k(ctx, hidden, k) != 0 ||
                                cuda_ensure_prefill(ctx,
                                    (size_t)k * (size_t)dim) != 0)
                                BN_CUDA_EXEC_FAIL(
                                    "routed moe pair down scratch alloc failed");
                            BnBlockQ8K *mid_q = (BnBlockQ8K *)ctx->d_q8_k;
                            float *pair_out = ctx->d_prefill;
                            BN_CUDA_LAUNCH_STABLE(ctx, graph_exec,
                                quantize_q8k_batch_kernel,
                                dim3(hidden / BN_QK_K, k, 1), BN_QK_K, 0,
                                mid_q, mid, hidden, k);
                            BN_CUDA_PREPARED_KQUANT_INPUT_CACHE_INVALIDATE();
                            if (profile_moe_internal) {
                                cudaEventRecord(moe_ev_stop, ctx->exec_stream);
                                cudaEventSynchronize(moe_ev_stop);
                                float ms = 0.0f;
                                cudaEventElapsedTime(&ms, moe_ev_start, moe_ev_stop);
                                profile_ops[BN_CUDA_PROFILE_MOE_MID_QUANT]++;
                                profile_ms[BN_CUDA_PROFILE_MOE_MID_QUANT] += (double)ms;
                                cudaEventRecord(moe_ev_start, ctx->exec_stream);
                            }
                            if (moe_all_active_two_ordered_quant_down) {
                                BN_CUDA_LAUNCH_STABLE(ctx, graph_exec,
                                    moe_q6k_down_routed_q8k_ordered_kernel,
                                    (dim + 127) / 128, 128, 0,
                                    out, (const BnBlockQ6K *)down->data,
                                    mid_q, route, dim, hidden, n_experts, k);
                            } else if (use_moe_down_pair4_sum) {
                                if (cuda_use_all_active_two_kquant_moe_down_fixed(ctx,
                                        moe_all_active_two_kquant)) {
                                    int pair4_sum_blocks =
                                        ((dim + 15) / 16);
                                    BN_CUDA_LAUNCH_STABLE(ctx, graph_exec,
                                        moe_q6k_down_all_active_two_q8k_pair4_sum_fixed_kernel,
                                        pair4_sum_blocks, route_threads, 0,
                                        out, (const BnBlockQ6K *)down->data,
                                        mid_q, route, dim, hidden);
                                } else {
                                    int pair4_sum_blocks =
                                        ((dim + 15) / 16);
                                    BN_CUDA_LAUNCH_STABLE(ctx, graph_exec,
                                        moe_q6k_down_all_active_two_q8k_pair4_sum_kernel,
                                        pair4_sum_blocks, route_threads, 0,
                                        out, (const BnBlockQ6K *)down->data,
                                        mid_q, route, dim, hidden);
                                }
                            } else if (use_moe_down_prepared_native_quant_8row_sum) {
                                BN_CUDA_LAUNCH_STABLE(ctx, graph_exec,
                                    moe_q6k_down_routed_q8k_prepared_native_quant_8row_sum_kernel,
                                    (dim + 7) / 8, route_threads, 0,
                                    out, (const BnBlockQ6K *)down->data,
                                    mid_q, route, dim, hidden,
                                    n_experts, k);
                            } else if (use_moe_down_prepared_native_quant_4row_sum) {
                                int fuse_resid_norm =
                                    cuda_use_moe_down_resid_rmsnorm_fuse(ctx) &&
                                    next &&
                                    next->op_code == BN_GPU_CODE_RESIDUAL_RMSNORM &&
                                    next->buf_in == BN_GPU_VALUE_X &&
                                    next->buf_aux == op->buf_out &&
                                    next->buf_out != op->buf_out &&
                                    dim == (int)next->p[0];
                                BnCudaBuffer *nw = fuse_resid_norm
                                    ? (BnCudaBuffer *)next->W_buf : NULL;
                                float *resid = fuse_resid_norm
                                    ? cuda_act(ctx, next->buf_in) : NULL;
                                float *norm_out = fuse_resid_norm
                                    ? cuda_act(ctx, next->buf_out) : NULL;
                                if (fuse_resid_norm && nw && nw->data &&
                                    resid && norm_out) {
                                    if (cuda_use_moe_down_prepared_native_quant_shape_2048_768(ctx,
                                            dim, hidden, k)) {
                                        BN_CUDA_LAUNCH_STABLE(ctx, graph_exec,
                                            moe_q6k_down_routed_q8k_prepared_native_quant_4row_residual_sum_2048_768_kernel,
                                            dim / 4, route_threads, 0,
                                            resid,
                                            (const BnBlockQ6K *)down->data,
                                            mid_q, route, n_experts);
                                    } else {
                                        BN_CUDA_LAUNCH_STABLE(ctx, graph_exec,
                                            moe_q6k_down_routed_q8k_prepared_native_quant_4row_residual_sum_kernel,
                                            (dim + 3) / 4, route_threads, 0,
                                            resid,
                                            (const BnBlockQ6K *)down->data,
                                            mid_q, route, dim, hidden,
                                            n_experts, k);
                                    }
                                    int norm_threads =
                                        cuda_rmsnorm_threads(dim);
                                    BN_CUDA_LAUNCH_STABLE(ctx, graph_exec,
                                        rmsnorm_kernel, 1, norm_threads,
                                        (size_t)norm_threads * sizeof(float),
                                        norm_out, resid,
                                        (const float *)nw->data, dim,
                                        cuda_u32_to_f32(next->p[1]));
                                    i++;
                                } else {
                                    BN_CUDA_LAUNCH_STABLE(ctx, graph_exec,
                                        moe_q6k_down_routed_q8k_prepared_native_quant_4row_sum_kernel,
                                        (dim + 3) / 4, route_threads, 0,
                                        out, (const BnBlockQ6K *)down->data,
                                        mid_q, route, dim, hidden,
                                        n_experts, k);
                                }
                            } else if (use_all_active_two_down_accum) {
                                if (!cuda_use_all_active_two_kquant_moe_down_accum_4row(ctx)) {
                                    int all_active_two_blocks =
                                        ((dim + 1) / 2 + warps - 1) / warps;
                                    BN_CUDA_LAUNCH_STABLE(ctx, graph_exec,
                                        moe_q6k_down_all_active_two_q8k_accum_2row_kernel,
                                        all_active_two_blocks, route_threads, 0,
                                        out, (const BnBlockQ6K *)down->data,
                                        mid_q, route, dim, hidden);
                                } else {
                                    int all_active_two_blocks =
                                        ((dim + 3) / 4 + warps - 1) / warps;
                                    BN_CUDA_LAUNCH_STABLE(ctx, graph_exec,
                                        moe_q6k_down_all_active_two_q8k_accum_4row_kernel,
                                        all_active_two_blocks, route_threads, 0,
                                        out, (const BnBlockQ6K *)down->data,
                                        mid_q, route, dim, hidden);
                                }
                            } else if (cuda_use_moe_down_prepared_pair_4row(ctx)) {
                                int pair4_blocks =
                                    ((dim + 3) / 4 + warps - 1) / warps;
                                BN_CUDA_LAUNCH_STABLE(ctx, graph_exec,
                                    moe_q6k_down_routed_q8k_pair_4row_kernel,
                                    dim3(pair4_blocks, k, 1),
                                    route_threads, 0,
                                    pair_out,
                                    (const BnBlockQ6K *)down->data,
                                    mid_q, route, dim, hidden,
                                    n_experts, k);
                            } else {
                                int pair_blocks =
                                    ((dim + 7) / 8 + warps - 1) / warps;
                                BN_CUDA_LAUNCH_STABLE(ctx, graph_exec,
                                    moe_q6k_down_routed_q8k_pair_8row_kernel,
                                    dim3(pair_blocks, k, 1),
                                    route_threads, 0,
                                    pair_out,
                                    (const BnBlockQ6K *)down->data,
                                    mid_q, route, dim, hidden,
                                    n_experts, k);
                            }
                            if (!use_moe_down_pair4_sum &&
                                !use_moe_down_prepared_native_quant_4row_sum &&
                                !use_all_active_two_down_accum &&
                                !moe_all_active_two_ordered_quant_down) {
                                BN_CUDA_LAUNCH_STABLE(ctx, graph_exec,
                                    moe_sum_pairs_kernel,
                                    (dim + threads - 1) / threads, threads, 0,
                                    out, pair_out, dim, k);
                            }
                        } else if (cuda_use_moe_down_f32_cache(ctx,
                                       down, moe_all_active_two_disable_f32_cache)) {
                            BN_CUDA_LAUNCH_STABLE(ctx, graph_exec,
                                moe_q6k_down_routed_f32_cache_warp_kernel,
                                down_blocks, route_threads, 0,
                                out, (const float *)down->f32_data, mid,
                                route, dim, hidden, n_experts, k);
                        } else if (cuda_use_moe_down_f16_cache(ctx, down)) {
                            BN_CUDA_LAUNCH_STABLE(ctx, graph_exec,
                                moe_q6k_down_routed_f16_cache_warp_kernel,
                                down_blocks, route_threads, 0,
                                out, (const __half *)down->f16_data, mid,
                                route, dim, hidden, n_experts, k);
                        } else if (moe_all_active_two_float_4row_down &&
                                   use_moe_down_float_path) {
                            int row4_blocks = (dim + 3) / 4;
                            BN_CUDA_LAUNCH_STABLE(ctx, graph_exec,
                                moe_q6k_down_all_active_two_float_accum_4row_kernel,
                                row4_blocks, dim3(256, 4, 1), 0,
                                out, (const BnBlockQ6K *)down->data, mid,
                                route, dim, hidden);
                        } else if (use_moe_down_float_path) {
                            BN_CUDA_LAUNCH_STABLE(ctx, graph_exec,
                                moe_q6k_down_routed_float_accum_row_kernel,
                                dim, route_threads, 0,
                                out, (const BnBlockQ6K *)down->data, mid,
                                route, dim, hidden, n_experts, k);
                        } else {
                            if (cuda_ensure_q8_k(ctx, hidden, k) != 0)
                                return -1;
                            BnBlockQ8K *mid_q = (BnBlockQ8K *)ctx->d_q8_k;
                            BN_CUDA_LAUNCH_STABLE(ctx, graph_exec, quantize_q8k_batch_kernel,
                                dim3(hidden / BN_QK_K, k, 1), BN_QK_K, 0,
                                mid_q, mid, hidden, k);
                            BN_CUDA_PREPARED_KQUANT_INPUT_CACHE_INVALIDATE();
                            BN_CUDA_LAUNCH_STABLE(ctx, graph_exec,
                                moe_q6k_down_routed_q8k_accum_kernel,
                                down_blocks, route_threads, 0,
                                out, (const BnBlockQ6K *)down->data, mid_q,
                                route, dim, hidden, n_experts, k);
                        }
                    } else if (cuda_use_moe_down_aux_f32_cache(ctx, down)) {
                        if (bn_gpu_policy_moe_route_all_active_two(n_experts,
                                                                   k) &&
                            moe_all_active_two_fast_enabled) {
                            BN_CUDA_LAUNCH_STABLE(ctx, graph_exec,
                                moe_q6k_down_all_active_two_f32_cache_4row_sum_kernel,
                                (dim + 3) / 4, dim3(32, 8, 1), 0,
                                out, (const float *)down->f32_data, mid,
                                route, dim, hidden);
                        } else {
                            BN_CUDA_LAUNCH_STABLE(ctx, graph_exec,
                                moe_q6k_down_routed_f32_cache_warp_kernel,
                                down_blocks, route_threads, 0,
                                out, (const float *)down->f32_data, mid,
                                route, dim, hidden, n_experts, k);
                        }
                    } else if (cuda_use_moe_down_prepared_pair8(ctx,
                                   n_experts, k, hidden)) {
                        if (cuda_ensure_q8_k(ctx, hidden, k) != 0 ||
                            cuda_ensure_prefill(ctx,
                                (size_t)k * (size_t)dim) != 0)
                            return -1;
                        BnBlockQ8K *mid_q = (BnBlockQ8K *)ctx->d_q8_k;
                        float *pair_out = ctx->d_prefill;
                        BN_CUDA_LAUNCH_STABLE(ctx, graph_exec,
                            quantize_q8k_batch_kernel,
                            dim3(hidden / BN_QK_K, k, 1), BN_QK_K, 0,
                            mid_q, mid, hidden, k);
                        BN_CUDA_PREPARED_KQUANT_INPUT_CACHE_INVALIDATE();
                        int pair_blocks =
                            ((dim + 7) / 8 + warps - 1) / warps;
                        BN_CUDA_LAUNCH_STABLE(ctx, graph_exec,
                            moe_q4k_down_routed_q8k_pair_8row_kernel,
                            dim3(pair_blocks, k, 1), route_threads, 0,
                            pair_out, (const BnBlockQ4K *)down->data,
                            mid_q, route, dim, hidden, n_experts, k);
                        BN_CUDA_LAUNCH_STABLE(ctx, graph_exec,
                            moe_sum_pairs_kernel,
                            (dim + threads - 1) / threads, threads, 0,
                            out, pair_out, dim, k);
                    } else {
                        if (cuda_ensure_q8_k(ctx, hidden, k) != 0)
                            BN_CUDA_EXEC_FAIL(
                                "routed moe down q8_k scratch alloc failed");
                        BnBlockQ8K *mid_q = (BnBlockQ8K *)ctx->d_q8_k;
                        BN_CUDA_LAUNCH_STABLE(ctx, graph_exec, quantize_q8k_batch_kernel,
                            dim3(hidden / BN_QK_K, k, 1), BN_QK_K, 0,
                            mid_q, mid, hidden, k);
                        BN_CUDA_PREPARED_KQUANT_INPUT_CACHE_INVALIDATE();
                        if (cuda_use_moe_down_prepared_8row(ctx, hidden)) {
                            int down8_blocks =
                                (dim + warps * 8 - 1) / (warps * 8);
                            BN_CUDA_LAUNCH_STABLE(ctx, graph_exec,
                                moe_q4k_down_routed_q8k_accum_8row_kernel,
                                down8_blocks, route_threads, 0,
                                out, (const BnBlockQ4K *)down->data, mid_q,
                                route, dim, hidden, n_experts, k);
                        } else {
                            BN_CUDA_LAUNCH_STABLE(ctx, graph_exec,
                                moe_q4k_down_routed_q8k_accum_kernel,
                                down_blocks, route_threads, 0,
                                out, (const BnBlockQ4K *)down->data, mid_q,
                                route, dim, hidden, n_experts, k);
                        }
                    }
                    if (profile_moe_internal) {
                        cudaEventRecord(moe_ev_stop, ctx->exec_stream);
                        cudaEventSynchronize(moe_ev_stop);
                        float ms = 0.0f;
                        cudaEventElapsedTime(&ms, moe_ev_start, moe_ev_stop);
                        profile_ops[BN_CUDA_PROFILE_MOE_DOWN]++;
                        profile_ms[BN_CUDA_PROFILE_MOE_DOWN] += (double)ms;
                        cudaEventDestroy(moe_ev_start);
                        cudaEventDestroy(moe_ev_stop);
                    }
                }
            }
            break;
        }
        case BN_GPU_CODE_RMSNORM: {
            BnCudaBuffer *w = (BnCudaBuffer *)op->W_buf;
            float *in = cuda_act(ctx, op->buf_in);
