                    weighted_add_sigmoid_residual_rmsnorm_kernel,
                    1, cuda_rmsnorm_threads(n), 0, resid, in, aux,
                    (const float *)gate->data, gate_in, norm_out,
                    (const float *)norm->data, n, dim, (int)op->p[2],
                    (int)op->p[4], cuda_u32_to_f32(next->p[1]));
